package com.danigt.building;

import com.danigt.entity.Player;
import com.danigt.world.World;
import com.danigt.world.WorldRaycaster;

public class BreakTool implements BuildingTool {

    @Override
    public void onLeftClick(World world, Player player, WorldRaycaster.HitResult hit) {
        if (hit != null) {
            world.removeBlock(hit.x, hit.y, hit.z);
        }
    }

    @Override
    public void onRightClick(World world, Player player, WorldRaycaster.HitResult hit) {
        if (hit != null) {
            int px = hit.x + hit.nx;
            int py = hit.y + hit.ny;
            int pz = hit.z + hit.nz;
            if (!world.isSolid(px, py, pz)) {
                world.setBlock(px, py, pz, player.createSelectedBlock());
            }
        }
    }

    @Override
    public void onScroll(World world, Player player, WorldRaycaster.HitResult hit, float delta) {}

    @Override
    public String getName() { return "Break/Place"; }
}


