package com.danigt.building;

import com.danigt.entity.Player;
import com.danigt.world.CrystalBlock;
import com.danigt.world.World;
import com.danigt.world.WorldRaycaster;
import org.joml.Vector3f;

public class ColorPicker implements BuildingTool {

    private float hue = 0f;
    private float saturation = 1f;
    private float brightness = 1f;

    @Override
    public void onLeftClick(World world, Player player, WorldRaycaster.HitResult hit) {
        if (hit != null) {
            CrystalBlock block = world.getBlock(hit.x, hit.y, hit.z);
            if (block != null) {
                Vector3f rgb = hsvToRgb(hue, saturation, brightness);
                block.color.set(rgb);
                int cx = hit.x >> 4, cy = hit.y >> 4, cz = hit.z >> 4;
                for (var chunk : world.getLoadedChunks()) {
                    if (chunk.getChunkX() == cx && chunk.getChunkY() == cy && chunk.getChunkZ() == cz) {
                        chunk.markDirty();
                        break;
                    }
                }
            }
        }
    }

    @Override
    public void onRightClick(World world, Player player, WorldRaycaster.HitResult hit) {}

    @Override
    public void onScroll(World world, Player player, WorldRaycaster.HitResult hit, float delta) {
        hue = (hue + delta * 10) % 360;
        if (hue < 0) hue += 360;
    }

    @Override
    public String getName() { return "Color (H:" + (int)hue + ")"; }

    public float getHue() { return hue; }
    public float getSaturation() { return saturation; }
    public float getBrightness() { return brightness; }

    public Vector3f getCurrentColor() {
        return hsvToRgb(hue, saturation, brightness);
    }

    private static Vector3f hsvToRgb(float h, float s, float v) {
        float c = v * s;
        float x = c * (1 - Math.abs((h / 60) % 2 - 1));
        float m = v - c;
        float r, g, b;
        if (h < 60)       { r = c; g = x; b = 0; }
        else if (h < 120) { r = x; g = c; b = 0; }
        else if (h < 180) { r = 0; g = c; b = x; }
        else if (h < 240) { r = 0; g = x; b = c; }
        else if (h < 300) { r = x; g = 0; b = c; }
        else              { r = c; g = 0; b = x; }
        return new Vector3f(r + m, g + m, b + m);
    }
}


