package com.danigt.building;

import com.danigt.entity.Player;
import com.danigt.world.CrystalBlock;
import com.danigt.world.World;
import com.danigt.world.WorldRaycaster;

public class ResizeTool implements BuildingTool {

    @Override
    public void onLeftClick(World world, Player player, WorldRaycaster.HitResult hit) {}

    @Override
    public void onRightClick(World world, Player player, WorldRaycaster.HitResult hit) {}

    @Override
    public void onScroll(World world, Player player, WorldRaycaster.HitResult hit, float delta) {
        if (hit != null) {
            CrystalBlock block = world.getBlock(hit.x, hit.y, hit.z);
            if (block != null) {
                block.scale = Math.max(0.25f, Math.min(3.0f, block.scale + delta * 0.1f));
                // Force chunk rebuild
                int cx = hit.x >> 4, cy = hit.y >> 4, cz = hit.z >> 4;
                for (var chunk : world.getLoadedChunks()) {
                    if (chunk.getChunkX() == cx && chunk.getChunkY() == cy && chunk.getChunkZ() == cz) {
                        chunk.markDirty();
                        break;
                    }
                }
            }
        }
    }

    @Override
    public String getName() { return "Resize"; }
}


