package com.danigt.building;

import com.danigt.entity.Player;
import com.danigt.world.CrystalBlock;
import com.danigt.world.World;
import com.danigt.world.WorldRaycaster;

public class RotateTool implements BuildingTool {

    @Override
    public void onLeftClick(World world, Player player, WorldRaycaster.HitResult hit) {
        if (hit != null) {
            rotateBlock(world, hit, (float) Math.toRadians(15));
        }
    }

    @Override
    public void onRightClick(World world, Player player, WorldRaycaster.HitResult hit) {
        if (hit != null) {
            rotateBlock(world, hit, (float) Math.toRadians(-15));
        }
    }

    private void rotateBlock(World world, WorldRaycaster.HitResult hit, float angle) {
        CrystalBlock block = world.getBlock(hit.x, hit.y, hit.z);
        if (block != null) {
            block.rotation.rotateY(angle);
            int cx = hit.x >> 4, cy = hit.y >> 4, cz = hit.z >> 4;
            for (var chunk : world.getLoadedChunks()) {
                if (chunk.getChunkX() == cx && chunk.getChunkY() == cy && chunk.getChunkZ() == cz) {
                    chunk.markDirty();
                    break;
                }
            }
        }
    }

    @Override
    public void onScroll(World world, Player player, WorldRaycaster.HitResult hit, float delta) {}

    @Override
    public String getName() { return "Rotate"; }
}


// ===== src/main/java/com/danigt/engine/GameEngine.java =====
package com.danigt.engine;

import com.danigt.building.*;
import com.danigt.entity.CharacterModel;
import com.danigt.entity.DroppedItem;
import com.danigt.entity.Inventory;
import com.danigt.entity.Player;
import com.danigt.entity.PlayerController;
import com.danigt.math.MeshBuilder;
import com.danigt.net.LanDiscovery;
import com.danigt.net.NetworkManager;
import com.danigt.net.RemotePlayer;
import com.danigt.render.Camera;
import com.danigt.render.Light;
import com.danigt.render.Mesh;
import com.danigt.render.ShaderProgram;
import com.danigt.resource.ResourceLoader;
import com.danigt.ui.HUD;
import com.danigt.ui.MainMenu;
import com.danigt.ui.UIRenderer;
import com.danigt.world.*;
import org.joml.Matrix4f;
import org.joml.Vector3f;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import static org.lwjgl.glfw.GLFW.*;
import static org.lwjgl.opengl.GL33.*;

public class GameEngine {

    private enum GameState { LOGIN, MAIN_MENU, PLAYING }
    private GameState gameState = GameState.LOGIN;
    private String currentWorldName;

    private final Window window;
    private final Timer timer;
    private final Input input;

    private ShaderProgram worldShader;
    private Camera camera;
    private Player player;
    private PlayerController controller;
    private World world;
    private Light sunLight;
    private CharacterModel characterModel;
    private UIRenderer uiRenderer;
    private HUD hud;
    private MainMenu mainMenu;
    private com.danigt.ui.LoginScreen loginScreen;
    private LanDiscovery lanDiscovery;

    private final BuildingTool[] tools;
    private float gameTime = 0;

    // UI scale factor for high-res screens
    private float uiScale = 1.0f;

    // Pause menu
    private boolean paused = false;
    private int pauseSelection = 0;
    private static final int PAUSE_ITEMS = 4; // Resume, Host/Disconnect, Join, Quit

    // Block info (hold I)
    private String lookingAtBlockName = "";

    // Inventory screen
    private boolean inventoryOpen = false;

    // Death
    private boolean dead = false;
    private float deathTimer = 0;

    // Chat system
    private boolean chatOpen = false;
    private StringBuilder chatInput = new StringBuilder();
    private final List<String> chatMessages = new ArrayList<>();
    private static final int MAX_CHAT_MESSAGES = 8;
    private float chatFadeTimer = 0;

    // Dropped items
    private final List<DroppedItem> droppedItems = new ArrayList<>();

    // Breaking state
    private Mesh breakOverlayMesh;

    // Cached meshes to avoid per-frame allocation
    private Mesh highlightMesh;
    private final Map<CrystalShape, Mesh> dropItemMeshes = new HashMap<>();

    // Frustum planes for culling
    private final float[][] frustumPlanes = new float[6][4];

    // 3D block icon meshes for inventory/hotbar
    private final Map<CrystalShape, Mesh> iconMeshes = new HashMap<>();

    // Networking
    private final NetworkManager network = new NetworkManager();
    private boolean lanMenuOpen = false;
    private StringBuilder lanIpInput = new StringBuilder();
    private int lanMenuSelection = 0;

    public GameEngine() {
        window = new Window("Crystal Realms", 1280, 720);
        timer = new Timer();
        input = new Input();
        tools = new BuildingTool[]{
            new BreakTool(),
            new ResizeTool(),
            new RotateTool(),
            new ColorPicker()
        };
    }

    public void run() {
        init();
        loop();
        cleanup();
    }

    private void init() {
        window.init();
        input.init(window.getHandle());
        timer.init();

        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glClearColor(0.08f, 0.08f, 0.12f, 1.0f);

        worldShader = new ShaderProgram();
        worldShader.createVertexShader(ResourceLoader.loadResource("/shaders/world_vertex.glsl"));
        worldShader.createFragmentShader(ResourceLoader.loadResource("/shaders/world_fragment.glsl"));
        worldShader.link();

        sunLight = new Light(
            new Vector3f(-0.5f, -1.0f, -0.3f),
            new Vector3f(1.4f, 1.35f, 1.25f),
            new Vector3f(0.45f, 0.45f, 0.5f)
        );

        uiRenderer = new UIRenderer();
        uiRenderer.init();

        com.danigt.ui.ProfileManager.init();
        loginScreen = new com.danigt.ui.LoginScreen();
        mainMenu = new MainMenu();
        mainMenu.refreshWorldList();

        lanDiscovery = new LanDiscovery();
        lanDiscovery.start();

        // Check if already logged in
        window.setCursorGrabbed(false);
        if (com.danigt.ui.ProfileManager.hasActiveProfile()) {
            gameState = GameState.MAIN_MENU;
        } else {
            gameState = GameState.LOGIN;
        }

        setupCallbacks();
    }

    private void startWorld(String worldName, long seed) {
        currentWorldName = worldName;

        camera = new Camera();
        player = new Player();
        String username = com.danigt.ui.ProfileManager.getCurrentUsername();
        if (username != null) player.name = username;
        controller = new PlayerController(player, camera);

        world = new World(seed, 4);
        world.setWorldName(worldName);

        characterModel = new CharacterModel();
        hud = new HUD(uiRenderer);

        // Try loading saved player data
        WorldSaveManager.WorldLoadResult loaded = WorldSaveManager.load(worldName);
        if (loaded != null && loaded.hasPlayer) {
            player.position.set(loaded.px, loaded.py, loaded.pz);
            player.yaw = loaded.yaw;
            player.pitch = loaded.pitch;
            player.health = loaded.health;
            player.stamina = loaded.stamina;
            player.creative = loaded.creative;
            player.flying = loaded.flying;
            player.selectedSlot = loaded.selectedSlot;
            for (int i = 0; i < Player.HOTBAR_SIZE; i++) player.hotbar[i] = loaded.hotbar[i];
            player.inventory.clear();
            for (int i = 0; i < Inventory.SIZE; i++) {
                if (loaded.invShapes[i] != null) {
                    player.inventory.getSlot(i).shape = loaded.invShapes[i];
                    player.inventory.getSlot(i).count = loaded.invCounts[i];
                }
            }
        }

        // Generate initial chunks
        world.update(player.position.x, player.position.y, player.position.z);

        // Find ground if no saved position
        if (loaded == null || !loaded.hasPlayer) {
            for (int y = 80; y > 0; y--) {
                if (world.isSolid((int) player.position.x, y, (int) player.position.z)) {
                    player.position.y = y + 2;
                    break;
                }
            }
        }

        glClearColor(0.45f, 0.55f, 0.75f, 1.0f);
        window.setCursorGrabbed(true);
        gameState = GameState.PLAYING;

        // Reset gameplay state
        paused = false;
        inventoryOpen = false;
        chatOpen = false;
        dead = false;
        chatMessages.clear();
        droppedItems.clear();
    }

    private void returnToMenu() {
        // Save world
        if (world != null && currentWorldName != null) {
            WorldSaveManager.save(currentWorldName, world, player);
        }

        // Disconnect network
        if (network.isOnline()) {
            network.disconnect();
        }

        // Cleanup gameplay objects
        if (world != null) { world.cleanup(); world = null; }
        if (characterModel != null) { characterModel.cleanup(); characterModel = null; }
        for (Mesh m : iconMeshes.values()) m.cleanup();
        iconMeshes.clear();
        for (Mesh m : dropItemMeshes.values()) if (m != null) m.cleanup();
        dropItemMeshes.clear();
        if (highlightMesh != null) { highlightMesh.cleanup(); highlightMesh = null; }
        if (breakOverlayMesh != null) { breakOverlayMesh.cleanup(); breakOverlayMesh = null; }
        player = null;
        camera = null;
        controller = null;
        hud = null;
        droppedItems.clear();
        chatMessages.clear();

        currentWorldName = null;
        paused = false;
        glClearColor(0.08f, 0.08f, 0.12f, 1.0f);
        window.setCursorGrabbed(false);
        gameState = GameState.MAIN_MENU;
        mainMenu.refreshWorldList();
    }

    private void setupCallbacks() {
        glfwSetKeyCallback(window.getHandle(), (w, key, scancode, action, mods) -> {
            // Login screen input
            if (gameState == GameState.LOGIN) {
                if (action == GLFW_PRESS || action == GLFW_REPEAT) {
                    loginScreen.onKey(key, action, mods);
                }
                return;
            }
            // Main menu input
            if (gameState == GameState.MAIN_MENU) {
                if (action == GLFW_PRESS || action == GLFW_REPEAT) {
                    mainMenu.onKey(key, action, mods);
                }
                return;
            }

            // Gameplay input
            if (chatOpen) {
                if (action == GLFW_PRESS || action == GLFW_REPEAT) {
                    if (key == GLFW_KEY_ESCAPE) {
                        chatOpen = false;
                        chatInput.setLength(0);
                        window.setCursorGrabbed(true);
                    } else if (key == GLFW_KEY_ENTER) {
                        if (chatInput.length() > 0) {
                            processChat(chatInput.toString());
                            chatInput.setLength(0);
                        }
                        chatOpen = false;
                        window.setCursorGrabbed(true);
                    } else if (key == GLFW_KEY_BACKSPACE && chatInput.length() > 0) {
                        chatInput.deleteCharAt(chatInput.length() - 1);
                    }
                }
                return;
            }
            if (key == GLFW_KEY_ESCAPE && action == GLFW_PRESS) {
                if (inventoryOpen) {
                    toggleInventory();
                } else {
                    togglePause();
                }
                return;
            }
            if (key == GLFW_KEY_V && action == GLFW_PRESS && !paused && !dead) {
                toggleInventory();
                return;
            }
            if ((key == GLFW_KEY_SLASH || key == GLFW_KEY_ENTER) && action == GLFW_PRESS && !paused && !dead && !inventoryOpen) {
                chatOpen = true;
                chatInput.setLength(0);
                if (key == GLFW_KEY_SLASH) chatInput.append('/');
                window.setCursorGrabbed(false);
                return;
            }
            if (action == GLFW_PRESS) {
                input.setKey(key, true);
            } else if (action == GLFW_RELEASE) {
                input.setKey(key, false);
            }
        });

        glfwSetCharCallback(window.getHandle(), (w, codepoint) -> {
            if (gameState == GameState.LOGIN) {
                loginScreen.onChar(codepoint);
                return;
            }
            if (gameState == GameState.MAIN_MENU) {
                mainMenu.onChar(codepoint);
                return;
            }
            if (chatOpen && codepoint >= 32 && codepoint < 127) {
                chatInput.append((char) codepoint);
            } else if (lanMenuOpen && codepoint >= 32 && codepoint < 127) {
                lanIpInput.append((char) codepoint);
            }
        });
    }

    private void togglePause() {
        paused = !paused;
        pauseSelection = 0;
        window.setCursorGrabbed(!paused);
    }

    private void toggleInventory() {
        inventoryOpen = !inventoryOpen;
        window.setCursorGrabbed(!inventoryOpen);
    }

    private double getMouseFBX() { return input.getMouseX() * window.getContentScaleX(); }
    private double getMouseFBY() { return input.getMouseY() * window.getContentScaleY(); }

    private void loop() {
        while (!window.shouldClose()) {
            window.pollEvents();
            timer.update();
            float dt = timer.getDeltaTime();
            gameTime += dt;

            // Update UI scale based on screen height (base: 720p)
            uiScale = Math.max(1.0f, window.getHeight() / 720.0f);

            if (gameState == GameState.LOGIN) {
                com.danigt.ui.LoginScreen.LoginResult loginResult = loginScreen.update(dt, input, window);
                if (loginResult == com.danigt.ui.LoginScreen.LoginResult.SUCCESS) {
                    gameState = GameState.MAIN_MENU;
                    mainMenu.refreshWorldList();
                }
                renderLoginScreen();
            } else if (gameState == GameState.MAIN_MENU) {
                lanDiscovery.update();
                mainMenu.setLanServers(lanDiscovery.getServers());
                MainMenu.Result menuResult = mainMenu.update(dt, input, window);
                handleMenuResult(menuResult);
                renderMainMenu();
            } else {
                // Fade out chat messages
                if (chatFadeTimer > 0) chatFadeTimer -= dt;

                // Network update
                if (network.isOnline()) {
                    network.update(dt, player, world);
                    for (String msg : network.drainChatMessages()) {
                        addChatMessage(msg);
                    }
                }

                if (dead) {
                    updateDeath(dt);
                } else if (chatOpen) {
                    // Don't update game while typing
                } else if (paused) {
                    updatePauseMenu();
                } else if (inventoryOpen) {
                    updateInventory();
                } else {
                    update(dt);
                    // Check for death
                    if (player.isDead() && !player.creative) {
                        dead = true;
                        deathTimer = 0;
                    }
                }
                if (gameState == GameState.PLAYING) {
                    render();
                } else {
                    // Switched to menu mid-frame (e.g. Save & Quit)
                    renderMainMenu();
                }
            }

            window.swapBuffers();
            input.update();
        }
    }

    private void handleMenuResult(MainMenu.Result result) {
        switch (result.action) {
            case LOAD_WORLD -> startWorld(result.worldName, result.seed);
            case CREATE_WORLD -> startWorld(result.worldName, result.seed);
            case JOIN_SERVER -> {
                // Create a temp world, join the server
                startWorld("_multiplayer", System.currentTimeMillis());
                network.setPlayerName(player.name);
                boolean ok = network.joinGame(result.serverIp, result.serverPort);
                if (!ok) {
                    addChatMessage("[System] Failed to connect");
                }
            }
            case DELETE_WORLD -> {
                WorldSaveManager.deleteWorld(result.worldName);
                mainMenu.refreshWorldList();
            }
            case LOGOUT -> {
                com.danigt.ui.ProfileManager.logout();
                loginScreen = new com.danigt.ui.LoginScreen();
                gameState = GameState.LOGIN;
            }
            case NONE -> {}
        }
    }

    private void renderLoginScreen() {
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
        int sw = window.getWidth();
        int sh = window.getHeight();
        loginScreen.render(sw, sh, uiRenderer, uiScale);
    }

    private void renderMainMenu() {
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
        int sw = window.getWidth();
        int sh = window.getHeight();
        mainMenu.render(sw, sh, uiRenderer, uiScale);
    }

    private void updatePauseMenu() {
        if (lanMenuOpen) {
            updateLanMenu();
            return;
        }
        if (input.isKeyPressed(GLFW_KEY_W) || input.isKeyPressed(GLFW_KEY_UP)) {
            pauseSelection = (pauseSelection - 1 + PAUSE_ITEMS) % PAUSE_ITEMS;
        }
        if (input.isKeyPressed(GLFW_KEY_S) || input.isKeyPressed(GLFW_KEY_DOWN)) {
            pauseSelection = (pauseSelection + 1) % PAUSE_ITEMS;
        }
        if (input.isKeyPressed(GLFW_KEY_ENTER) || input.isKeyPressed(GLFW_KEY_SPACE)) {
            executePauseAction(pauseSelection);
        }
        if (input.isButtonPressed(0)) {
            int screenW = window.getWidth();
            int screenH = window.getHeight();
            double mx = getMouseFBX();
            double my = getMouseFBY();
            float u = uiScale;
            float btnW = 240 * u, btnH = 40 * u;
            float btnX = (screenW - btnW) / 2f;
            float startY = screenH / 2f - 40 * u;
            for (int i = 0; i < PAUSE_ITEMS; i++) {
                float btnY = startY + i * (btnH + 12 * u);
                if (mx >= btnX && mx <= btnX + btnW && my >= btnY && my <= btnY + btnH) {
                    executePauseAction(i);
                }
            }
        }
    }

    private void executePauseAction(int action) {
        if (action == 0) { // Resume
            togglePause();
        } else if (action == 1) { // Host LAN / Disconnect
            if (network.isOnline()) {
                network.disconnect();
                addChatMessage("[System] Disconnected from LAN");
            } else {
                network.setPlayerName(player.name);
                network.setWorldName(currentWorldName != null ? currentWorldName : "World");
                boolean ok = network.hostGame(25565, world.getSeed());
                if (ok) {
                    addChatMessage("[System] Hosting LAN on port 25565");
                }
                togglePause();
            }
        } else if (action == 2) { // Join LAN
            if (!network.isOnline()) {
                lanMenuOpen = true;
                lanIpInput.setLength(0);
                lanIpInput.append("localhost");
            }
        } else if (action == 3) { // Save & Quit to Menu
            returnToMenu();
        }
    }

    private void updateLanMenu() {
        if (input.isKeyPressed(GLFW_KEY_ESCAPE)) {
            lanMenuOpen = false;
            return;
        }
        if (input.isKeyPressed(GLFW_KEY_ENTER)) {
            String ip = lanIpInput.toString().trim();
            if (!ip.isEmpty()) {
                network.setPlayerName(player.name);
                boolean ok = network.joinGame(ip, 25565);
                if (ok) {
                    addChatMessage("[System] Connecting to " + ip + "...");
                    // Wait briefly for welcome packet with seed
                    // The world will be regenerated when seed arrives
                } else {
                    addChatMessage("[System] Failed to connect to " + ip);
                }
            }
            lanMenuOpen = false;
            togglePause();
            return;
        }
        if (input.isKeyPressed(GLFW_KEY_BACKSPACE) && lanIpInput.length() > 0) {
            lanIpInput.deleteCharAt(lanIpInput.length() - 1);
        }
    }

    private void update(float dt) {
        if (window.isResized()) {
            glViewport(0, 0, window.getWidth(), window.getHeight());
        }

        controller.update(input, world, dt);
        world.update(player.position.x, player.position.y, player.position.z);

        // Void kill
        if (player.position.y < -10 && !player.creative) {
            player.health = 0;
        }

        // Raycast
        float reach = player.creative ? 64f : 8f;
        WorldRaycaster.HitResult hit = WorldRaycaster.raycast(
            world, camera.getPosition(), camera.getForward(), reach
        );

        BuildingTool currentTool = tools[player.currentToolIndex];

        // ====== Block breaking (hold left click) ======
        if (input.isButtonDown(0) && hit != null) {
            CrystalBlock targetBlock = world.getBlock(hit.x, hit.y, hit.z);
            if (targetBlock != null) {
                if (player.creative) {
                    // Creative: instant break
                    if (input.isButtonPressed(0)) {
                        Vector3f dropColor = getBlockDropColor(targetBlock);
                        world.removeBlock(hit.x, hit.y, hit.z);
                        if (network.isOnline()) network.sendBlockRemove(hit.x, hit.y, hit.z);
                        spawnDrop(targetBlock.shape, dropColor, hit.x, hit.y, hit.z);
                    }
                } else {
                    // Survival: progressive breaking
                    if (player.breakingX != hit.x || player.breakingY != hit.y || player.breakingZ != hit.z) {
                        // Looking at a new block, reset progress
                        player.breakingX = hit.x;
                        player.breakingY = hit.y;
                        player.breakingZ = hit.z;
                        player.breakProgress = 0;
                    }
                    player.isBreaking = true;
                    float hardness = targetBlock.shape.hardness;
                    player.breakProgress += dt / hardness;

                    if (player.breakProgress >= 1.0f) {
                        // Block broken!
                        Vector3f dropColor = getBlockDropColor(targetBlock);
                        world.removeBlock(hit.x, hit.y, hit.z);
                        if (network.isOnline()) network.sendBlockRemove(hit.x, hit.y, hit.z);
                        spawnDrop(targetBlock.shape, dropColor, hit.x, hit.y, hit.z);
                        player.breakProgress = 0;
                        player.isBreaking = false;
                        player.breakingX = Integer.MIN_VALUE;
                    }
                }
            }
        } else {
            // Not holding left click or no target - reset breaking
            if (player.isBreaking) {
                player.breakProgress = 0;
                player.isBreaking = false;
                player.breakingX = Integer.MIN_VALUE;
            }
        }

        // Right click: place block
        if (input.isButtonPressed(1) && hit != null) {
            int px = hit.x + hit.nx;
            int py = hit.y + hit.ny;
            int pz = hit.z + hit.nz;
            if (!world.isSolid(px, py, pz)) {
                CrystalShape shape = player.getSelectedShape();
                if (player.creative || player.inventory.has(shape)) {
                    CrystalBlock placed = player.createSelectedBlock();
                    world.setBlock(px, py, pz, placed);
                    if (network.isOnline()) network.sendBlockChange(px, py, pz, placed);
                    if (!player.creative) {
                        player.inventory.remove(shape);
                    }
                }
            }
        }

        // Scroll for other tools
        double scroll = input.getScrollDY();
        if (scroll != 0) {
            currentTool.onScroll(world, player, hit, (float) scroll);
        }

        // Block info when holding I
        if (input.isKeyDown(GLFW_KEY_I)) {
            com.danigt.world.Biome currentBiome = world.getGenerator().getBiome(
                (int) player.position.x, (int) player.position.z);
            String biomeStr = "[" + currentBiome.displayName + "] ";
            if (hit != null) {
                CrystalBlock block = world.getBlock(hit.x, hit.y, hit.z);
                if (block != null) {
                    lookingAtBlockName = biomeStr + block.shape.name() + " (" + hit.x + ", " + hit.y + ", " + hit.z + ")";
                } else {
                    lookingAtBlockName = biomeStr + "AIR";
                }
            } else {
                lookingAtBlockName = biomeStr + "AIR (TOO FAR)";
            }
        } else {
            lookingAtBlockName = "";
        }

        // Update dropped items
        Iterator<DroppedItem> it = droppedItems.iterator();
        while (it.hasNext()) {
            DroppedItem item = it.next();
            int blockBelow = (int) Math.floor(item.position.y - 0.2f);
            boolean groundSolid = world.isSolid(
                (int) Math.floor(item.position.x),
                blockBelow,
                (int) Math.floor(item.position.z)
            );
            if (item.update(dt, player, groundSolid)) {
                it.remove();
            }
        }

        boolean walking = player.velocity.x != 0 || player.velocity.z != 0;
        characterModel.update(dt, walking);
    }

    private Vector3f getBlockDropColor(CrystalBlock block) {
        return new Vector3f(block.shape.defaultColor);
    }

    private void spawnDrop(CrystalShape shape, Vector3f color, int x, int y, int z) {
        droppedItems.add(new DroppedItem(shape, color, x, y, z));
    }

    private void render() {
        // === Day/Night Cycle ===
        float dayPhase = (gameTime % 600.0f) / 600.0f; // 10 min cycle
        float sunAngle = dayPhase * (float)(2.0 * Math.PI);

        // Sun direction rotates through the sky
        float sx = -(float)Math.cos(sunAngle);
        float sy = -(float)Math.abs(Math.sin(sunAngle));
        sunLight.setDirection(new Vector3f(sx, sy, -0.3f));

        // Light color & ambient by time of day
        Vector3f dayColor = new Vector3f(1.4f, 1.35f, 1.25f);
        Vector3f dawnColor = new Vector3f(1.0f, 0.6f, 0.3f);
        Vector3f nightColor = new Vector3f(0.15f, 0.15f, 0.25f);
        Vector3f dayAmbient = new Vector3f(0.45f, 0.45f, 0.5f);
        Vector3f nightAmbient = new Vector3f(0.08f, 0.08f, 0.12f);

        // Sky colors
        Vector3f daySky = new Vector3f(0.45f, 0.55f, 0.75f);
        Vector3f dawnSky = new Vector3f(0.8f, 0.5f, 0.3f);
        Vector3f nightSky = new Vector3f(0.02f, 0.02f, 0.06f);

        Vector3f lc, ac, sc;
        if (dayPhase < 0.1f) {
            // Dawn: orange → bright
            float t = dayPhase / 0.1f;
            lc = new Vector3f(dawnColor).lerp(dayColor, t);
            ac = new Vector3f(nightAmbient).lerp(dayAmbient, t);
            sc = new Vector3f(dawnSky).lerp(daySky, t);
        } else if (dayPhase < 0.4f) {
            // Day: bright
            lc = new Vector3f(dayColor);
            ac = new Vector3f(dayAmbient);
            sc = new Vector3f(daySky);
        } else if (dayPhase < 0.5f) {
            // Dusk: bright → orange → dark
            float t = (dayPhase - 0.4f) / 0.1f;
            lc = new Vector3f(dayColor).lerp(dawnColor, t);
            ac = new Vector3f(dayAmbient).lerp(nightAmbient, t);
            sc = new Vector3f(daySky).lerp(dawnSky, t);
        } else if (dayPhase < 0.55f) {
            // Dusk→Night transition
            float t = (dayPhase - 0.5f) / 0.05f;
            lc = new Vector3f(dawnColor).lerp(nightColor, t);
            ac = new Vector3f(nightAmbient);
            sc = new Vector3f(dawnSky).lerp(nightSky, t);
        } else if (dayPhase < 0.9f) {
            // Night: moonlight
            lc = new Vector3f(nightColor);
            ac = new Vector3f(nightAmbient);
            sc = new Vector3f(nightSky);
        } else {
            // Pre-dawn: moonlight → orange
            float t = (dayPhase - 0.9f) / 0.1f;
            lc = new Vector3f(nightColor).lerp(dawnColor, t);
            ac = new Vector3f(nightAmbient).lerp(nightAmbient, t); // stays dim until dawn
            sc = new Vector3f(nightSky).lerp(dawnSky, t);
        }

        sunLight.setColor(lc);
        sunLight.setAmbient(ac);
        glClearColor(sc.x, sc.y, sc.z, 1.0f);

        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        float aspect = (float) window.getWidth() / window.getHeight();
        Matrix4f projection = camera.getProjectionMatrix(aspect);
        Matrix4f view = camera.getViewMatrix();

        worldShader.bind();
        worldShader.setUniform("projection", projection);
        worldShader.setUniform("view", view);
        worldShader.setUniform("lightDir", sunLight.getDirection());
        worldShader.setUniform("lightColor", sunLight.getColor());
        worldShader.setUniform("ambientColor", sunLight.getAmbient());
        worldShader.setUniform("viewPos", camera.getPosition());
        worldShader.setUniform("gameTime", gameTime);

        Matrix4f identity = new Matrix4f();
        worldShader.setUniform("model", identity);

        // Frustum culling
        Matrix4f vp = new Matrix4f();
        projection.mul(view, vp);
        extractFrustumPlanes(vp);

        // Enable blending for leaves transparency
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);

        for (Chunk chunk : world.getLoadedChunks()) {
            Mesh mesh = chunk.getMesh();
            if (mesh != null && isChunkVisible(chunk)) {
                mesh.render();
            }
        }

        glDisable(GL_BLEND);

        // Render character model in third person
        if (camera.isThirdPerson()) {
            Mesh charMesh = characterModel.getMesh();
            if (charMesh != null) {
                Matrix4f charModel = new Matrix4f()
                    .translate(player.position.x, player.position.y, player.position.z)
                    .rotateY((float) Math.toRadians(-player.yaw - 90));
                worldShader.setUniform("model", charModel);
                charMesh.render();
            }
        }

        // Render remote players
        for (RemotePlayer rp : network.getRemotePlayers()) {
            Mesh rpMesh = rp.model.getMesh();
            if (rpMesh != null) {
                Matrix4f rpModel = new Matrix4f()
                    .translate(rp.position.x, rp.position.y, rp.position.z)
                    .rotateY((float) Math.toRadians(-rp.yaw - 90));
                worldShader.setUniform("model", rpModel);
                rpMesh.render();
            }
        }

        // Render dropped items
        renderDroppedItems();

        // Block highlight
        float reach = player.creative ? 64f : 8f;
        WorldRaycaster.HitResult hit = WorldRaycaster.raycast(
            world, camera.getPosition(), camera.getForward(), reach
        );
        if (hit != null) {
            renderBlockHighlight(hit, projection, view);

            // Breaking overlay
            if (player.isBreaking && player.breakProgress > 0 &&
                hit.x == player.breakingX && hit.y == player.breakingY && hit.z == player.breakingZ) {
                renderBreakOverlay(hit, player.breakProgress);
            }
        }

        worldShader.unbind();

        // HUD
        int sw = window.getWidth();
        int sh = window.getHeight();
        hud.render(sw, sh, player, tools[player.currentToolIndex], timer.getFps(),
                   lookingAtBlockName, uiRenderer, uiScale);
        // Render 3D block icons for hotbar
        flush3DBlockIcons(sw, sh);

        if (inventoryOpen) {
            renderInventory(sw, sh);
            // Render 3D block icons for inventory
            flush3DBlockIcons(sw, sh);
        }

        // Chat overlay (render before death/pause so it's visible)
        renderChat(sw, sh);

        if (dead) {
            renderDeathScreen(sw, sh);
        }

        if (paused) {
            renderPauseMenu(sw, sh);
        }
    }

    private Mesh getDropItemMesh(CrystalShape shape, org.joml.Vector3f color) {
        // Cache per shape (color is baked into vertex data so we use shape as key)
        return dropItemMeshes.computeIfAbsent(shape, s -> {
            MeshBuilder mb = new MeshBuilder();
            mb.addCrystal(new CrystalBlock(s, color), 0, 0, 0);
            return mb.build();
        });
    }

    private void renderDroppedItems() {
        for (DroppedItem item : droppedItems) {
            Mesh dropMesh = getDropItemMesh(item.shape, item.color);
            if (dropMesh != null) {
                float s = item.getScale();
                float bob = item.getBobOffset();
                Matrix4f model = new Matrix4f()
                    .translate(item.position.x - s / 2, item.position.y + bob - s / 2, item.position.z - s / 2)
                    .rotateY((float) Math.toRadians(item.getSpinAngle()))
                    .scale(s);
                worldShader.setUniform("model", model);
                dropMesh.render();
            }
        }
        // Reset model matrix
        worldShader.setUniform("model", new Matrix4f());
    }

    private void renderBreakOverlay(WorldRaycaster.HitResult hit, float progress) {
        // Draw a semi-transparent dark overlay on the block being broken, scaling with progress
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
        glDepthMask(false);

        // Dark cracking overlay — use crack lines by darkening the block
        float alpha = progress * 0.6f;
        float[] pos = CrystalShape.GRASS.getVertices(); // just need a cube
        float[] norms = CrystalShape.GRASS.getNormals();
        float[] cols = new float[24 * 4]; // 24 verts * vec4
        for (int i = 0; i < 24; i++) {
            cols[i * 4] = 0;
            cols[i * 4 + 1] = 0;
            cols[i * 4 + 2] = 0;
            cols[i * 4 + 3] = -2; // special blockType to signal override
        }
        int[] idx = CrystalShape.GRASS.getIndices();

        if (breakOverlayMesh != null) breakOverlayMesh.cleanup();
        breakOverlayMesh = new Mesh(pos, norms, cols, idx);

        // Slightly larger than the block to avoid z-fighting
        Matrix4f model = new Matrix4f()
            .translate(hit.x - 0.005f, hit.y - 0.005f, hit.z - 0.005f)
            .scale(1.01f);
        worldShader.setUniform("model", model);
        breakOverlayMesh.render();

        glDepthMask(true);
        glDisable(GL_BLEND);
        glEnable(GL_CULL_FACE);
    }

    private void renderPauseMenu(int screenW, int screenH) {
        uiRenderer.begin(screenW, screenH);
        float u = uiScale;

        uiRenderer.drawRect(0, 0, screenW, screenH, 0, 0, 0, 0.6f);

        float titleScale = 4 * u;
        String title = "PAUSED";
        float titleW = uiRenderer.textWidth(title, titleScale);
        uiRenderer.drawTextWithShadow(title, (screenW - titleW) / 2f, screenH / 2f - 120 * u, titleScale,
            1f, 1f, 1f, 1f);

        // Status line
        if (network.isOnline()) {
            String status = network.isHosting() ? "HOSTING LAN (" + network.getPlayerCount() + " players)"
                                                 : "CONNECTED (" + network.getPlayerCount() + " players)";
            float sScale = 2 * u;
            float sW = uiRenderer.textWidth(status, sScale);
            uiRenderer.drawTextWithShadow(status, (screenW - sW) / 2f, screenH / 2f - 80 * u, sScale,
                0.3f, 1f, 0.5f, 1f);
        }

        String hostLabel = network.isOnline() ? "DISCONNECT" : "HOST LAN";
        String[] items = {"RESUME", hostLabel, "JOIN LAN", "SAVE AND QUIT"};
        float btnW = 240 * u, btnH = 40 * u;
        float btnX = (screenW - btnW) / 2f;
        float startY = screenH / 2f - 40 * u;
        float textScale = 3 * u;

        for (int i = 0; i < items.length; i++) {
            float btnY = startY + i * (btnH + 12 * u);
            boolean selected = i == pauseSelection;
            boolean disabled = (i == 2 && network.isOnline()); // Can't join if already online

            if (disabled) {
                uiRenderer.drawRect(btnX, btnY, btnW, btnH, 0.25f, 0.25f, 0.25f, 0.5f);
            } else if (selected) {
                uiRenderer.drawRect(btnX - 3 * u, btnY - 3 * u, btnW + 6 * u, btnH + 6 * u, 1f, 0.85f, 0.2f, 0.9f);
                uiRenderer.drawRect(btnX, btnY, btnW, btnH, 0.3f, 0.5f, 0.8f, 0.9f);
            } else {
                uiRenderer.drawRect(btnX, btnY, btnW, btnH, 0.4f, 0.4f, 0.4f, 0.8f);
            }

            float tw = uiRenderer.textWidth(items[i], textScale);
            float tx = btnX + (btnW - tw) / 2f;
            float ty = btnY + (btnH - 5 * textScale) / 2f;
            float alpha = disabled ? 0.4f : 1f;
            uiRenderer.drawTextWithShadow(items[i], tx, ty, textScale, 1f, 1f, 1f, alpha);
        }

        // LAN IP input overlay
        if (lanMenuOpen) {
            float boxW = 300 * u, boxH = 80 * u;
            float boxX = (screenW - boxW) / 2f;
            float boxY = screenH / 2f - boxH / 2f;
            uiRenderer.drawRect(boxX, boxY, boxW, boxH, 0.1f, 0.1f, 0.15f, 0.95f);
            uiRenderer.drawRect(boxX, boxY, boxW, 3 * u, 0.3f, 0.8f, 1f, 0.9f);

            float lScale = 2.5f * u;
            uiRenderer.drawTextWithShadow("ENTER IP ADDRESS:", boxX + 10 * u, boxY + 10 * u, lScale,
                0.7f, 0.7f, 0.8f, 1f);

            // Input field
            float inputY = boxY + 35 * u;
            uiRenderer.drawRect(boxX + 10 * u, inputY, boxW - 20 * u, 30 * u, 0.2f, 0.2f, 0.22f, 0.9f);
            String ipDisplay = lanIpInput.toString();
            if ((int)(gameTime * 2) % 2 == 0) ipDisplay += "_";
            uiRenderer.drawTextWithShadow(ipDisplay, boxX + 15 * u, inputY + 8 * u, 2.5f * u, 1f, 1f, 1f, 1f);
        }

        float hintScale = 2 * u;
        String hint = lanMenuOpen ? "ENTER TO CONNECT, ESC TO CANCEL" : "W/S TO SELECT, ENTER TO CONFIRM";
        float hintW = uiRenderer.textWidth(hint, hintScale);
        uiRenderer.drawTextWithShadow(hint, (screenW - hintW) / 2f, startY + PAUSE_ITEMS * (btnH + 12 * u) + 20 * u,
            hintScale, 0.7f, 0.7f, 0.7f, 0.8f);

        uiRenderer.end();
    }

    private int inventoryScroll = 0;

    private void updateInventory() {
        if (player.creative) {
            updateCreativeInventory();
        } else {
            updateSurvivalInventory();
        }
    }

    private void updateCreativeInventory() {
        // Scroll through creative menu
        double scroll = input.getScrollDY();
        if (scroll != 0) {
            inventoryScroll -= (int) scroll;
            if (inventoryScroll < 0) inventoryScroll = 0;
        }

        // Click to assign block to selected hotbar slot
        if (input.isButtonPressed(0)) {
            double mx = getMouseFBX();
            double my = getMouseFBY();
            int screenW = window.getWidth();
            int screenH = window.getHeight();

            CrystalShape[] allShapes = CrystalShape.values();
            float slotSize = 44 * uiScale;
            float pad = 4 * uiScale;
            int cols = 9;
            float panelW = cols * (slotSize + pad) + pad + 20 * uiScale;
            float panelH = screenH * 0.75f;
            float panelX = (screenW - panelW) / 2f;
            float panelY = (screenH - panelH) / 2f;
            float gridX = panelX + 10 * uiScale + pad;
            float gridY = panelY + 40 * uiScale;

            // Check all blocks grid
            for (int idx = 0; idx < allShapes.length; idx++) {
                int row = idx / cols;
                int col = idx % cols;
                float sx = gridX + col * (slotSize + pad);
                float sy = gridY + (row - inventoryScroll) * (slotSize + pad);
                if (sy < gridY - slotSize || sy > panelY + panelH - 80 * uiScale) continue;
                if (mx >= sx && mx <= sx + slotSize && my >= sy && my <= sy + slotSize) {
                    player.hotbar[player.selectedSlot] = allShapes[idx];
                    return;
                }
            }

            // Check hotbar slots
            float hotbarY = panelY + panelH - 65 * uiScale;
            for (int i = 0; i < Player.HOTBAR_SIZE; i++) {
                float sx = gridX + i * (slotSize + pad);
                if (mx >= sx && mx <= sx + slotSize && my >= hotbarY && my <= hotbarY + slotSize) {
                    player.selectedSlot = i;
                    return;
                }
            }
        }
    }

    private void updateSurvivalInventory() {
        if (!input.isButtonPressed(0)) return;
        double mx = getMouseFBX();
        double my = getMouseFBY();
        int screenW = window.getWidth();
        int screenH = window.getHeight();

        float slotSize = 44 * uiScale;
        float pad = 4 * uiScale;
        int cols = 9;
        float panelW = cols * (slotSize + pad) + pad + 20 * uiScale;
        int invRows = (Inventory.SIZE + cols - 1) / cols;
        float panelH = (invRows + 2) * (slotSize + pad) + 100 * uiScale;
        float panelX = (screenW - panelW) / 2f;
        float panelY = (screenH - panelH) / 2f;
        float gridX = panelX + 10 * uiScale + pad;
        float gridY = panelY + 40 * uiScale + 16 * uiScale;

        // Click inventory slot → assign to hotbar if it has items
        for (int i = 0; i < Inventory.SIZE; i++) {
            int row = i / cols;
            int col = i % cols;
            float sx = gridX + col * (slotSize + pad);
            float sy = gridY + row * (slotSize + pad);
            if (mx >= sx && mx <= sx + slotSize && my >= sy && my <= sy + slotSize) {
                Inventory.Slot slot = player.inventory.getSlot(i);
                if (!slot.isEmpty()) {
                    player.hotbar[player.selectedSlot] = slot.shape;
                }
                return;
            }
        }

        // Click hotbar slots
        float sepY = gridY + invRows * (slotSize + pad) + 4 * uiScale;
        float hotbarY = sepY + 20 * uiScale;
        for (int i = 0; i < Player.HOTBAR_SIZE; i++) {
            float sx = gridX + i * (slotSize + pad);
            if (mx >= sx && mx <= sx + slotSize && my >= hotbarY && my <= hotbarY + slotSize) {
                player.selectedSlot = i;
                return;
            }
        }
    }

    private void updateDeath(float dt) {
        deathTimer += dt;
        // Press ENTER to respawn after a short delay
        if (deathTimer > 1.5f && (input.isKeyPressed(GLFW_KEY_ENTER) || input.isKeyPressed(GLFW_KEY_SPACE))) {
            // Find spawn point
            float spawnX = 0, spawnZ = 0;
            int spawnY = 80;
            for (int y = 80; y > 0; y--) {
                if (world.isSolid((int) spawnX, y, (int) spawnZ)) {
                    spawnY = y + 2;
                    break;
                }
            }
            player.respawn(spawnX, spawnY, spawnZ);
            dead = false;
        }
    }

    private void renderDeathScreen(int screenW, int screenH) {
        uiRenderer.begin(screenW, screenH);
        float s = uiScale;

        // Red overlay
        float alpha = Math.min(0.7f, deathTimer * 0.5f);
        uiRenderer.drawRect(0, 0, screenW, screenH, 0.4f, 0, 0, alpha);

        // "YOU DIED" text
        float titleScale = 6 * s;
        String title = "YOU DIED";
        float titleW = uiRenderer.textWidth(title, titleScale);
        uiRenderer.drawTextWithShadow(title, (screenW - titleW) / 2f, screenH / 2f - 40 * s, titleScale,
            0.9f, 0.15f, 0.15f, 1f);

        // Respawn hint (show after delay)
        if (deathTimer > 1.5f) {
            float hintScale = 3 * s;
            String hint = "PRESS ENTER TO RESPAWN";
            float hintW = uiRenderer.textWidth(hint, hintScale);
            float blink = (float) (Math.sin(deathTimer * 3) * 0.3 + 0.7);
            uiRenderer.drawTextWithShadow(hint, (screenW - hintW) / 2f, screenH / 2f + 30 * s, hintScale,
                1f, 1f, 1f, blink);
        }

        uiRenderer.end();
    }

    private void addChatMessage(String msg) {
        chatMessages.add(msg);
        if (chatMessages.size() > MAX_CHAT_MESSAGES) chatMessages.remove(0);
        chatFadeTimer = 8f; // show for 8 seconds
    }

    private void processChat(String text) {
        addChatMessage("> " + text);

        // Broadcast non-command chat to network
        if (network.isOnline() && !text.startsWith("/")) {
            network.sendChat(text);
        }

        String lower = text.toLowerCase().trim();

        // Strip leading /
        if (lower.startsWith("/")) lower = lower.substring(1).trim();

        // === Direct commands ===
        if (lower.equals("help")) {
            addChatMessage("Commands: give, tp, heal, gamemode, fly, kill, clear, vanish, locate <biome>, time <set/query>");
            return;
        }

        // Admin check — only Danimew456 can use commands
        if (!player.name.equals("Danimew456")) {
            addChatMessage("[System] You don't have permission to use commands");
            return;
        }

        // === AI-style fuzzy matching ===
        // Gamemode
        if (matches(lower, "creative", "gamemode creative", "gmc", "creative mode", "switch to creative",
                "make me creative", "i want creative", "go creative")) {
            player.creative = true; player.flying = true; player.noclip = false;
            player.health = player.maxHealth; player.stamina = player.maxStamina;
            addChatMessage("[AI] Switched to Creative mode");
            return;
        }
        if (matches(lower, "survival", "gamemode survival", "gms", "survival mode", "switch to survival",
                "make me survival", "go survival")) {
            player.creative = false; player.flying = false; player.noclip = false;
            addChatMessage("[AI] Switched to Survival mode");
            return;
        }

        // Heal
        if (matches(lower, "heal", "heal me", "full health", "restore health", "hp", "give me health",
                "i need health", "fix me", "patch me up")) {
            player.health = player.maxHealth;
            player.stamina = player.maxStamina;
            addChatMessage("[AI] Healed to full health and stamina");
            return;
        }

        // Kill
        if (matches(lower, "kill", "kill me", "die", "suicide", "i want to die", "end me")) {
            player.health = 0;
            addChatMessage("[AI] You asked for it...");
            return;
        }

        // Fly
        if (matches(lower, "fly", "fly on", "let me fly", "i want to fly", "toggle fly", "enable fly")) {
            player.flying = !player.flying;
            if (player.flying) player.velocity.y = 0;
            addChatMessage("[AI] Flying " + (player.flying ? "enabled" : "disabled"));
            return;
        }

        // Noclip
        if (matches(lower, "noclip", "ghost", "no clip", "phase", "walk through walls")) {
            player.noclip = !player.noclip;
            addChatMessage("[AI] Noclip " + (player.noclip ? "enabled" : "disabled"));
            return;
        }

        // Vanish (Danimew456 only)
        if (matches(lower, "vanish", "invisible", "disappear", "hide me")) {
            if (player.name.equals("Danimew456")) {
                player.vanished = !player.vanished;
                addChatMessage("[AI] Vanish " + (player.vanished ? "enabled - you are invisible" : "disabled - you are visible"));
            } else {
                addChatMessage("[AI] You don't have permission to use vanish");
            }
            return;
        }

        // Clear inventory
        if (matches(lower, "clear", "clear inv", "clear inventory", "empty inventory", "drop everything",
                "remove all items", "clear my inventory")) {
            player.inventory.clear();
            for (int i = 0; i < Player.HOTBAR_SIZE; i++) player.hotbar[i] = null;
            addChatMessage("[AI] Inventory cleared");
            return;
        }

        // Teleport
        if (lower.startsWith("tp ") || lower.startsWith("teleport ") || lower.startsWith("go to ")) {
            String args = lower.replaceFirst("^(tp|teleport|go to)\\s+", "");
            String[] parts = args.split("[,\\s]+");
            // Try coordinates first
            try {
                if (parts.length >= 3) {
                    float x = Float.parseFloat(parts[0]);
                    float y = Float.parseFloat(parts[1]);
                    float z = Float.parseFloat(parts[2]);
                    player.position.set(x, y, z);
                    player.velocity.set(0, 0, 0);
                    addChatMessage("[AI] Teleported to " + (int)x + ", " + (int)y + ", " + (int)z);
                    return;
                }
            } catch (NumberFormatException ignored) {}
            // Try player name
            String targetName = args.trim();
            if (network.isOnline()) {
                for (com.danigt.net.RemotePlayer rp : network.getRemotePlayers()) {
                    if (rp.name.equalsIgnoreCase(targetName)) {
                        player.position.set(rp.position.x, rp.position.y, rp.position.z);
                        player.velocity.set(0, 0, 0);
                        addChatMessage("[AI] Teleported to " + rp.name);
                        return;
                    }
                }
                addChatMessage("[AI] Player '" + targetName + "' not found. Online players:");
                for (com.danigt.net.RemotePlayer rp : network.getRemotePlayers()) {
                    addChatMessage("  - " + rp.name);
                }
            } else {
                addChatMessage("[AI] Usage: tp <x> <y> <z> or tp <player name> (when online)");
            }
            return;
        }
        if (matches(lower, "spawn", "go home", "go to spawn", "tp spawn", "teleport spawn",
                "take me home", "bring me back")) {
            float spawnY = 80;
            for (int y = 80; y > 0; y--) {
                if (world.isSolid(0, y, 0)) { spawnY = y + 2; break; }
            }
            player.position.set(0, spawnY, 0);
            player.velocity.set(0, 0, 0);
            addChatMessage("[AI] Teleported to spawn");
            return;
        }

        // Locate biome
        // Time command
        if (lower.startsWith("time ") || lower.equals("time")) {
            String args = lower.length() > 5 ? lower.substring(5).trim() : "";
            if (args.equals("query") || args.isEmpty()) {
                float phase = (gameTime % 600.0f) / 600.0f;
                int ticks = (int)(phase * 24000); // MC-style ticks
                String period;
                if (phase < 0.1f) period = "Dawn";
                else if (phase < 0.4f) period = "Day";
                else if (phase < 0.55f) period = "Dusk";
                else if (phase < 0.9f) period = "Night";
                else period = "Pre-dawn";
                addChatMessage("[System] Time: " + ticks + " (" + period + ")");
                return;
            }
            if (args.startsWith("set ")) {
                String val = args.substring(4).trim();
                float targetPhase = -1;
                switch (val) {
                    case "day": case "noon": case "midday": targetPhase = 0.25f; break;
                    case "dawn": case "sunrise": case "morning": targetPhase = 0.0f; break;
                    case "dusk": case "sunset": case "evening": targetPhase = 0.45f; break;
                    case "night": case "midnight": targetPhase = 0.7f; break;
                    default:
                        try {
                            int ticks = Integer.parseInt(val);
                            targetPhase = (ticks % 24000) / 24000.0f;
                        } catch (NumberFormatException e) {
                            addChatMessage("[System] Usage: time set <day|dawn|dusk|night|ticks>");
                            return;
                        }
                }
                // Set gameTime so dayPhase matches target
                gameTime = targetPhase * 600.0f;
                String period;
                if (targetPhase < 0.1f) period = "Dawn";
                else if (targetPhase < 0.4f) period = "Day";
                else if (targetPhase < 0.55f) period = "Dusk";
                else if (targetPhase < 0.9f) period = "Night";
                else period = "Pre-dawn";
                addChatMessage("[System] Time set to " + period);
                return;
            }
            addChatMessage("[System] Usage: time query | time set <day|dawn|dusk|night|ticks>");
            return;
        }

        if (lower.startsWith("locate ") || lower.startsWith("find biome ") || lower.startsWith("find ")) {
            String biomeName = lower.replaceFirst("^(locate|find biome|find)\\s+", "").trim();
            com.danigt.world.Biome targetBiome = com.danigt.world.Biome.fromName(biomeName);
            if (targetBiome == null) {
                addChatMessage("[System] Unknown biome: " + biomeName);
                addChatMessage("[System] Biomes: Crystal Fields, Mushroom Grove, Enchanted Forest, Volcanic Wastes, Frozen Tundra, Desert, Plains");
                return;
            }
            // Spiral search outward from player position
            int px = (int) player.position.x;
            int pz = (int) player.position.z;
            int step = 32;
            int maxRadius = 5000;
            int foundX = Integer.MIN_VALUE, foundZ = 0;
            outer:
            for (int radius = 0; radius <= maxRadius; radius += step) {
                for (int dx = -radius; dx <= radius; dx += step) {
                    int[] dzValues = (Math.abs(dx) == radius) ?
                        new int[]{-radius, -radius + step, radius - step, radius} :
                        new int[]{-radius, radius};
                    for (int dz : dzValues) {
                        if (Math.abs(dz) > radius) continue;
                        int testX = px + dx, testZ = pz + dz;
                        if (world.getGenerator().getBiome(testX, testZ) == targetBiome) {
                            foundX = testX;
                            foundZ = testZ;
                            break outer;
                        }
                    }
                }
            }
            if (foundX != Integer.MIN_VALUE) {
                int dist = (int) Math.sqrt((foundX - px) * (foundX - px) + (foundZ - pz) * (foundZ - pz));
                addChatMessage("[System] Nearest " + targetBiome.displayName + " at " + foundX + ", " + foundZ + " (" + dist + " blocks away)");
            } else {
                addChatMessage("[System] " + targetBiome.displayName + " not found within " + maxRadius + " blocks");
            }
            return;
        }

        // Give items
        if (lower.startsWith("give") || lower.startsWith("i want") || lower.startsWith("get me") ||
            lower.startsWith("spawn ") || lower.startsWith("gimme")) {
            String args = lower.replaceFirst("^(give me|give|i want|get me|gimme|spawn)\\s*", "").trim();
            // Parse optional count
            int count = 64;
            String[] parts = args.split("\\s+");
            String blockSearch = args;
            if (parts.length >= 2) {
                try {
                    count = Integer.parseInt(parts[parts.length - 1]);
                    blockSearch = args.substring(0, args.lastIndexOf(parts[parts.length - 1])).trim();
                } catch (NumberFormatException e) {
                    // last word isn't a number, search full string
                }
            }
            // Find matching block
            CrystalShape found = findBlock(blockSearch);
            if (found != null) {
                player.inventory.add(found, count);
                player.assignToHotbarIfEmpty(found);
                addChatMessage("[AI] Gave " + count + "x " + found.name().replace('_', ' '));
            } else {
                addChatMessage("[AI] Unknown block: " + blockSearch);
            }
            return;
        }

        // Fallback — try to find if they're asking for a block by name
        CrystalShape guessed = findBlock(lower);
        if (guessed != null) {
            player.inventory.add(guessed, 64);
            player.assignToHotbarIfEmpty(guessed);
            addChatMessage("[AI] Gave 64x " + guessed.name().replace('_', ' '));
            return;
        }

        addChatMessage("[AI] I don't understand. Try /help");
    }

    private boolean matches(String input, String... options) {
        for (String opt : options) {
            if (input.equals(opt)) return true;
        }
        return false;
    }

    private void extractFrustumPlanes(Matrix4f vp) {
        // Extract 6 frustum planes from view-projection matrix
        float[] m = new float[16];
        vp.get(m);
        // Left
        frustumPlanes[0][0] = m[3] + m[0]; frustumPlanes[0][1] = m[7] + m[4];
        frustumPlanes[0][2] = m[11] + m[8]; frustumPlanes[0][3] = m[15] + m[12];
        // Right
        frustumPlanes[1][0] = m[3] - m[0]; frustumPlanes[1][1] = m[7] - m[4];
        frustumPlanes[1][2] = m[11] - m[8]; frustumPlanes[1][3] = m[15] - m[12];
        // Bottom
        frustumPlanes[2][0] = m[3] + m[1]; frustumPlanes[2][1] = m[7] + m[5];
        frustumPlanes[2][2] = m[11] + m[9]; frustumPlanes[2][3] = m[15] + m[13];
        // Top
        frustumPlanes[3][0] = m[3] - m[1]; frustumPlanes[3][1] = m[7] - m[5];
        frustumPlanes[3][2] = m[11] - m[9]; frustumPlanes[3][3] = m[15] - m[13];
        // Near
        frustumPlanes[4][0] = m[3] + m[2]; frustumPlanes[4][1] = m[7] + m[6];
        frustumPlanes[4][2] = m[11] + m[10]; frustumPlanes[4][3] = m[15] + m[14];
        // Far
        frustumPlanes[5][0] = m[3] - m[2]; frustumPlanes[5][1] = m[7] - m[6];
        frustumPlanes[5][2] = m[11] - m[10]; frustumPlanes[5][3] = m[15] - m[14];
        // Normalize
        for (int i = 0; i < 6; i++) {
            float len = (float) Math.sqrt(frustumPlanes[i][0]*frustumPlanes[i][0] +
                frustumPlanes[i][1]*frustumPlanes[i][1] + frustumPlanes[i][2]*frustumPlanes[i][2]);
            if (len > 0) { frustumPlanes[i][0]/=len; frustumPlanes[i][1]/=len; frustumPlanes[i][2]/=len; frustumPlanes[i][3]/=len; }
        }
    }

    private boolean isChunkVisible(Chunk chunk) {
        float x = chunk.getChunkX() * Chunk.SIZE;
        float y = chunk.getChunkY() * Chunk.SIZE;
        float z = chunk.getChunkZ() * Chunk.SIZE;
        float s = Chunk.SIZE;
        // Test AABB against all 6 frustum planes
        for (int i = 0; i < 6; i++) {
            float px = frustumPlanes[i][0] > 0 ? x + s : x;
            float py = frustumPlanes[i][1] > 0 ? y + s : y;
            float pz = frustumPlanes[i][2] > 0 ? z + s : z;
            if (frustumPlanes[i][0]*px + frustumPlanes[i][1]*py + frustumPlanes[i][2]*pz + frustumPlanes[i][3] < 0)
                return false;
        }
        return true;
    }

    private CrystalShape findBlock(String search) {
        search = search.replace(' ', '_').toUpperCase().trim();
        // Exact match
        for (CrystalShape s : CrystalShape.values()) {
            if (s.name().equals(search)) return s;
        }
        // Contains match
        for (CrystalShape s : CrystalShape.values()) {
            if (s.name().contains(search) || search.contains(s.name())) return s;
        }
        // Partial/fuzzy match
        for (CrystalShape s : CrystalShape.values()) {
            String name = s.name().replace('_', ' ').toLowerCase();
            if (name.contains(search.toLowerCase().replace('_', ' '))) return s;
        }
        // Common aliases
        if (search.contains("WOOD") || search.contains("LOG")) return CrystalShape.OAK_LOG;
        if (search.contains("PLANK")) return CrystalShape.OAK_PLANKS;
        if (search.contains("LEAF") || search.contains("LEAVES")) return CrystalShape.OAK_LEAVES;
        if (search.contains("DIAMOND")) return CrystalShape.DIAMOND_ORE;
        if (search.contains("IRON")) return CrystalShape.IRON_ORE;
        if (search.contains("GOLD")) return CrystalShape.GOLD_ORE;
        if (search.contains("COAL")) return CrystalShape.COAL_ORE;
        return null;
    }

    private void renderChat(int screenW, int screenH) {
        float s = uiScale;
        float chatScale = 2.5f * s;
        float lineH = 5 * chatScale + 4 * s;
        float chatX = 10 * s;
        float chatY = screenH - 90 * s - lineH * MAX_CHAT_MESSAGES;

        // Only render if chat is open or messages are fading
        if (!chatOpen && chatFadeTimer <= 0) return;

        uiRenderer.begin(screenW, screenH);

        // Show messages
        float alpha = chatOpen ? 0.9f : Math.min(1f, chatFadeTimer / 2f);
        float bgAlpha = chatOpen ? 0.5f : Math.min(0.3f, chatFadeTimer / 4f);

        for (int i = 0; i < chatMessages.size(); i++) {
            String msg = chatMessages.get(i);
            float my = chatY + i * lineH;
            float mw = uiRenderer.textWidth(msg, chatScale) + 10 * s;
            uiRenderer.drawRect(chatX - 4 * s, my - 2 * s, mw + 8 * s, lineH, 0, 0, 0, bgAlpha);

            // Color AI messages differently
            if (msg.startsWith("[AI]")) {
                uiRenderer.drawTextWithShadow(msg, chatX, my, chatScale, 0.3f, 1f, 0.5f, alpha);
            } else if (msg.startsWith(">")) {
                uiRenderer.drawTextWithShadow(msg, chatX, my, chatScale, 0.8f, 0.8f, 0.8f, alpha);
            } else {
                uiRenderer.drawTextWithShadow(msg, chatX, my, chatScale, 1f, 1f, 1f, alpha);
            }
        }

        // Input box
        if (chatOpen) {
            float inputY = chatY + chatMessages.size() * lineH + 4 * s;
            float inputW = screenW * 0.5f;
            uiRenderer.drawRect(chatX - 4 * s, inputY - 2 * s, inputW, lineH + 4 * s, 0, 0, 0, 0.7f);
            uiRenderer.drawRect(chatX - 4 * s, inputY - 2 * s, inputW, 2 * s, 0.3f, 0.8f, 1f, 0.8f);

            String display = chatInput.toString();
            // Blinking cursor
            if ((int)(gameTime * 2) % 2 == 0) display += "_";
            uiRenderer.drawTextWithShadow(display, chatX, inputY + 2 * s, chatScale, 1f, 1f, 1f, 1f);
        }

        uiRenderer.end();
    }

    private void renderInventory(int screenW, int screenH) {
