        // Panel
        uiRenderer.drawRect(panelX, panelY, panelW, panelH, 0.12f, 0.12f, 0.15f, 0.95f);
        uiRenderer.drawRect(panelX, panelY, panelW, 3 * s, 0.4f, 0.4f, 0.5f, 0.9f);
        uiRenderer.drawRect(panelX, panelY + panelH - 3 * s, panelW, 3 * s, 0.4f, 0.4f, 0.5f, 0.9f);
        uiRenderer.drawRect(panelX, panelY, 3 * s, panelH, 0.4f, 0.4f, 0.5f, 0.9f);
        uiRenderer.drawRect(panelX + panelW - 3 * s, panelY, 3 * s, panelH, 0.4f, 0.4f, 0.5f, 0.9f);

        float titleScale = 3 * s;
        String title = "CREATIVE MENU";
        float titleW = uiRenderer.textWidth(title, titleScale);
        uiRenderer.drawTextWithShadow(title, (screenW - titleW) / 2f, panelY + 10 * s, titleScale, 0.8f, 0.8f, 0.9f, 1f);

        float gridX = panelX + 10 * s + pad;
        float gridY = panelY + 40 * s;
        float gridMaxY = panelY + panelH - 80 * s;

        for (int idx = 0; idx < allShapes.length; idx++) {
            int row = idx / cols;
            int col = idx % cols;
