            uiRenderer.drawRect(sx, sy, slotSize, slotSize, 0.2f, 0.2f, 0.22f, 0.8f);
            uiRenderer.queueBlockIcon(sx + 3 * s, sy + 3 * s, slotSize - 6 * s, allShapes[idx]);
