        String hint = "CLICK BLOCK TO SET HOTBAR  SCROLL TO BROWSE  V TO CLOSE";
        float hintW = uiRenderer.textWidth(hint, hintScale);
        uiRenderer.drawTextWithShadow(hint, (screenW - hintW) / 2f, panelY + panelH - 65 * s + slotSize + 8 * s,
            hintScale, 0.5f, 0.5f, 0.5f, 0.7f);

        uiRenderer.end();
    }

