package com.danigt.engine;

import static org.lwjgl.glfw.GLFW.*;

public class Input {

    private static final int MAX_KEYS = 350;
    private static final int MAX_BUTTONS = 8;

    private final boolean[] keys = new boolean[MAX_KEYS];
    private final boolean[] keysPressed = new boolean[MAX_KEYS];
    private final boolean[] buttons = new boolean[MAX_BUTTONS];
    private final boolean[] buttonsPressed = new boolean[MAX_BUTTONS];

    private double mouseX, mouseY;
    private double mouseDX, mouseDY;
    private double scrollDX, scrollDY;
    private boolean firstMouse = true;

    public void init(long windowHandle) {
        glfwSetKeyCallback(windowHandle, (window, key, scancode, action, mods) -> {
            if (key >= 0 && key < MAX_KEYS) {
                if (action == GLFW_PRESS) {
                    keys[key] = true;
                    keysPressed[key] = true;
                } else if (action == GLFW_RELEASE) {
                    keys[key] = false;
                }
            }
        });

        glfwSetMouseButtonCallback(windowHandle, (window, button, action, mods) -> {
            if (button >= 0 && button < MAX_BUTTONS) {
                if (action == GLFW_PRESS) {
                    buttons[button] = true;
                    buttonsPressed[button] = true;
                } else if (action == GLFW_RELEASE) {
                    buttons[button] = false;
                }
            }
        });

        glfwSetCursorPosCallback(windowHandle, (window, xpos, ypos) -> {
            if (firstMouse) {
                mouseX = xpos;
                mouseY = ypos;
                firstMouse = false;
            }
            mouseDX += xpos - mouseX;
            mouseDY += ypos - mouseY;
            mouseX = xpos;
            mouseY = ypos;
        });

        glfwSetScrollCallback(windowHandle, (window, xoffset, yoffset) -> {
            scrollDX += xoffset;
            scrollDY += yoffset;
        });
    }

    public void update() {
        // Clear per-frame states
        java.util.Arrays.fill(keysPressed, false);
        java.util.Arrays.fill(buttonsPressed, false);
        mouseDX = 0;
        mouseDY = 0;
        scrollDX = 0;
        scrollDY = 0;
    }

    public boolean isKeyDown(int key) { return key >= 0 && key < MAX_KEYS && keys[key]; }
    public boolean isKeyPressed(int key) { return key >= 0 && key < MAX_KEYS && keysPressed[key]; }
    public boolean isButtonDown(int button) { return button >= 0 && button < MAX_BUTTONS && buttons[button]; }
    public boolean isButtonPressed(int button) { return button >= 0 && button < MAX_BUTTONS && buttonsPressed[button]; }
    public double getMouseDX() { return mouseDX; }
    public double getMouseDY() { return mouseDY; }
    public double getScrollDY() { return scrollDY; }
    public double getMouseX() { return mouseX; }
    public double getMouseY() { return mouseY; }

    public void setKey(int key, boolean pressed) {
        if (key >= 0 && key < MAX_KEYS) {
            if (pressed && !keys[key]) keysPressed[key] = true;
            keys[key] = pressed;
        }
    }
}


