package com.danigt.engine;

public class Timer {

    private long lastTime;
    private float deltaTime;
    private int fps;
    private int frameCount;
    private float fpsTimer;

    public void init() {
        lastTime = System.nanoTime();
    }

    public void update() {
        long now = System.nanoTime();
        deltaTime = (now - lastTime) / 1_000_000_000.0f;
        lastTime = now;

        // Clamp to avoid spiral of death
        if (deltaTime > 0.05f) deltaTime = 0.05f;

        frameCount++;
        fpsTimer += deltaTime;
        if (fpsTimer >= 1.0f) {
            fps = frameCount;
            frameCount = 0;
            fpsTimer -= 1.0f;
        }
    }

    public float getDeltaTime() { return deltaTime; }
    public int getFps() { return fps; }
}


// ===== src/main/java/com/danigt/engine/Window.java =====
package com.danigt.engine;

import org.lwjgl.glfw.*;
import org.lwjgl.opengl.GL;
import org.lwjgl.system.MemoryStack;

import java.nio.IntBuffer;

import static org.lwjgl.glfw.Callbacks.glfwFreeCallbacks;
import static org.lwjgl.glfw.GLFW.*;
import static org.lwjgl.system.MemoryUtil.NULL;

public class Window {

    private long handle;
    private int width, height;       // framebuffer size (pixels)
    private int windowW, windowH;    // window size (screen coords)
    private float contentScaleX = 1, contentScaleY = 1;
    private boolean resized;
    private final String title;

    public Window(String title, int width, int height) {
        this.title = title;
        this.width = width;
        this.height = height;
    }

    public void init() {
        GLFWErrorCallback.createPrint(System.err).set();

        if (!glfwInit()) {
            throw new IllegalStateException("Unable to initialize GLFW");
        }

        glfwDefaultWindowHints();
        glfwWindowHint(GLFW_VISIBLE, GLFW_FALSE);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_TRUE);
        glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
        glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
        glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
        glfwWindowHint(GLFW_OPENGL_FORWARD_COMPAT, GLFW_TRUE);

        handle = glfwCreateWindow(width, height, title, NULL, NULL);
        if (handle == NULL) {
            throw new RuntimeException("Failed to create GLFW window");
        }

        glfwSetFramebufferSizeCallback(handle, (window, w, h) -> {
            width = w;
            height = h;
            resized = true;
            updateContentScale();
        });

        glfwSetWindowSizeCallback(handle, (window, w, h) -> {
            windowW = w;
            windowH = h;
            updateContentScale();
        });

        // Get initial sizes
        try (MemoryStack stack = MemoryStack.stackPush()) {
            IntBuffer wBuf = stack.mallocInt(1);
            IntBuffer hBuf = stack.mallocInt(1);
            glfwGetFramebufferSize(handle, wBuf, hBuf);
            width = wBuf.get(0);
            height = hBuf.get(0);
            glfwGetWindowSize(handle, wBuf, hBuf);
            windowW = wBuf.get(0);
            windowH = hBuf.get(0);
            updateContentScale();
        }

        glfwMakeContextCurrent(handle);
        glfwSwapInterval(1); // vsync
        glfwShowWindow(handle);

        GL.createCapabilities();
    }

    public boolean shouldClose() {
        return glfwWindowShouldClose(handle);
    }

    public void swapBuffers() {
        glfwSwapBuffers(handle);
    }

    public void pollEvents() {
        glfwPollEvents();
    }

    public void cleanup() {
        glfwFreeCallbacks(handle);
        glfwDestroyWindow(handle);
        glfwTerminate();
        GLFWErrorCallback cb = glfwSetErrorCallback(null);
        if (cb != null) cb.free();
    }

    private void updateContentScale() {
        if (windowW > 0 && windowH > 0) {
            contentScaleX = (float) width / windowW;
            contentScaleY = (float) height / windowH;
        }
    }

    public long getHandle() { return handle; }
    public int getWidth() { return width; }
    public int getHeight() { return height; }
    public float getContentScaleX() { return contentScaleX; }
    public float getContentScaleY() { return contentScaleY; }

    public boolean isResized() {
        if (resized) {
            resized = false;
            return true;
        }
        return false;
    }

    public void setCursorGrabbed(boolean grabbed) {
        glfwSetInputMode(handle, GLFW_CURSOR,
            grabbed ? GLFW_CURSOR_DISABLED : GLFW_CURSOR_NORMAL);
    }
}


// ===== src/main/java/com/danigt/entity/CharacterModel.java =====
package com.danigt.entity;

import com.danigt.math.MeshBuilder;
import com.danigt.render.Mesh;
import com.danigt.world.CrystalBlock;
import com.danigt.world.CrystalShape;
import org.joml.Vector3f;

/**
 * Minecraft-style character model with detailed pixel-art skin.
 * Built from colored cubes forming a humanoid figure:
 * - 8x8x8 head with face detail (eyes, mouth, hair)
 * - 8x12x4 torso with shirt/hoodie design
 * - 4x12x4 legs with jeans and shoes
 * - 4x12x4 arms with skin and sleeves
 */
public class CharacterModel {

    private Mesh mesh;
    private float walkCycle = 0;

    // Skin colors
    private static final Vector3f SKIN = new Vector3f(0.87f, 0.72f, 0.58f);
    private static final Vector3f SKIN_DARK = new Vector3f(0.75f, 0.60f, 0.48f);
    private static final Vector3f HAIR = new Vector3f(0.22f, 0.15f, 0.10f);
    private static final Vector3f HAIR_LIGHT = new Vector3f(0.30f, 0.20f, 0.14f);
    private static final Vector3f EYE_WHITE = new Vector3f(0.95f, 0.95f, 0.95f);
    private static final Vector3f EYE_PUPIL = new Vector3f(0.15f, 0.35f, 0.65f); // blue eyes
    private static final Vector3f MOUTH = new Vector3f(0.70f, 0.40f, 0.35f);

    // Clothing colors - blue hoodie
    private static final Vector3f HOODIE = new Vector3f(0.20f, 0.40f, 0.75f);
    private static final Vector3f HOODIE_DARK = new Vector3f(0.15f, 0.30f, 0.60f);
    private static final Vector3f HOODIE_LIGHT = new Vector3f(0.28f, 0.50f, 0.85f);
    private static final Vector3f HOODIE_STRIPE = new Vector3f(0.90f, 0.85f, 0.20f); // yellow stripe

    // Pants
    private static final Vector3f JEANS = new Vector3f(0.22f, 0.25f, 0.45f);
    private static final Vector3f JEANS_DARK = new Vector3f(0.18f, 0.20f, 0.38f);

    // Shoes
    private static final Vector3f SHOE = new Vector3f(0.25f, 0.25f, 0.25f);
    private static final Vector3f SHOE_SOLE = new Vector3f(0.85f, 0.85f, 0.80f);

    private static final float PX = 1f / 16f; // one pixel at model scale

    public void update(float dt, boolean walking) {
        if (walking) {
            walkCycle += dt * 8;
        } else {
            walkCycle *= 0.9f; // smoothly stop
            if (Math.abs(walkCycle) < 0.01f) walkCycle = 0;
        }
    }

    public Mesh getMesh() {
        if (mesh != null) mesh.cleanup();

        MeshBuilder builder = new MeshBuilder();
        float legSwing = (float) Math.sin(walkCycle) * 0.4f;
        float armSwing = -legSwing * 0.7f;

        // ===== HEAD (8x8x8 pixels, centered at top) =====
        // Base head - skin color
        buildHead(builder);

        // ===== TORSO (8x12x4 pixels) =====
        buildTorso(builder);

        // ===== RIGHT LEG =====
        buildLeg(builder, 0, legSwing);

        // ===== LEFT LEG =====
        buildLeg(builder, 1, -legSwing);

        // ===== RIGHT ARM =====
        buildArm(builder, 0, armSwing);

        // ===== LEFT ARM =====
        buildArm(builder, 1, -armSwing);

        mesh = builder.build();
        return mesh;
    }

    private void buildHead(MeshBuilder builder) {
        float headY = 1.5f; // top of torso
        float headX = -0.25f;
        float headZ = -0.25f;
        float hs = 0.5f; // head size

        // Main head block
        addBlock(builder, headX, headY, headZ, hs, hs, hs, SKIN);

        // Hair on top (darker)
        addBlock(builder, headX, headY + hs * 0.85f, headZ, hs, hs * 0.2f, hs, HAIR);
        // Hair sides
        addBlock(builder, headX - hs * 0.05f, headY + hs * 0.3f, headZ, hs * 0.12f, hs * 0.7f, hs, HAIR);
        addBlock(builder, headX + hs * 0.93f, headY + hs * 0.3f, headZ, hs * 0.12f, hs * 0.7f, hs, HAIR);
        // Hair back
        addBlock(builder, headX, headY + hs * 0.3f, headZ - hs * 0.05f, hs, hs * 0.7f, hs * 0.12f, HAIR);

        // Eyes (front face, z = headZ + hs)
        float eyeY = headY + hs * 0.55f;
        float eyeSize = hs * 0.14f;
        // Left eye white
        addBlock(builder, headX + hs * 0.18f, eyeY, headZ + hs * 0.95f, eyeSize * 1.5f, eyeSize, eyeSize * 0.5f, EYE_WHITE);
        // Left eye pupil
        addBlock(builder, headX + hs * 0.22f, eyeY, headZ + hs * 0.97f, eyeSize, eyeSize, eyeSize * 0.3f, EYE_PUPIL);
        // Right eye white
        addBlock(builder, headX + hs * 0.58f, eyeY, headZ + hs * 0.95f, eyeSize * 1.5f, eyeSize, eyeSize * 0.5f, EYE_WHITE);
        // Right eye pupil
        addBlock(builder, headX + hs * 0.62f, eyeY, headZ + hs * 0.97f, eyeSize, eyeSize, eyeSize * 0.3f, EYE_PUPIL);

        // Mouth
        addBlock(builder, headX + hs * 0.30f, headY + hs * 0.30f, headZ + hs * 0.96f,
            hs * 0.4f, hs * 0.08f, hs * 0.08f, MOUTH);

        // Nose
        addBlock(builder, headX + hs * 0.42f, headY + hs * 0.42f, headZ + hs * 0.96f,
            hs * 0.16f, hs * 0.1f, hs * 0.08f, SKIN_DARK);
    }

    private void buildTorso(MeshBuilder builder) {
        float torsoX = -0.25f;
        float torsoY = 0.75f;
        float torsoZ = -0.125f;
        float tw = 0.5f;  // width
        float th = 0.75f; // height
        float td = 0.25f; // depth

        // Main hoodie body
        addBlock(builder, torsoX, torsoY, torsoZ, tw, th, td, HOODIE);

        // Darker sides
        addBlock(builder, torsoX, torsoY, torsoZ, tw * 0.15f, th, td, HOODIE_DARK);
        addBlock(builder, torsoX + tw * 0.85f, torsoY, torsoZ, tw * 0.15f, th, td, HOODIE_DARK);

        // Hoodie pocket (front)
        addBlock(builder, torsoX + tw * 0.15f, torsoY + th * 0.15f, torsoZ + td * 0.9f,
            tw * 0.7f, th * 0.25f, td * 0.15f, HOODIE_DARK);

        // Yellow stripe across chest
        addBlock(builder, torsoX + tw * 0.1f, torsoY + th * 0.55f, torsoZ + td * 0.92f,
            tw * 0.8f, th * 0.08f, td * 0.12f, HOODIE_STRIPE);

        // Collar
        addBlock(builder, torsoX + tw * 0.2f, torsoY + th * 0.92f, torsoZ - td * 0.05f,
            tw * 0.6f, th * 0.1f, td * 1.1f, HOODIE_LIGHT);
    }

    private void buildLeg(MeshBuilder builder, int side, float swing) {
        // side: 0 = right, 1 = left
        float legW = 0.22f;
        float legH = 0.75f;
        float legD = 0.22f;
        float legX = side == 0 ? -0.22f : 0.0f;
        float legY = 0;
        float legZ = -0.11f;

        // Apply swing by offsetting position (simplified, no rotation transform in mesh)
        float swingOffset = swing * 0.3f;

        // Jeans upper
        addBlock(builder, legX, legY + legH * 0.3f + swingOffset, legZ,
            legW, legH * 0.6f, legD, JEANS);

        // Jeans lower (slightly darker)
        addBlock(builder, legX, legY + legH * 0.15f + swingOffset, legZ,
            legW, legH * 0.2f, legD, JEANS_DARK);

        // Shoe
        addBlock(builder, legX - 0.01f, legY + swingOffset, legZ - 0.02f,
            legW + 0.02f, legH * 0.15f, legD + 0.04f, SHOE);

        // Shoe sole (white/light stripe at bottom)
        addBlock(builder, legX - 0.01f, legY + swingOffset, legZ - 0.02f,
            legW + 0.02f, legH * 0.04f, legD + 0.04f, SHOE_SOLE);

        // Knee detail
        addBlock(builder, legX + legW * 0.15f, legY + legH * 0.45f + swingOffset, legZ + legD * 0.9f,
            legW * 0.7f, legH * 0.12f, legD * 0.15f, JEANS_DARK);
    }

    private void buildArm(MeshBuilder builder, int side, float swing) {
        // side: 0 = right, 1 = left
        float armW = 0.2f;
        float armH = 0.7f;
        float armD = 0.2f;
        float armX = side == 0 ? -0.47f : 0.27f;
        float armY = 0.8f;
        float armZ = -0.1f;

        float swingOffset = swing * 0.25f;

        // Sleeve (hoodie color) - upper arm
        addBlock(builder, armX, armY + armH * 0.45f + swingOffset, armZ,
            armW, armH * 0.55f, armD, HOODIE);
        // Sleeve cuff
        addBlock(builder, armX, armY + armH * 0.40f + swingOffset, armZ,
            armW, armH * 0.1f, armD, HOODIE_DARK);

        // Forearm skin
        addBlock(builder, armX, armY + armH * 0.1f + swingOffset, armZ,
            armW, armH * 0.35f, armD, SKIN);

        // Hand
        addBlock(builder, armX + armW * 0.05f, armY + swingOffset, armZ + armD * 0.05f,
            armW * 0.9f, armH * 0.12f, armD * 0.9f, SKIN_DARK);
    }

    private void addBlock(MeshBuilder builder, float x, float y, float z,
                          float w, float h, float d, Vector3f color) {
        // Create a custom sized block using CRYSTAL shape (uses custom color)
        // We need to scale the cube to (w, h, d) - but MeshBuilder.addCrystal adds a unit cube
        // So we manually add vertices scaled appropriately

        // For simplicity, just add a unit cube at position and let the face colors handle it
        // But we need custom sizing... let's add the faces manually

        float x1 = x, y1 = y, z1 = z;
        float x2 = x + w, y2 = y + h, z2 = z + d;

        // We'll use addCrystal with a position offset and pretend scale is 1
        // Actually we need to handle custom sizes. Let's add a scaled cube directly.
        CrystalBlock block = new CrystalBlock(CrystalShape.GLASS, color);

        // Manually push 6 faces of a box from (x1,y1,z1) to (x2,y2,z2)
        addFace(builder, color,
            x1, y1, z2, x2, y1, z2, x2, y2, z2, x1, y2, z2,  // front +Z
            0, 0, 1);
        addFace(builder, color,
            x2, y1, z1, x1, y1, z1, x1, y2, z1, x2, y2, z1,  // back -Z
            0, 0, -1);
        addFace(builder, color,
            x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1,  // top +Y
            0, 1, 0);
        addFace(builder, color,
            x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2,  // bottom -Y
            0, -1, 0);
        addFace(builder, color,
            x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2,  // right +X
            1, 0, 0);
        addFace(builder, color,
            x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1,  // left -X
            -1, 0, 0);
    }

    private void addFace(MeshBuilder builder, Vector3f color,
                         float x0, float y0, float z0,
                         float x1, float y1, float z1,
                         float x2, float y2, float z2,
                         float x3, float y3, float z3,
                         float nx, float ny, float nz) {
        // We need direct access to builder's internal lists. Since MeshBuilder doesn't expose
        // raw face adding, use a workaround: add via the public addRawFace method
        builder.addRawFace(
            x0, y0, z0, x1, y1, z1, x2, y2, z2, x3, y3, z3,
            nx, ny, nz, color.x, color.y, color.z, 5.0f // blockType 5 = CRYSTAL
        );
    }

    public void cleanup() {
        if (mesh != null) {
            mesh.cleanup();
            mesh = null;
        }
    }
}


