package com.danigt.entity;

import com.danigt.world.CrystalShape;
import org.joml.Vector3f;

public class DroppedItem {

    public final CrystalShape shape;
    public final Vector3f color;
    public final Vector3f position;
    public final Vector3f velocity;
    public float age = 0;
    public boolean collected = false;

    private static final float PICKUP_DELAY = 0.5f;  // seconds before can be picked up
    private static final float DESPAWN_TIME = 60f;    // seconds before disappearing
    private static final float PICKUP_RANGE = 1.8f;
    private static final float GRAVITY = 15f;
    private static final float BOUNCE = 0.3f;
    private static final float BOB_SPEED = 2.5f;
    private static final float BOB_HEIGHT = 0.1f;

    public DroppedItem(CrystalShape shape, Vector3f color, float x, float y, float z) {
        this.shape = shape;
        this.color = new Vector3f(color);
        this.position = new Vector3f(x + 0.5f, y + 0.5f, z + 0.5f);
        // Random pop-up velocity
        float angle = (float) (Math.random() * Math.PI * 2);
        this.velocity = new Vector3f(
            (float) Math.cos(angle) * 2f,
            4f,
            (float) Math.sin(angle) * 2f
        );
    }

    /** Update physics and check for player pickup. Returns true if should be removed. */
    public boolean update(float dt, Player player, boolean isSolid) {
        age += dt;
        if (age > DESPAWN_TIME) return true;
        if (collected) return true;

        // Apply gravity
        velocity.y -= GRAVITY * dt;

        // Move
        position.x += velocity.x * dt;
        position.z += velocity.z * dt;
        position.y += velocity.y * dt;

        // Simple ground collision
        if (isSolid && velocity.y < 0) {
            position.y = (float) Math.ceil(position.y);
            velocity.y = -velocity.y * BOUNCE;
            if (Math.abs(velocity.y) < 0.5f) velocity.y = 0;
            // Friction
            velocity.x *= 0.7f;
            velocity.z *= 0.7f;
        }

        // Dampen horizontal velocity
        velocity.x *= (1f - 2f * dt);
        velocity.z *= (1f - 2f * dt);

        // Check pickup
        if (age > PICKUP_DELAY) {
            float dx = player.position.x - position.x;
            float dy = (player.position.y + Player.EYE_HEIGHT * 0.5f) - position.y;
            float dz = player.position.z - position.z;
            float dist = dx * dx + dy * dy + dz * dz;
            if (dist < PICKUP_RANGE * PICKUP_RANGE) {
                if (player.creative) {
                    collected = true;
                    return true;
                }
                // Add to inventory
                if (player.inventory.add(shape, 1)) {
                    // Also assign to an empty hotbar slot if available
                    player.assignToHotbarIfEmpty(shape);
                    collected = true;
                    return true;
                }
            }
        }

        return false;
    }

    /** Get the visual Y offset for bobbing animation. */
    public float getBobOffset() {
        if (velocity.y == 0 && Math.abs(velocity.x) < 0.1f) {
            return (float) Math.sin(age * BOB_SPEED) * BOB_HEIGHT;
        }
        return 0;
    }

    /** Get visual scale (small cube). */
    public float getScale() {
        return 0.3f;
    }

    /** Get spin angle in degrees for visual rotation. */
    public float getSpinAngle() {
        return age * 90f; // 90 degrees per second
    }
}


