package com.danigt.entity;

import com.danigt.world.CrystalShape;

public class Inventory {

    public static final int SIZE = 36; // 6 hotbar + 30 storage

    private final Slot[] slots = new Slot[SIZE];

    public Inventory() {
        for (int i = 0; i < SIZE; i++) {
            slots[i] = new Slot();
        }
    }

    /** Add a block to inventory. Returns true if successfully added. */
    public boolean add(CrystalShape shape, int count) {
        // First try to stack onto existing matching slot
        for (int i = 0; i < SIZE; i++) {
            if (slots[i].shape == shape && slots[i].count < 64) {
                int canAdd = Math.min(count, 64 - slots[i].count);
                slots[i].count += canAdd;
                count -= canAdd;
                if (count <= 0) return true;
            }
        }
        // Then fill empty slots
        for (int i = 0; i < SIZE; i++) {
            if (slots[i].isEmpty()) {
                int canAdd = Math.min(count, 64);
                slots[i].shape = shape;
                slots[i].count = canAdd;
                count -= canAdd;
                if (count <= 0) return true;
            }
        }
        return count <= 0;
    }

    /** Remove one block of the given shape. Returns true if found and removed. */
    public boolean remove(CrystalShape shape) {
        // Search from end to front (use deepest stack first)
        for (int i = SIZE - 1; i >= 0; i--) {
            if (slots[i].shape == shape && slots[i].count > 0) {
                slots[i].count--;
                if (slots[i].count <= 0) {
                    slots[i].shape = null;
                }
                return true;
            }
        }
        return false;
    }

    /** Check if player has at least one of this block type. */
    public boolean has(CrystalShape shape) {
        for (int i = 0; i < SIZE; i++) {
            if (slots[i].shape == shape && slots[i].count > 0) return true;
        }
        return false;
    }

    /** Get total count of a specific block type. */
    public int count(CrystalShape shape) {
        int total = 0;
        for (int i = 0; i < SIZE; i++) {
            if (slots[i].shape == shape) total += slots[i].count;
        }
        return total;
    }

    public void clear() {
        for (int i = 0; i < SIZE; i++) {
            slots[i].shape = null;
            slots[i].count = 0;
        }
    }

    public Slot getSlot(int index) {
        return slots[index];
    }

    public static class Slot {
        public CrystalShape shape;
        public int count;

        public boolean isEmpty() {
            return shape == null || count <= 0;
        }
    }
}


// ===== src/main/java/com/danigt/entity/Player.java =====
package com.danigt.entity;

import com.danigt.world.CrystalBlock;
import com.danigt.world.CrystalShape;
import org.joml.Vector3f;

public class Player {

    public String name = "Player";
    public final Vector3f position = new Vector3f(0, 50, 0);
    public final Vector3f velocity = new Vector3f();
    public float yaw = -90f, pitch = 0f;
    public boolean onGround = false;
    public int health = 20;
    public int maxHealth = 20;
    public float stamina = 100;
    public float maxStamina = 100;
    public boolean creative = false;
    public boolean flying = false;
    public boolean noclip = false;
    public boolean vanished = false;
    public boolean sprinting = false;

    public final Inventory inventory = new Inventory();

    // Hotbar: 9 slots, assignable to any block type
    public static final int HOTBAR_SIZE = 9;
    public final CrystalShape[] hotbar = new CrystalShape[HOTBAR_SIZE];
    public int selectedSlot = 0;
    public int currentToolIndex = 0;

    // Block breaking progress
    public int breakingX = Integer.MIN_VALUE, breakingY, breakingZ;
    public float breakProgress = 0;
    public boolean isBreaking = false;

    public static final float WIDTH = 0.6f;
    public static final float HEIGHT = 1.8f;
    public static final float EYE_HEIGHT = 1.6f;

    public Player() {
        // Default hotbar blocks
        hotbar[0] = CrystalShape.GRASS;
        hotbar[1] = CrystalShape.DIRT;
        hotbar[2] = CrystalShape.STONE;
        hotbar[3] = CrystalShape.OAK_PLANKS;
        hotbar[4] = CrystalShape.COBBLESTONE;
        hotbar[5] = CrystalShape.OAK_LOG;
        hotbar[6] = CrystalShape.SAND;
        hotbar[7] = CrystalShape.GLASS;
        hotbar[8] = CrystalShape.BRICKS;
        // Survival: start with NOTHING in inventory
    }

    public Vector3f getEyePosition() {
        return new Vector3f(position.x, position.y + EYE_HEIGHT, position.z);
    }

    public CrystalBlock createSelectedBlock() {
        CrystalShape shape = getSelectedShape();
        if (shape == null) return null;
        return new CrystalBlock(shape, shape.defaultColor);
    }

    public CrystalShape getSelectedShape() {
        return hotbar[selectedSlot];
    }

    public Vector3f getHotbarColor(int slot) {
        CrystalShape s = hotbar[slot];
        return s != null ? s.defaultColor : new Vector3f(0.2f, 0.2f, 0.2f);
    }

    /** Assign a shape to the first empty hotbar slot, or one that already has this shape. */
    public void assignToHotbarIfEmpty(CrystalShape shape) {
        // Check if already in hotbar
        for (int i = 0; i < HOTBAR_SIZE; i++) {
            if (hotbar[i] == shape) return;
        }
        // Find first empty slot
        for (int i = 0; i < HOTBAR_SIZE; i++) {
            if (hotbar[i] == null) {
                hotbar[i] = shape;
                return;
            }
        }
    }

    public boolean isDead() { return health <= 0; }

    public void respawn(float x, float y, float z) {
        health = maxHealth;
        stamina = maxStamina;
        position.set(x, y, z);
        velocity.set(0, 0, 0);
        onGround = false;
        isBreaking = false;
        breakProgress = 0;
        breakingX = Integer.MIN_VALUE;
    }

    public void toggleGameMode() {
        creative = !creative;
        if (creative) {
            flying = true;
            noclip = false;
            health = maxHealth;
            stamina = maxStamina;
            // Restore default hotbar for creative
            hotbar[0] = CrystalShape.GRASS;
            hotbar[1] = CrystalShape.DIRT;
            hotbar[2] = CrystalShape.STONE;
            hotbar[3] = CrystalShape.OAK_PLANKS;
            hotbar[4] = CrystalShape.COBBLESTONE;
            hotbar[5] = CrystalShape.OAK_LOG;
            hotbar[6] = CrystalShape.SAND;
            hotbar[7] = CrystalShape.GLASS;
            hotbar[8] = CrystalShape.BRICKS;
        } else {
            flying = false;
            noclip = false;
            health = maxHealth;
            stamina = maxStamina;
            // Only keep hotbar slots for blocks you actually have
            for (int i = 0; i < HOTBAR_SIZE; i++) {
                if (hotbar[i] != null && !inventory.has(hotbar[i])) {
                    hotbar[i] = null;
                }
            }
        }
    }
}


// ===== src/main/java/com/danigt/entity/PlayerController.java =====
package com.danigt.entity;

import com.danigt.engine.Input;
import com.danigt.render.Camera;
import com.danigt.world.World;
import org.joml.Vector3f;

import static org.lwjgl.glfw.GLFW.*;

public class PlayerController {

    private static final float MOVE_SPEED = 5.5f;
    private static final float FLY_SPEED = 12.0f;
    private static final float SPRINT_MULTIPLIER = 2.5f;
    private static final float JUMP_FORCE = 8.0f;
    private static final float GRAVITY = 20.0f;
    private static final float MAX_FALL_SPEED = 60.0f;
    private static final float STAMINA_DRAIN = 15f;  // per second while sprinting
    private static final float STAMINA_REGEN = 8f;   // per second while not sprinting

    private final Player player;
    private final Camera camera;

    // Double-tap space to toggle fly
    private long lastSpacePress = 0;

    public PlayerController(Player player, Camera camera) {
        this.player = player;
        this.camera = camera;
    }

    public void update(Input input, World world, float dt) {
        // Mouse look
        camera.processMouseMovement(input.getMouseDX(), input.getMouseDY());
        player.yaw = camera.getYaw();
        player.pitch = camera.getPitch();

        // G: toggle game mode (creative/survival)
        if (input.isKeyPressed(GLFW_KEY_G)) {
            player.toggleGameMode();
        }

        // Creative mode toggles
        if (player.creative) {
            // F: toggle fly
            if (input.isKeyPressed(GLFW_KEY_F)) {
                player.flying = !player.flying;
                if (player.flying) player.velocity.y = 0;
            }
            // N: toggle noclip
            if (input.isKeyPressed(GLFW_KEY_N)) {
                player.noclip = !player.noclip;
            }
            // Double-tap space to toggle fly
            if (input.isKeyPressed(GLFW_KEY_SPACE)) {
                long now = System.currentTimeMillis();
                if (now - lastSpacePress < 300) {
                    player.flying = !player.flying;
                    if (player.flying) player.velocity.y = 0;
                }
                lastSpacePress = now;
            }
        }

        // Sprint: E key
        boolean wantsSprint = input.isKeyDown(GLFW_KEY_E);
        if (player.creative) {
            player.sprinting = wantsSprint;
        } else {
            // In survival, sprinting drains stamina
            if (wantsSprint && player.stamina > 0) {
                player.sprinting = true;
                player.stamina -= STAMINA_DRAIN * dt;
                if (player.stamina < 0) player.stamina = 0;
            } else {
                player.sprinting = false;
            }
            // Regen stamina when not sprinting
            if (!player.sprinting && player.stamina < player.maxStamina) {
                player.stamina += STAMINA_REGEN * dt;
                if (player.stamina > player.maxStamina) player.stamina = player.maxStamina;
            }
        }

        // Movement direction
        float moveX = 0, moveZ = 0;
        float radYaw = (float) Math.toRadians(player.yaw);
        float forwardX = (float) Math.cos(radYaw);
        float forwardZ = (float) Math.sin(radYaw);
        float rightX = -forwardZ;
        float rightZ = forwardX;

        if (input.isKeyDown(GLFW_KEY_W)) { moveX += forwardX; moveZ += forwardZ; }
        if (input.isKeyDown(GLFW_KEY_S)) { moveX -= forwardX; moveZ -= forwardZ; }
        if (input.isKeyDown(GLFW_KEY_A)) { moveX -= rightX; moveZ -= rightZ; }
        if (input.isKeyDown(GLFW_KEY_D)) { moveX += rightX; moveZ += rightZ; }

        // Normalize horizontal movement
        float len = (float) Math.sqrt(moveX * moveX + moveZ * moveZ);
        if (len > 0) {
            moveX /= len;
            moveZ /= len;
        }

        float speed = player.flying ? FLY_SPEED : MOVE_SPEED;
        if (player.sprinting) speed *= SPRINT_MULTIPLIER;

        if (player.flying) {
            // Fly mode: space = up, shift = down
            player.velocity.x = moveX * speed;
            player.velocity.z = moveZ * speed;
            player.velocity.y = 0;

            if (input.isKeyDown(GLFW_KEY_SPACE)) player.velocity.y = speed;
            if (input.isKeyDown(GLFW_KEY_LEFT_SHIFT)) player.velocity.y = -speed;

            if (player.noclip) {
                player.position.x += player.velocity.x * dt;
                player.position.y += player.velocity.y * dt;
                player.position.z += player.velocity.z * dt;
            } else {
                moveWithCollision(world, dt);
            }
        } else {
            // Normal mode: gravity, jumping, collision
            player.velocity.x = moveX * speed;
            player.velocity.z = moveZ * speed;

            player.velocity.y -= GRAVITY * dt;
            if (player.velocity.y < -MAX_FALL_SPEED) player.velocity.y = -MAX_FALL_SPEED;

            if (input.isKeyDown(GLFW_KEY_SPACE) && player.onGround) {
                player.velocity.y = JUMP_FORCE;
                player.onGround = false;
            }

            // Save fall speed before collision zeros it
            float fallSpeed = player.velocity.y;
            boolean wasOnGround = player.onGround;

            moveWithCollision(world, dt);

            // Fall damage in survival: trigger when we just landed
            // Threshold ~3 blocks fall = velocity around -10
            if (!player.creative && !wasOnGround && player.onGround && fallSpeed < -10) {
                int damage = (int) ((-fallSpeed - 10) * 0.8f);
                if (damage > 0) {
                    player.health -= damage;
                    if (player.health < 0) player.health = 0;
                }
            }
        }

        // Update camera
        Vector3f eye = player.getEyePosition();
        camera.setPosition(eye.x, eye.y, eye.z);

        // Hotbar selection
        for (int i = 0; i < Player.HOTBAR_SIZE; i++) {
            if (input.isKeyPressed(GLFW_KEY_1 + i)) {
                player.selectedSlot = i;
            }
        }

        // Toggle third person (F5)
        if (input.isKeyPressed(GLFW_KEY_F5)) {
            camera.toggleThirdPerson();
        }

        // Cycle tool
        if (input.isKeyPressed(GLFW_KEY_T)) {
            player.currentToolIndex = (player.currentToolIndex + 1) % 4;
        }
    }

    private void moveWithCollision(World world, float dt) {
        // Move X
        float newX = player.position.x + player.velocity.x * dt;
        if (!collides(world, newX, player.position.y, player.position.z)) {
            player.position.x = newX;
        } else {
            player.velocity.x = 0;
        }

        // Move Y
        float newY = player.position.y + player.velocity.y * dt;
        if (!collides(world, player.position.x, newY, player.position.z)) {
            player.position.y = newY;
            player.onGround = false;
        } else {
            if (player.velocity.y < 0) {
                player.onGround = true;
                player.position.y = (float) Math.ceil(newY);
            }
            player.velocity.y = 0;
        }

        // Move Z
        float newZ = player.position.z + player.velocity.z * dt;
        if (!collides(world, player.position.x, player.position.y, newZ)) {
            player.position.z = newZ;
        } else {
            player.velocity.z = 0;
        }
    }

    private boolean collides(World world, float x, float y, float z) {
        float hw = Player.WIDTH / 2;
        float h = Player.HEIGHT;

        int minBX = (int) Math.floor(x - hw);
        int maxBX = (int) Math.floor(x + hw);
        int minBY = (int) Math.floor(y);
        int maxBY = (int) Math.floor(y + h);
        int minBZ = (int) Math.floor(z - hw);
        int maxBZ = (int) Math.floor(z + hw);

        for (int bx = minBX; bx <= maxBX; bx++) {
            for (int by = minBY; by <= maxBY; by++) {
                for (int bz = minBZ; bz <= maxBZ; bz++) {
                    if (world.isSolid(bx, by, bz)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}


// ===== src/main/java/com/danigt/math/MeshBuilder.java =====
package com.danigt.math;

import com.danigt.render.Mesh;
import com.danigt.world.CrystalBlock;
import com.danigt.world.CrystalShape;

import java.util.ArrayList;
import java.util.List;

public class MeshBuilder {

    private final List<Float> positions = new ArrayList<>();
    private final List<Float> normals = new ArrayList<>();
    private final List<Float> colors = new ArrayList<>();
    private final List<Integer> indices = new ArrayList<>();
    private int vertexOffset = 0;

    public static final int FACE_FRONT  = 0;
    public static final int FACE_BACK   = 1;
    public static final int FACE_TOP    = 2;
    public static final int FACE_BOTTOM = 3;
    public static final int FACE_RIGHT  = 4;
    public static final int FACE_LEFT   = 5;

    public void addCube(CrystalBlock block, float wx, float wy, float wz, boolean[] visibleFaces) {
        addCube(block, wx, wy, wz, visibleFaces, 1.0f);
    }

    public void addCube(CrystalBlock block, float wx, float wy, float wz, boolean[] visibleFaces, float aoShade) {
        CrystalShape shape = block.shape;
        float[] verts = shape.getVertices();
        float[] norms = shape.getNormals();
        int[] idx = shape.getIndices();

        float[][] faceColors = getBlockFaceColors(block);
        float texCat = (float) shape.texCategory;

        for (int face = 0; face < 6; face++) {
            if (!visibleFaces[face]) continue;

            int vStart = face * 4;
            int iStart = face * 6;

            for (int v = 0; v < 4; v++) {
                int vi = (vStart + v) * 3;
                positions.add(verts[vi]     + wx);
                positions.add(verts[vi + 1] + wy);
                positions.add(verts[vi + 2] + wz);

                normals.add(norms[vi]);
                normals.add(norms[vi + 1]);
                normals.add(norms[vi + 2]);

                colors.add(faceColors[face][0] * aoShade);
                colors.add(faceColors[face][1] * aoShade);
                colors.add(faceColors[face][2] * aoShade);
                colors.add(texCat);
            }

            for (int i = 0; i < 6; i++) {
                int origIdx = idx[iStart + i] - vStart;
                indices.add(vertexOffset + origIdx);
            }
            vertexOffset += 4;
        }
    }

    public void addCrystal(CrystalBlock block, float wx, float wy, float wz) {
        boolean[] allVisible = {true, true, true, true, true, true};
        addCube(block, wx, wy, wz, allVisible);
    }

    private float[][] getBlockFaceColors(CrystalBlock block) {
        float r = block.color.x, g = block.color.y, b = block.color.z;
        float[][] cols = new float[6][3];
        int cat = block.shape.texCategory;

        if (cat == 0) {
            // Grass: green top, dirt sides/bottom
            cols[FACE_TOP] = new float[]{r, g, b};
            cols[FACE_BOTTOM] = new float[]{0.52f, 0.37f, 0.26f};
            float[] side = {0.52f, 0.40f, 0.26f};
            cols[FACE_FRONT] = side.clone(); cols[FACE_BACK] = side.clone();
            cols[FACE_RIGHT] = side.clone(); cols[FACE_LEFT] = side.clone();
        } else if (cat == 4) {
            // Wood logs: bark on sides, rings on top/bottom
            float[] rings = {r * 1.4f, g * 1.4f, b * 1.4f};
            cols[FACE_TOP] = rings.clone(); cols[FACE_BOTTOM] = rings.clone();
            float[] bark = {r, g, b};
            cols[FACE_FRONT] = bark.clone(); cols[FACE_BACK] = bark.clone();
            cols[FACE_RIGHT] = bark.clone(); cols[FACE_LEFT] = bark.clone();
        } else {
            // All other blocks: uniform color with slight top/bottom variation
            for (int i = 0; i < 6; i++) cols[i] = new float[]{r, g, b};
            cols[FACE_TOP] = new float[]{
                Math.min(1, r * 1.08f), Math.min(1, g * 1.08f), Math.min(1, b * 1.08f)};
            cols[FACE_BOTTOM] = new float[]{r * 0.9f, g * 0.9f, b * 0.9f};
        }
        return cols;
    }

    public void addRawFace(float x0, float y0, float z0,
                           float x1, float y1, float z1,
                           float x2, float y2, float z2,
                           float x3, float y3, float z3,
                           float nx, float ny, float nz,
                           float r, float g, float b, float blockType) {
        float[][] verts = {{x0,y0,z0},{x1,y1,z1},{x2,y2,z2},{x3,y3,z3}};
        for (float[] v : verts) {
            positions.add(v[0]); positions.add(v[1]); positions.add(v[2]);
            normals.add(nx); normals.add(ny); normals.add(nz);
            colors.add(r); colors.add(g); colors.add(b); colors.add(blockType);
        }
        indices.add(vertexOffset);     indices.add(vertexOffset + 1); indices.add(vertexOffset + 2);
        indices.add(vertexOffset);     indices.add(vertexOffset + 2); indices.add(vertexOffset + 3);
        vertexOffset += 4;
    }

    public Mesh build() {
        if (indices.isEmpty()) return null;
        float[] posArr = new float[positions.size()];
        for (int i = 0; i < posArr.length; i++) posArr[i] = positions.get(i);
        float[] normArr = new float[normals.size()];
        for (int i = 0; i < normArr.length; i++) normArr[i] = normals.get(i);
        float[] colArr = new float[colors.size()];
        for (int i = 0; i < colArr.length; i++) colArr[i] = colors.get(i);
        int[] idxArr = indices.stream().mapToInt(Integer::intValue).toArray();
        return new Mesh(posArr, normArr, colArr, idxArr);
    }

    public void clear() {
        positions.clear(); normals.clear(); colors.clear(); indices.clear(); vertexOffset = 0;
    }

    public boolean isEmpty() { return indices.isEmpty(); }
}


