package com.danigt.net;

import java.io.*;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * TCP client that connects to a GameServer.
 * Runs a read thread, queues incoming packets for the game loop.
 */
public class GameClient {

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private Thread readThread;
    private volatile boolean connected = false;
    private final Queue<Packet> incomingPackets = new ConcurrentLinkedQueue<>();

    public void connect(String host, int port, String playerName) throws IOException {
        socket = new Socket(host, port);
        socket.setTcpNoDelay(true);
        in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
        connected = true;

        // Send CONNECT packet
        send(Packet.connect(playerName));

        // Start reading
        readThread = new Thread(() -> {
            try {
                while (connected) {
                    int typeOrd = in.readUnsignedShort();
                    int length = in.readInt();
                    byte[] data = new byte[length];
                    in.readFully(data);

                    Packet.Type type = Packet.Type.fromOrdinal(typeOrd);
                    if (type != null) {
                        incomingPackets.add(new Packet(type, data));
                    }
                }
            } catch (IOException e) {
                // Disconnected
            } finally {
                connected = false;
            }
        }, "GameClient-Read");
        readThread.setDaemon(true);
        readThread.start();
    }

    public void send(Packet packet) {
        if (!connected) return;
        try {
            byte[] bytes = packet.toBytes();
            synchronized (out) {
                out.write(bytes);
                out.flush();
            }
        } catch (IOException e) {
            connected = false;
        }
    }

    public Packet poll() {
        return incomingPackets.poll();
    }

    public boolean isConnected() { return connected; }

    public void disconnect() {
        connected = false;
        try { if (socket != null) socket.close(); } catch (IOException ignored) {}
    }
}


