package com.danigt.net;

import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * TCP server that runs in a background thread.
 * Accepts client connections, reads packets, relays to all other clients.
 */
public class GameServer {

    private ServerSocket serverSocket;
    private final List<ClientConnection> clients = Collections.synchronizedList(new ArrayList<>());
    private final Queue<Packet> incomingPackets = new ConcurrentLinkedQueue<>();
    private volatile boolean running = false;
    private Thread acceptThread;
    private int nextPlayerId = 1; // 0 = host
    private final long worldSeed;
    private final int port;
    private String hostName = "Host";

    public GameServer(int port, long worldSeed) {
        this.port = port;
        this.worldSeed = worldSeed;
    }

    public void setHostName(String name) { this.hostName = name; }

    public void start() throws IOException {
        serverSocket = new ServerSocket(port);
        serverSocket.setSoTimeout(100); // non-blocking accept
        running = true;

        acceptThread = new Thread(() -> {
            while (running) {
                try {
                    Socket socket = serverSocket.accept();
                    socket.setTcpNoDelay(true);
                    int playerId = nextPlayerId++;
                    ClientConnection conn = new ClientConnection(playerId, socket);
                    conn.start();
                    clients.add(conn);
                } catch (SocketTimeoutException ignored) {
                } catch (IOException e) {
                    if (running) e.printStackTrace();
                }
            }
        }, "GameServer-Accept");
        acceptThread.setDaemon(true);
        acceptThread.start();
    }

    public void stop() {
        running = false;
        synchronized (clients) {
            for (ClientConnection c : clients) c.close();
            clients.clear();
        }
        try { if (serverSocket != null) serverSocket.close(); } catch (IOException ignored) {}
    }

    /** Poll for packets received from clients */
    public Packet poll() {
        return incomingPackets.poll();
    }

    /** Send a packet to all connected clients */
    public void broadcast(Packet packet) {
        byte[] bytes = packet.toBytes();
        synchronized (clients) {
            clients.removeIf(c -> !c.isAlive());
            for (ClientConnection c : clients) {
                c.send(bytes);
            }
        }
    }

    /** Send a packet to all clients except the one with the given id */
    public void broadcastExcept(int excludeId, Packet packet) {
        byte[] bytes = packet.toBytes();
        synchronized (clients) {
            clients.removeIf(c -> !c.isAlive());
            for (ClientConnection c : clients) {
                if (c.playerId != excludeId) {
                    c.send(bytes);
                }
            }
        }
    }

    /** Send to a specific client */
    public void sendTo(int playerId, Packet packet) {
        byte[] bytes = packet.toBytes();
        synchronized (clients) {
            for (ClientConnection c : clients) {
                if (c.playerId == playerId) {
                    c.send(bytes);
                    return;
                }
            }
        }
    }

    public int getPort() { return port; }
    public boolean isRunning() { return running; }

    private class ClientConnection {
        final int playerId;
        final Socket socket;
        private DataInputStream in;
        private DataOutputStream out;
        private Thread readThread;
        private volatile boolean alive = true;
        String playerName = "Player";

        ClientConnection(int playerId, Socket socket) {
            this.playerId = playerId;
            this.socket = socket;
        }

        void start() {
            try {
                in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
                out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
            } catch (IOException e) {
                alive = false;
                return;
            }

            readThread = new Thread(() -> {
                try {
                    while (alive && running) {
                        int typeOrd = in.readUnsignedShort();
                        int length = in.readInt();
                        byte[] data = new byte[length];
                        in.readFully(data);

                        Packet.Type type = Packet.Type.fromOrdinal(typeOrd);
                        if (type == null) continue;

                        Packet packet = new Packet(type, data);

                        if (type == Packet.Type.CONNECT) {
                            // Client connecting — read name, send welcome
                            ByteBuffer buf = packet.reader();
                            playerName = Packet.readString(buf);

                            // Send welcome with world seed
                            send(Packet.welcome(worldSeed).toBytes());

                            // Tell the new client about the host (player 0)
                            send(Packet.playerJoin(0, hostName).toBytes());

                            // Tell the new client about all existing clients
                            synchronized (clients) {
                                for (ClientConnection other : clients) {
                                    if (other.playerId != playerId && other.isAlive()) {
                                        send(Packet.playerJoin(other.playerId, other.playerName).toBytes());
                                    }
                                }
                            }

                            // Notify host of new player
                            incomingPackets.add(Packet.playerJoin(playerId, playerName));

                            // Broadcast join to other clients
                            broadcastExcept(playerId, Packet.playerJoin(playerId, playerName));
                        } else if (type == Packet.Type.PLAYER_UPDATE) {
                            // Rewrite the player id to this connection's id before forwarding
                            ByteBuffer buf = ByteBuffer.wrap(data);
                            buf.putInt(0, playerId);
                            Packet rewritten = new Packet(type, data);
                            incomingPackets.add(rewritten);
                            broadcastExcept(playerId, rewritten);
                        } else if (type == Packet.Type.BLOCK_CHANGE) {
                            incomingPackets.add(packet);
                            broadcastExcept(playerId, packet);
                        } else if (type == Packet.Type.CHAT) {
                            incomingPackets.add(packet);
                            broadcastExcept(playerId, packet);
                        } else if (type == Packet.Type.PING) {
                            // ignore
                        }
                    }
                } catch (IOException e) {
                    // Disconnected
                } finally {
                    alive = false;
                    incomingPackets.add(Packet.playerLeave(playerId));
                    broadcastExcept(playerId, Packet.playerLeave(playerId));
                }
            }, "GameServer-Client-" + playerId);
            readThread.setDaemon(true);
            readThread.start();
        }

        void send(byte[] bytes) {
            if (!alive) return;
            try {
                synchronized (out) {
                    out.write(bytes);
                    out.flush();
                }
            } catch (IOException e) {
                alive = false;
            }
        }

        boolean isAlive() { return alive; }

        void close() {
            alive = false;
            try { socket.close(); } catch (IOException ignored) {}
        }
    }
}


