package com.danigt.net;

import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.util.function.IntSupplier;

public class LanBroadcaster {

    private Thread broadcastThread;
    private volatile boolean running;

    public void start(int gamePort, String worldName, String hostName, IntSupplier playerCount) {
        if (running) return;
        running = true;
        broadcastThread = new Thread(() -> {
            try (DatagramSocket socket = new DatagramSocket()) {
                socket.setBroadcast(true);
                InetAddress broadcastAddr = InetAddress.getByName("255.255.255.255");
                while (running) {
                    try {
                        String msg = "[CRYSTALREALMS]" + gamePort + ":" + playerCount.getAsInt()
                            + ":" + worldName + ":" + hostName;
                        byte[] data = msg.getBytes();
                        DatagramPacket packet = new DatagramPacket(
                            data, data.length, broadcastAddr, LanDiscovery.DISCOVERY_PORT);
                        socket.send(packet);
                    } catch (Exception ignored) {}
                    Thread.sleep(2000);
                }
            } catch (Exception ignored) {}
        }, "LanBroadcaster");
        broadcastThread.setDaemon(true);
        broadcastThread.start();
    }

    public void stop() {
        running = false;
        if (broadcastThread != null) {
            broadcastThread.interrupt();
            broadcastThread = null;
        }
    }
}


