package com.danigt.net;

import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class LanDiscovery {

    public static final int DISCOVERY_PORT = 25564;
    private static final String PREFIX = "[CRYSTALREALMS]";

    public static class LanServerInfo {
        public String ip;
        public int port;
        public int playerCount;
        public String worldName;
        public String hostName;
        public long lastSeen;
    }

    private Thread listenerThread;
    private volatile boolean running;
    private final List<LanServerInfo> servers = new CopyOnWriteArrayList<>();

    public void start() {
        if (running) return;
        running = true;
        listenerThread = new Thread(() -> {
            try (DatagramSocket socket = new DatagramSocket(DISCOVERY_PORT)) {
                socket.setBroadcast(true);
                socket.setSoTimeout(1000);
                byte[] buf = new byte[256];
                while (running) {
                    try {
                        DatagramPacket packet = new DatagramPacket(buf, buf.length);
                        socket.receive(packet);
                        String msg = new String(packet.getData(), 0, packet.getLength());
                        if (msg.startsWith(PREFIX)) {
                            parseServer(msg.substring(PREFIX.length()), packet.getAddress().getHostAddress());
                        }
                    } catch (Exception ignored) {
                        // Timeout or parse error
                    }
                }
            } catch (Exception e) {
                // Port in use or other error
            }
        }, "LanDiscovery");
        listenerThread.setDaemon(true);
        listenerThread.start();
    }

    private void parseServer(String data, String ip) {
        // Format: port:playerCount:worldName:hostName
        String[] parts = data.split(":", 4);
        if (parts.length < 4) return;
        try {
            int port = Integer.parseInt(parts[0]);
            int playerCount = Integer.parseInt(parts[1]);
            String worldName = parts[2];
            String hostName = parts[3];

            // Update existing or add new
            for (LanServerInfo s : servers) {
                if (s.ip.equals(ip) && s.port == port) {
                    s.playerCount = playerCount;
                    s.worldName = worldName;
                    s.hostName = hostName;
                    s.lastSeen = System.currentTimeMillis();
                    return;
                }
            }
            LanServerInfo info = new LanServerInfo();
            info.ip = ip;
            info.port = port;
            info.playerCount = playerCount;
            info.worldName = worldName;
            info.hostName = hostName;
            info.lastSeen = System.currentTimeMillis();
            servers.add(info);
        } catch (NumberFormatException ignored) {}
    }

    public void update() {
        long now = System.currentTimeMillis();
        servers.removeIf(s -> now - s.lastSeen > 6000);
    }

    public List<LanServerInfo> getServers() {
        return new ArrayList<>(servers);
    }

    public void stop() {
        running = false;
        if (listenerThread != null) {
            listenerThread.interrupt();
            listenerThread = null;
        }
        servers.clear();
    }
}


// ===== src/main/java/com/danigt/net/NetworkManager.java =====
package com.danigt.net;

import com.danigt.entity.Player;
import com.danigt.world.CrystalBlock;
import com.danigt.world.CrystalShape;
import com.danigt.world.World;
import org.joml.Vector3f;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.*;

/**
 * High-level network facade used by GameEngine.
 * Handles hosting, joining, sending updates, and processing incoming packets.
 */
public class NetworkManager {

    private GameServer server;
    private GameClient client;
    private LanBroadcaster broadcaster;
    private boolean hosting = false;
    private boolean joined = false;
    private String playerName = "Player";
    private String worldName = "World";
    private long remoteSeed = -1;

    private final Map<Integer, RemotePlayer> remotePlayers = new LinkedHashMap<>();
    private final List<String> pendingChatMessages = new ArrayList<>();
    private final List<int[]> pendingBlockChanges = new ArrayList<>(); // [x,y,z,shape,r*1000,g*1000,b*1000]

    private float updateTimer = 0;
    private static final float UPDATE_INTERVAL = 0.05f; // 20Hz

    public void setPlayerName(String name) { this.playerName = name; }
    public void setWorldName(String name) { this.worldName = name; }

    // === Host ===

    public boolean hostGame(int port, long worldSeed) {
        try {
            server = new GameServer(port, worldSeed);
            server.setHostName(playerName);
            server.start();
            hosting = true;
            // Start LAN broadcaster
            broadcaster = new LanBroadcaster();
            broadcaster.start(port, worldName, playerName, this::getPlayerCount);
            return true;
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }

    // === Join ===

    public boolean joinGame(String host, int port) {
        try {
            client = new GameClient();
            client.connect(host, port, playerName);
            joined = true;
            return true;
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }

    /** Get the world seed received from server (only for clients) */
    public long getRemoteSeed() { return remoteSeed; }
    public boolean hasRemoteSeed() { return remoteSeed >= 0; }

    // === State ===

    public boolean isOnline() { return hosting || joined; }
    public boolean isHosting() { return hosting; }
    public boolean isClient() { return joined && !hosting; }

    // === Send ===

    public void sendPlayerUpdate(Player player, boolean walking) {
        if (player.vanished) return; // Don't send updates when vanished
        Packet packet = Packet.playerUpdate(0,
            player.position.x, player.position.y, player.position.z,
            player.yaw, player.pitch, player.selectedSlot,
            player.isBreaking, walking);

        if (hosting && server != null) {
            // Broadcast to all clients AND relay back through server queue
            // so clients that just joined will see the host's position
            server.broadcast(packet);
        } else if (joined && client != null) {
            client.send(packet);
        }
    }

    public void sendBlockChange(int x, int y, int z, CrystalBlock block) {
        int shapeOrd = block != null ? block.shape.ordinal() : -1;
        float r = block != null ? block.color.x : 0;
        float g = block != null ? block.color.y : 0;
        float b = block != null ? block.color.z : 0;
        Packet packet = Packet.blockChange(x, y, z, shapeOrd, r, g, b);

        if (hosting && server != null) {
            server.broadcast(packet);
        } else if (joined && client != null) {
            client.send(packet);
        }
    }

    public void sendBlockRemove(int x, int y, int z) {
        Packet packet = Packet.blockChange(x, y, z, -1, 0, 0, 0);
        if (hosting && server != null) {
            server.broadcast(packet);
        } else if (joined && client != null) {
            client.send(packet);
        }
    }

    public void sendChat(String message) {
        Packet packet = Packet.chat(playerName, message);
        if (hosting && server != null) {
            server.broadcast(packet);
        } else if (joined && client != null) {
            client.send(packet);
        }
    }

    // === Update (called every frame) ===

    public void update(float dt, Player localPlayer, World world) {
        // Send position updates at fixed rate
        updateTimer += dt;
        if (updateTimer >= UPDATE_INTERVAL) {
            updateTimer = 0;
            boolean walking = localPlayer.velocity.x != 0 || localPlayer.velocity.z != 0;
            sendPlayerUpdate(localPlayer, walking);
        }

        // Update remote player interpolation
        for (RemotePlayer rp : remotePlayers.values()) {
            rp.update(dt);
        }

        // Process incoming packets
        Packet packet;
        if (hosting && server != null) {
            while ((packet = server.poll()) != null) {
                processPacket(packet, world);
            }
        }
        if (joined && client != null) {
            while ((packet = client.poll()) != null) {
                processPacket(packet, world);
            }
            if (!client.isConnected()) {
                // Lost connection
                joined = false;
                pendingChatMessages.add("[System] Disconnected from server");
                cleanup();
            }
        }
    }

    private void processPacket(Packet packet, World world) {
        ByteBuffer buf = packet.reader();

        switch (packet.type) {
            case WELCOME -> {
                remoteSeed = buf.getLong();
                pendingChatMessages.add("[System] Connected! Seed: " + remoteSeed);
            }
            case PLAYER_JOIN -> {
                int id = buf.getInt();
                String name = Packet.readString(buf);
                remotePlayers.put(id, new RemotePlayer(id, name));
                pendingChatMessages.add("[System] " + name + " joined the game");
            }
            case PLAYER_LEAVE -> {
                int id = buf.getInt();
                RemotePlayer rp = remotePlayers.remove(id);
                if (rp != null) {
                    pendingChatMessages.add("[System] " + rp.name + " left the game");
                    rp.cleanup();
                }
            }
            case PLAYER_UPDATE -> {
                int id = buf.getInt();
                float x = buf.getFloat(), y = buf.getFloat(), z = buf.getFloat();
                float yaw = buf.getFloat(), pitch = buf.getFloat();
                int slot = buf.getInt();
                boolean breaking = buf.get() == 1;
                boolean walking = buf.get() == 1;

                RemotePlayer rp = remotePlayers.get(id);
                if (rp != null) {
                    rp.setTarget(x, y, z, yaw, pitch, slot, breaking, walking);
                }
            }
            case BLOCK_CHANGE -> {
                int x = buf.getInt(), y = buf.getInt(), z = buf.getInt();
                int shapeOrd = buf.getInt();
                float r = buf.getFloat(), g = buf.getFloat(), b = buf.getFloat();

                if (shapeOrd < 0) {
                    world.removeBlock(x, y, z);
                } else {
                    CrystalShape[] shapes = CrystalShape.values();
                    if (shapeOrd < shapes.length) {
                        world.setBlock(x, y, z, new CrystalBlock(shapes[shapeOrd], new Vector3f(r, g, b)));
                    }
                }
            }
            case CHAT -> {
                String sender = Packet.readString(buf);
                String message = Packet.readString(buf);
                pendingChatMessages.add(sender + ": " + message);
            }
            case PING -> {}
            default -> {}
        }
    }

    // === Getters ===

    public Collection<RemotePlayer> getRemotePlayers() {
        return remotePlayers.values();
    }

    public List<String> drainChatMessages() {
        if (pendingChatMessages.isEmpty()) return Collections.emptyList();
        List<String> msgs = new ArrayList<>(pendingChatMessages);
        pendingChatMessages.clear();
        return msgs;
    }

    public int getPlayerCount() {
        return remotePlayers.size() + 1; // +1 for local
    }

    // === Cleanup ===

    public void disconnect() {
        if (broadcaster != null) {
            broadcaster.stop();
            broadcaster = null;
        }
        if (hosting && server != null) {
            server.stop();
            server = null;
        }
        if (joined && client != null) {
            client.disconnect();
            client = null;
        }
        cleanup();
        hosting = false;
        joined = false;
        remoteSeed = -1;
    }

    private void cleanup() {
        for (RemotePlayer rp : remotePlayers.values()) {
            rp.cleanup();
        }
        remotePlayers.clear();
    }
}


// ===== src/main/java/com/danigt/net/Packet.java =====
package com.danigt.net;

import java.io.*;
import java.nio.ByteBuffer;

public class Packet {

    public enum Type {
        CONNECT,        // client→server: name
        WELCOME,        // server→client: seed, playerCount, block changes
        PLAYER_JOIN,    // server→clients: id, name
        PLAYER_LEAVE,   // server→clients: id
        PLAYER_UPDATE,  // both: id, x,y,z, vx,vy,vz, yaw,pitch, slot, breaking, walking
        BLOCK_CHANGE,   // both: x,y,z, shapeOrdinal (-1=remove), r,g,b
        CHAT,           // both: senderName, message
        PING;           // keepalive

        public static Type fromOrdinal(int ord) {
            Type[] vals = values();
            return ord >= 0 && ord < vals.length ? vals[ord] : null;
        }
    }

    public final Type type;
    public final byte[] data;

    public Packet(Type type, byte[] data) {
        this.type = type;
        this.data = data;
    }

    /** Serialize to bytes: [2-byte type][4-byte length][data] */
    public byte[] toBytes() {
        ByteBuffer buf = ByteBuffer.allocate(6 + data.length);
        buf.putShort((short) type.ordinal());
        buf.putInt(data.length);
        buf.put(data);
        return buf.array();
    }

    // === Builder helpers ===

    public static Packet connect(String name) {
        return new Packet(Type.CONNECT, writeString(name));
    }

    public static Packet welcome(long seed) {
        ByteBuffer buf = ByteBuffer.allocate(8);
        buf.putLong(seed);
        return new Packet(Type.WELCOME, buf.array());
    }

    public static Packet playerJoin(int id, String name) {
        ByteBuffer buf = ByteBuffer.allocate(4 + 4 + name.length());
        buf.putInt(id);
        byte[] nameBytes = name.getBytes();
        buf.putInt(nameBytes.length);
        buf.put(nameBytes);
        return new Packet(Type.PLAYER_JOIN, buf.array());
    }

    public static Packet playerLeave(int id) {
        ByteBuffer buf = ByteBuffer.allocate(4);
        buf.putInt(id);
        return new Packet(Type.PLAYER_LEAVE, buf.array());
    }

    public static Packet playerUpdate(int id, float x, float y, float z,
                                       float yaw, float pitch, int slot,
                                       boolean breaking, boolean walking) {
        ByteBuffer buf = ByteBuffer.allocate(4 + 6*4 + 4 + 2);
        buf.putInt(id);
        buf.putFloat(x);
        buf.putFloat(y);
        buf.putFloat(z);
        buf.putFloat(yaw);
        buf.putFloat(pitch);
        buf.putInt(slot);
        buf.put((byte)(breaking ? 1 : 0));
        buf.put((byte)(walking ? 1 : 0));
        return new Packet(Type.PLAYER_UPDATE, buf.array());
    }

    public static Packet blockChange(int x, int y, int z, int shapeOrdinal, float r, float g, float b) {
        ByteBuffer buf = ByteBuffer.allocate(4*4 + 3*4);
        buf.putInt(x);
        buf.putInt(y);
        buf.putInt(z);
        buf.putInt(shapeOrdinal);
        buf.putFloat(r);
        buf.putFloat(g);
        buf.putFloat(b);
        return new Packet(Type.BLOCK_CHANGE, buf.array());
    }

    public static Packet chat(String sender, String message) {
        byte[] sBytes = sender.getBytes();
        byte[] mBytes = message.getBytes();
        ByteBuffer buf = ByteBuffer.allocate(4 + sBytes.length + 4 + mBytes.length);
        buf.putInt(sBytes.length);
        buf.put(sBytes);
        buf.putInt(mBytes.length);
        buf.put(mBytes);
        return new Packet(Type.CHAT, buf.array());
    }

    public static Packet ping() {
        return new Packet(Type.PING, new byte[0]);
    }

    // === Read helpers ===

    public ByteBuffer reader() {
        return ByteBuffer.wrap(data);
    }

    public static String readString(ByteBuffer buf) {
        int len = buf.getInt();
        byte[] bytes = new byte[len];
        buf.get(bytes);
        return new String(bytes);
    }

    private static byte[] writeString(String s) {
        byte[] bytes = s.getBytes();
        ByteBuffer buf = ByteBuffer.allocate(4 + bytes.length);
        buf.putInt(bytes.length);
        buf.put(bytes);
        return buf.array();
    }
}


