package com.danigt.net;

import com.danigt.entity.CharacterModel;
import org.joml.Vector3f;

public class RemotePlayer {

    public final int id;
    public final String name;

    // Current state (latest from network)
    public final Vector3f position = new Vector3f(0, 50, 0);
    public float yaw = -90f, pitch = 0f;
    public int selectedSlot = 0;
    public boolean isBreaking = false;
    public boolean walking = false;

    // Interpolation targets
    private final Vector3f targetPos = new Vector3f(0, 50, 0);
    private float targetYaw = -90f, targetPitch = 0f;

    // Character model for rendering
    public final CharacterModel model = new CharacterModel();

    public RemotePlayer(int id, String name) {
        this.id = id;
        this.name = name;
    }

    public void setTarget(float x, float y, float z, float yaw, float pitch,
                          int slot, boolean breaking, boolean walking) {
        targetPos.set(x, y, z);
        targetYaw = yaw;
        targetPitch = pitch;
        this.selectedSlot = slot;
        this.isBreaking = breaking;
        this.walking = walking;
    }

    public void update(float dt) {
        // Smooth interpolation towards target
        float lerpSpeed = 12f * dt;
        position.lerp(targetPos, Math.min(1f, lerpSpeed));
        yaw += (targetYaw - yaw) * Math.min(1f, lerpSpeed);
        pitch += (targetPitch - pitch) * Math.min(1f, lerpSpeed);

        model.update(dt, walking);
    }

    public void cleanup() {
        model.cleanup();
    }
}


