package com.danigt.render;

import org.joml.Matrix4f;
import org.joml.Vector3f;

public class Camera {

    private final Vector3f position = new Vector3f(0, 0, 0);
    private float yaw = -90f;   // looking along -Z
    private float pitch = 0f;
    private boolean thirdPerson = false;
    private float thirdPersonDistance = 5f;

    private static final float MOUSE_SENSITIVITY = 0.1f;
    private static final float FOV = 70f;
    private static final float NEAR = 0.1f;
    private static final float FAR = 500f;

    public void processMouseMovement(double dx, double dy) {
        yaw += (float) dx * MOUSE_SENSITIVITY;
        pitch -= (float) dy * MOUSE_SENSITIVITY;
        pitch = Math.max(-89f, Math.min(89f, pitch));
    }

    public Vector3f getForward() {
        float radYaw = (float) Math.toRadians(yaw);
        float radPitch = (float) Math.toRadians(pitch);
        return new Vector3f(
            (float) (Math.cos(radPitch) * Math.cos(radYaw)),
            (float) Math.sin(radPitch),
            (float) (Math.cos(radPitch) * Math.sin(radYaw))
        ).normalize();
    }

    public Vector3f getRight() {
        return getForward().cross(new Vector3f(0, 1, 0), new Vector3f()).normalize();
    }

    public Matrix4f getViewMatrix() {
        Vector3f forward = getForward();
        if (thirdPerson) {
            Vector3f camPos = new Vector3f(position).sub(new Vector3f(forward).mul(thirdPersonDistance));
            camPos.y += 2f;
            return new Matrix4f().lookAt(camPos, position, new Vector3f(0, 1, 0));
        }
        Vector3f target = new Vector3f(position).add(forward);
        return new Matrix4f().lookAt(position, target, new Vector3f(0, 1, 0));
    }

    public Matrix4f getProjectionMatrix(float aspectRatio) {
        return new Matrix4f().perspective(
            (float) Math.toRadians(FOV), aspectRatio, NEAR, FAR
        );
    }

    public void setPosition(float x, float y, float z) { position.set(x, y, z); }
    public Vector3f getPosition() { return new Vector3f(position); }
    public float getYaw() { return yaw; }
    public float getPitch() { return pitch; }
    public boolean isThirdPerson() { return thirdPerson; }
    public void toggleThirdPerson() { thirdPerson = !thirdPerson; }
}


