package com.danigt.ui;

import com.danigt.building.BuildingTool;
import com.danigt.building.ColorPicker;
import com.danigt.entity.Player;
import com.danigt.world.CrystalShape;
import org.joml.Vector3f;

public class HUD {

    private final UIRenderer ui;

    public HUD(UIRenderer ui) {
        this.ui = ui;
    }

    public void render(int screenW, int screenH, Player player, BuildingTool currentTool, int fps,
                       String blockName, UIRenderer uiRenderer, float uiScale) {
        ui.begin(screenW, screenH);
        float u = uiScale;

        // ========== Block info at top when holding I ==========
        if (blockName != null && !blockName.isEmpty()) {
            float scale = 4 * u;
            float tw = ui.textWidth(blockName, scale);
            float tx = (screenW - tw) / 2f;
            float ty = 20 * u;
            ui.drawRect(tx - 16 * u, ty - 8 * u, tw + 32 * u, 5 * scale + 20 * u, 0, 0, 0, 0.75f);
            ui.drawRect(tx - 16 * u, ty - 8 * u, tw + 32 * u, 3 * u, 0.2f, 0.8f, 1f, 0.9f);
            ui.drawRect(tx - 16 * u, ty + 5 * scale + 9 * u, tw + 32 * u, 3 * u, 0.2f, 0.8f, 1f, 0.9f);
            ui.drawTextWithShadow(blockName, tx, ty, scale, 0.3f, 1f, 1f, 1f);
        }

        // ========== Breaking progress bar ==========
        if (player.isBreaking && player.breakProgress > 0) {
            float barW = 120 * u, barH = 6 * u;
            float barX = (screenW - barW) / 2f;
            float barY = screenH / 2f + 20 * u;
            ui.drawRect(barX - u, barY - u, barW + 2 * u, barH + 2 * u, 0, 0, 0, 0.7f);
            ui.drawRect(barX, barY, barW * player.breakProgress, barH, 1f, 0.8f, 0.2f, 0.9f);
        }

        // ========== Crosshair ==========
        float cx = screenW / 2f;
        float cy = screenH / 2f;
        float ch = u; // crosshair scale
        ui.drawRect(cx - 14 * ch, cy - 2 * ch, 28 * ch, 4 * ch, 1, 1, 1, 0.9f);
        ui.drawRect(cx - 2 * ch, cy - 14 * ch, 4 * ch, 28 * ch, 1, 1, 1, 0.9f);
        ui.drawRect(cx - 15 * ch, cy - 3 * ch, 30 * ch, ch, 0, 0, 0, 0.5f);
        ui.drawRect(cx - 15 * ch, cy + 2 * ch, 30 * ch, ch, 0, 0, 0, 0.5f);
        ui.drawRect(cx - 3 * ch, cy - 15 * ch, ch, 30 * ch, 0, 0, 0, 0.5f);
        ui.drawRect(cx + 2 * ch, cy - 15 * ch, ch, 30 * ch, 0, 0, 0, 0.5f);

        // ========== Hotbar (9 slots) ==========
        float slotSize = 42 * u;
        int hotbarSlots = Player.HOTBAR_SIZE;
        float hotbarPad = 3 * u;
        float hotbarW = hotbarSlots * (slotSize + hotbarPad) + hotbarPad;
        float hotbarX = (screenW - hotbarW) / 2f;
        float hotbarY = screenH - slotSize - 14 * u;

        ui.drawRect(hotbarX, hotbarY, hotbarW, slotSize + 8 * u, 0, 0, 0, 0.65f);
        ui.drawRect(hotbarX, hotbarY, hotbarW, 2 * u, 0.5f, 0.5f, 0.5f, 0.6f);

        for (int i = 0; i < hotbarSlots; i++) {
            float sx = hotbarX + hotbarPad + i * (slotSize + hotbarPad);
            float sy = hotbarY + 4 * u;
            boolean selected = i == player.selectedSlot;

            if (selected) {
                ui.drawRect(sx - 3 * u, sy - 3 * u, slotSize + 6 * u, slotSize + 6 * u, 1, 1, 1, 0.5f);
            }

            ui.drawRect(sx, sy, slotSize, slotSize, 0.15f, 0.15f, 0.15f, 0.8f);

            CrystalShape shape = player.hotbar[i];
            if (shape != null) {
                ui.queueBlockIcon(sx + 3 * u, sy + 3 * u, slotSize - 6 * u, shape);

                // Slot number
                String num = String.valueOf(i + 1);
                ui.drawText(num, sx + 2 * u, sy + 2 * u, 1.5f * u, 0.8f, 0.8f, 0.8f, 0.7f);

                // Inventory count (survival)
                if (!player.creative) {
                    int count = player.inventory.count(shape);
                    String countStr = String.valueOf(count);
                    float countW = ui.textWidth(countStr, 1.5f * u);
                    ui.drawTextWithShadow(countStr, sx + slotSize - countW - 2 * u, sy + slotSize - 10 * u, 1.5f * u,
                        count > 0 ? 1f : 0.5f, count > 0 ? 1f : 0.3f, count > 0 ? 1f : 0.3f, 0.9f);
                }
            }
        }

        // Selected block name below hotbar
        CrystalShape selShape = player.getSelectedShape();
        if (selShape != null) {
            String selName = selShape.name().replace('_', ' ');
            if (!player.creative) {
                selName += " x" + player.inventory.count(selShape);
            }
            float nameScale = 2.5f * u;
            float nameW = ui.textWidth(selName, nameScale);
            ui.drawRect((screenW - nameW) / 2f - 6 * u, hotbarY - 20 * u, nameW + 12 * u, 16 * u, 0, 0, 0, 0.5f);
            ui.drawTextWithShadow(selName, (screenW - nameW) / 2f, hotbarY - 18 * u, nameScale, 1f, 1f, 1f, 0.9f);
        }

        // ========== Health/Stamina (survival mode) ==========
        if (!player.creative) {
            float barW = 200 * u, barH = 10 * u;
            float barX = 10 * u, barY = screenH - 80 * u;
            ui.drawRect(barX, barY, barW, barH, 0.15f, 0.15f, 0.15f, 0.7f);
            ui.drawRect(barX, barY, barW * (player.health / (float) player.maxHealth), barH, 0.85f, 0.15f, 0.15f, 0.9f);
            ui.drawText("HP", barX + 2 * u, barY + u, 1.5f * u, 1, 1, 1, 0.8f);
            ui.drawRect(barX, barY + barH + 4 * u, barW, barH, 0.15f, 0.15f, 0.15f, 0.7f);
            float sf = player.stamina / player.maxStamina;
            ui.drawRect(barX, barY + barH + 4 * u, barW * sf, barH, sf > 0.3f ? 0.2f : 0.9f, sf > 0.3f ? 0.8f : 0.5f, 0.3f, 0.9f);
            ui.drawText("SP", barX + 2 * u, barY + barH + 5 * u, 1.5f * u, 1, 1, 1, 0.8f);
        }

        // ========== Tool name (top right) ==========
        String toolName = currentTool.getName();
        float toolScale = 3 * u;
        float toolW = ui.textWidth(toolName, toolScale);
        ui.drawRect(screenW - toolW - 20 * u, 10 * u, toolW + 16 * u, 5 * toolScale + 10 * u, 0, 0, 0, 0.6f);
        ui.drawTextWithShadow(toolName, screenW - toolW - 12 * u, 15 * u, toolScale, 1f, 0.9f, 0.3f, 1f);

        if (currentTool instanceof ColorPicker cp) {
            Vector3f col = cp.getCurrentColor();
            float cpX = screenW - 64 * u, cpY = 5 * toolScale + 28 * u;
            ui.drawRect(cpX - 2 * u, cpY - 2 * u, 54 * u, 54 * u, 1, 1, 1, 0.4f);
            ui.drawRect(cpX, cpY, 50 * u, 50 * u, col.x, col.y, col.z, 1f);
        }

        // ========== FPS (top left) ==========
        String fpsText = "FPS " + fps;
        float fpsScale = 3 * u;
        float fpsW = ui.textWidth(fpsText, fpsScale);
        ui.drawRect(8 * u, 8 * u, fpsW + 12 * u, 5 * fpsScale + 8 * u, 0, 0, 0, 0.5f);
        float fr = fps >= 50 ? 0.3f : fps >= 30 ? 1f : 1f;
        float fg = fps >= 50 ? 1f : fps >= 30 ? 1f : 0.3f;
        ui.drawTextWithShadow(fpsText, 14 * u, 12 * u, fpsScale, fr, fg, 0.2f, 1f);

        // ========== Mode + info panel ==========
        float px = 8 * u, py = 5 * fpsScale + 24 * u, s = 3 * u;
        String modeName = player.creative ? "CREATIVE" : "SURVIVAL";
        float badgeW = ui.textWidth(modeName, s) + 12 * u;
        if (player.creative) {
            ui.drawRect(px, py, badgeW, 5*s+8*u, 0.1f, 0.5f, 0.75f, 0.9f);
            ui.drawRect(px, py, badgeW, 2*u, 0.2f, 0.8f, 1f, 1f);
            ui.drawRect(px, py+5*s+6*u, badgeW, 2*u, 0.2f, 0.8f, 1f, 1f);
            ui.drawTextWithShadow(modeName, px+6*u, py+4*u, s, 0.3f, 1f, 1f, 1f);
        } else {
            ui.drawRect(px, py, badgeW, 5*s+8*u, 0.6f, 0.15f, 0.1f, 0.9f);
            ui.drawRect(px, py, badgeW, 2*u, 1f, 0.4f, 0.2f, 1f);
            ui.drawRect(px, py+5*s+6*u, badgeW, 2*u, 1f, 0.4f, 0.2f, 1f);
            ui.drawTextWithShadow(modeName, px+6*u, py+4*u, s, 1f, 0.6f, 0.3f, 1f);
        }
        py += 5*s+14*u;

        if (player.creative) {
            String flyText = player.flying ? "FLY ON" : "FLY OFF";
            float flyW = ui.textWidth(flyText, s) + 10*u;
            ui.drawRect(px, py, flyW, 5*s+6*u, 0, 0, 0, 0.5f);
            if (player.flying) ui.drawRect(px, py, 3*u, 5*s+6*u, 0.2f, 1f, 0.4f, 0.9f);
            ui.drawTextWithShadow(flyText, px+6*u, py+3*u, s,
                player.flying?0.3f:0.6f, player.flying?1f:0.6f, player.flying?0.4f:0.6f, 1f);
            py += 5*s+10*u;
        }

        if (player.sprinting) {
            ui.drawRect(px, py, ui.textWidth("SPRINT",s)+10*u, 5*s+6*u, 0, 0, 0, 0.5f);
            ui.drawRect(px, py, 3*u, 5*s+6*u, 1f, 0.9f, 0.2f, 0.9f);
            ui.drawTextWithShadow("SPRINT", px+6*u, py+3*u, s, 1f, 0.9f, 0.2f, 1f);
            py += 5*s+10*u;
        }

        String coords = String.format("%.0f, %.0f, %.0f", player.position.x, player.position.y, player.position.z);
        float cs = 2.5f * u;
        ui.drawRect(px, py, ui.textWidth(coords,cs)+10*u, 5*cs+6*u, 0, 0, 0, 0.4f);
        ui.drawTextWithShadow(coords, px+5*u, py+3*u, cs, 0.7f, 0.7f, 0.7f, 0.9f);
        py += 5*cs+12*u;

        float hs = 2 * u;
        ui.drawText("E SPRINT  G MODE  V INV", px, py, hs, 0.5f, 0.5f, 0.5f, 0.7f);
        py += 5*hs+4*u;
        if (player.creative) {
            ui.drawText("F FLY  N NOCLIP  SHIFT DOWN", px, py, hs, 0.5f, 0.5f, 0.5f, 0.7f);
        } else {
            ui.drawText("I INSPECT  F5 3RD  T TOOL", px, py, hs, 0.5f, 0.5f, 0.5f, 0.7f);
        }

        ui.end();
    }
}


// ===== src/main/java/com/danigt/ui/LoginScreen.java =====
package com.danigt.ui;

import com.danigt.engine.Input;
import com.danigt.engine.Window;

import static org.lwjgl.glfw.GLFW.*;

public class LoginScreen {

    public enum LoginResult { NONE, SUCCESS }

    private final StringBuilder usernameInput = new StringBuilder();
    private final StringBuilder passwordInput = new StringBuilder();
    private int focusField = 0; // 0 = username, 1 = password
    private String errorMessage = "";
    private float animTime = 0;
    private boolean isRegistering = false; // true = creating account, false = logging in

    public void onChar(int codepoint) {
        char c = (char) codepoint;
        if (!Character.isLetterOrDigit(c) && c != '_' && c != '-') return;

        if (focusField == 0 && usernameInput.length() < 16) {
            usernameInput.append(c);
        } else if (focusField == 1 && passwordInput.length() < 32) {
            passwordInput.append(c);
        }
    }

    public void onKey(int key, int action, int mods) {
        if (action != GLFW_PRESS && action != GLFW_REPEAT) return;

        if (key == GLFW_KEY_TAB) {
            focusField = (focusField + 1) % 2;
        } else if (key == GLFW_KEY_BACKSPACE) {
            if (focusField == 0 && usernameInput.length() > 0) {
                usernameInput.deleteCharAt(usernameInput.length() - 1);
            } else if (focusField == 1 && passwordInput.length() > 0) {
                passwordInput.deleteCharAt(passwordInput.length() - 1);
            }
        } else if (key == GLFW_KEY_ENTER) {
            trySubmit();
        }
    }

    private void trySubmit() {
        String user = usernameInput.toString().trim();
        String pass = passwordInput.toString();

        if (user.isEmpty()) {
            errorMessage = "ENTER A USERNAME";
            return;
        }
        if (pass.length() < 3) {
            errorMessage = "PASSWORD MUST BE AT LEAST 3 CHARACTERS";
            return;
        }

        if (isRegistering) {
            if (ProfileManager.accountExists(user)) {
                errorMessage = "USERNAME ALREADY TAKEN";
                return;
            }
            if (ProfileManager.register(user, pass)) {
                errorMessage = "";
            } else {
                errorMessage = "FAILED TO CREATE ACCOUNT";
            }
        } else {
            if (!ProfileManager.accountExists(user)) {
                errorMessage = "ACCOUNT NOT FOUND  CLICK REGISTER";
                return;
            }
            if (ProfileManager.login(user, pass)) {
                errorMessage = "";
            } else {
                errorMessage = "WRONG PASSWORD";
            }
        }
    }

    public LoginResult update(float dt, Input input, Window window) {
        animTime += dt;

        if (ProfileManager.getCurrentUsername() != null) {
            return LoginResult.SUCCESS;
        }

        // Mouse clicks
        if (input.isButtonPressed(0)) {
            handleClick(input, window);
        }

        return LoginResult.NONE;
    }

    private void handleClick(Input input, Window window) {
        int screenW = window.getWidth();
        int screenH = window.getHeight();
        float scale = window.getContentScaleX();
        double mx = input.getMouseX() * scale;
        double my = input.getMouseY() * scale;
        float s = Math.max(1.0f, screenH / 720.0f);

        float panelW = 400 * s;
        float panelX = (screenW - panelW) / 2f;
        float fieldH = 50 * s;
        float pad = 10 * s;

        float y = screenH / 2f - 100 * s;

        // Username field
        if (mx >= panelX && mx <= panelX + panelW && my >= y && my <= y + fieldH) {
            focusField = 0;
            return;
        }
        y += fieldH + pad;

        // Password field
        if (mx >= panelX && mx <= panelX + panelW && my >= y && my <= y + fieldH) {
            focusField = 1;
            return;
        }
        y += fieldH + pad + 10 * s;

        // Submit button
        float btnW = 180 * s;
        float btnH = 45 * s;
        float btnX = panelX;
        if (mx >= btnX && mx <= btnX + btnW && my >= y && my <= y + btnH) {
            trySubmit();
            return;
        }

        // Toggle register/login button
        float toggleX = panelX + panelW - btnW;
        if (mx >= toggleX && mx <= toggleX + btnW && my >= y && my <= y + btnH) {
            isRegistering = !isRegistering;
            errorMessage = "";
        }
    }

    public void render(int screenW, int screenH, UIRenderer ui, float uiScale) {
        ui.begin(screenW, screenH);
        float s = uiScale;

        // Background
        ui.drawRect(0, 0, screenW, screenH, 0.06f, 0.06f, 0.1f, 1f);

        // Animated bar
        float barAlpha = (float)(Math.sin(animTime * 0.5) * 0.15 + 0.85);
        ui.drawRect(0, 0, screenW, 4 * s, 0.3f, 0.7f, 1f, barAlpha);

        float panelW = 400 * s;
        float panelX = (screenW - panelW) / 2f;
        float fieldH = 50 * s;
        float pad = 10 * s;

        // Title
        float titleScale = 8 * s;
        String title = "CRYSTAL REALMS";
        float titleW = ui.textWidth(title, titleScale);
        ui.drawTextWithShadow(title, (screenW - titleW) / 2f, screenH / 2f - 220 * s, titleScale, 0.4f, 0.85f, 1f, 1f);

        // Subtitle
        float subScale = 3 * s;
        String sub = isRegistering ? "CREATE YOUR ACCOUNT" : "WELCOME BACK";
        float subW = ui.textWidth(sub, subScale);
        ui.drawTextWithShadow(sub, (screenW - subW) / 2f, screenH / 2f - 140 * s, subScale, 0.6f, 0.6f, 0.7f, 0.9f);

        float y = screenH / 2f - 100 * s;
        float textScale = 2.5f * s;
        float labelScale = 2 * s;
        float blink = (float)(Math.sin(animTime * 4) > 0 ? 1 : 0);

        // Username field
        boolean userFocused = focusField == 0;
        ui.drawRect(panelX, y, panelW, fieldH, 0.14f, 0.14f, 0.19f, 0.95f);
        ui.drawRect(panelX, y, panelW, 2 * s, userFocused ? 0.3f : 0.2f, userFocused ? 0.8f : 0.3f, userFocused ? 1f : 0.4f, 0.9f);
        ui.drawText("USERNAME", panelX + 10 * s, y + 4 * s, labelScale, 0.5f, 0.5f, 0.6f, 0.6f);
        String userDisplay = usernameInput.toString() + (userFocused && blink > 0 ? "|" : "");
        if (usernameInput.length() == 0) userDisplay = (userFocused ? "|" : "");
        ui.drawText(userDisplay, panelX + 10 * s, y + fieldH / 2f - textScale * 1.2f + 4 * s, textScale,
            0.9f, 0.9f, 1f, 0.9f);
        y += fieldH + pad;

        // Password field
        boolean passFocused = focusField == 1;
        ui.drawRect(panelX, y, panelW, fieldH, 0.14f, 0.14f, 0.19f, 0.95f);
        ui.drawRect(panelX, y, panelW, 2 * s, passFocused ? 0.3f : 0.2f, passFocused ? 0.8f : 0.3f, passFocused ? 1f : 0.4f, 0.9f);
        ui.drawText("PASSWORD", panelX + 10 * s, y + 4 * s, labelScale, 0.5f, 0.5f, 0.6f, 0.6f);
        // Show dots for password
        StringBuilder dots = new StringBuilder();
        for (int i = 0; i < passwordInput.length(); i++) dots.append("*");
        String passDisplay = dots.toString() + (passFocused && blink > 0 ? "|" : "");
        ui.drawText(passDisplay, panelX + 10 * s, y + fieldH / 2f - textScale * 1.2f + 4 * s, textScale,
            0.9f, 0.9f, 1f, 0.9f);
        y += fieldH + pad;

        // Error message
        if (!errorMessage.isEmpty()) {
            float errScale = 2 * s;
            ui.drawText(errorMessage, panelX + 10 * s, y, errScale, 1f, 0.35f, 0.35f, 0.9f);
        }
        y += 10 * s;

        // Buttons
        float btnW = 180 * s;
        float btnH = 45 * s;
        float btnTextScale = 3 * s;

        // Submit button
        ui.drawRect(panelX, y, btnW, btnH, 0.2f, 0.55f, 0.25f, 0.9f);
        String submitText = isRegistering ? "REGISTER" : "LOGIN";
        float submitW = ui.textWidth(submitText, btnTextScale);
        ui.drawTextWithShadow(submitText, panelX + (btnW - submitW) / 2f, y + (btnH - btnTextScale * 5) / 2f, btnTextScale, 1f, 1f, 1f, 1f);

        // Toggle button
        float toggleX = panelX + panelW - btnW;
        ui.drawRect(toggleX, y, btnW, btnH, 0.25f, 0.25f, 0.35f, 0.9f);
        String toggleText = isRegistering ? "BACK TO LOGIN" : "REGISTER";
        float toggleW = ui.textWidth(toggleText, btnTextScale);
        ui.drawTextWithShadow(toggleText, toggleX + (btnW - toggleW) / 2f, y + (btnH - btnTextScale * 5) / 2f, btnTextScale, 0.7f, 0.7f, 0.8f, 1f);

        // Hint
        y += btnH + 20 * s;
        float hintScale = 1.8f * s;
        String hint = "TAB TO SWITCH FIELDS  ENTER TO SUBMIT";
        float hintW = ui.textWidth(hint, hintScale);
        ui.drawText(hint, (screenW - hintW) / 2f, y, hintScale, 0.35f, 0.35f, 0.45f, 0.5f);

        ui.end();
    }
}


// ===== src/main/java/com/danigt/ui/MainMenu.java =====
package com.danigt.ui;

import com.danigt.engine.Input;
import com.danigt.engine.Window;
import com.danigt.net.LanDiscovery;
import com.danigt.world.WorldSaveManager;

import java.util.ArrayList;
import java.util.List;

import static org.lwjgl.glfw.GLFW.*;

public class MainMenu {

    public enum ActionType { NONE, LOAD_WORLD, CREATE_WORLD, JOIN_SERVER, DELETE_WORLD, LOGOUT }

    public static class Result {
        public ActionType action = ActionType.NONE;
        public String worldName;
        public long seed;
        public String serverIp;
        public int serverPort;
    }

    private List<WorldSaveManager.WorldInfo> savedWorlds = new ArrayList<>();
    private List<LanDiscovery.LanServerInfo> lanServers = new ArrayList<>();
    private int selectedIndex = -1;
    private float scrollOffset = 0;
    private boolean creatingWorld = false;
    private int createInputFocus = 0; // 0 = name, 1 = seed
    private final StringBuilder worldNameInput = new StringBuilder();
    private final StringBuilder seedInput = new StringBuilder();
    private Result pendingResult = null;
    private float animTime = 0;
    private int deleteConfirmIndex = -1; // which world is pending delete confirmation
    private float deleteConfirmTimer = 0;

    public void refreshWorldList() {
        savedWorlds = WorldSaveManager.listWorlds();
        deleteConfirmIndex = -1;
    }

    public void setLanServers(List<LanDiscovery.LanServerInfo> servers) {
        this.lanServers = servers;
    }

    public boolean isTyping() { return creatingWorld; }

    public void onChar(int codepoint) {
        if (!creatingWorld) return;
        char c = (char) codepoint;

        if (createInputFocus == 0) {
            // Name input
            if (worldNameInput.length() < 20) {
                if (Character.isLetterOrDigit(c) || c == ' ' || c == '-' || c == '_') {
                    worldNameInput.append(c);
                }
            }
        } else {
            // Seed input - digits only
            if (seedInput.length() < 18) {
                if (Character.isDigit(c)) {
                    seedInput.append(c);
                }
            }
        }
    }

    public void onKey(int key, int action, int mods) {
        if (action != GLFW_PRESS && action != GLFW_REPEAT) return;

        if (creatingWorld) {
            if (key == GLFW_KEY_TAB) {
                createInputFocus = (createInputFocus + 1) % 2;
            } else if (key == GLFW_KEY_BACKSPACE) {
                if (createInputFocus == 0 && worldNameInput.length() > 0) {
                    worldNameInput.deleteCharAt(worldNameInput.length() - 1);
                } else if (createInputFocus == 1 && seedInput.length() > 0) {
                    seedInput.deleteCharAt(seedInput.length() - 1);
                }
            } else if (key == GLFW_KEY_ENTER && worldNameInput.length() > 0) {
                pendingResult = new Result();
                pendingResult.action = ActionType.CREATE_WORLD;
                pendingResult.worldName = worldNameInput.toString();
                pendingResult.seed = parseSeed();
                creatingWorld = false;
                worldNameInput.setLength(0);
                seedInput.setLength(0);
                createInputFocus = 0;
            } else if (key == GLFW_KEY_ESCAPE) {
                creatingWorld = false;
                worldNameInput.setLength(0);
                seedInput.setLength(0);
                createInputFocus = 0;
            }
            return;
        }

        // Cancel delete confirmation on ESC
        if (key == GLFW_KEY_ESCAPE) {
            deleteConfirmIndex = -1;
        }
    }

    private long parseSeed() {
        if (seedInput.length() == 0) return System.currentTimeMillis();
        try {
            return Long.parseLong(seedInput.toString());
        } catch (NumberFormatException e) {
            return seedInput.toString().hashCode();
        }
    }

    public Result update(float dt, Input input, Window window) {
        animTime += dt;

        if (deleteConfirmIndex >= 0) {
            deleteConfirmTimer += dt;
        }

        // Return pending result from keyboard
        if (pendingResult != null) {
            Result r = pendingResult;
            pendingResult = null;
            return r;
        }

        // Scroll
        double scroll = input.getScrollDY();
        if (scroll != 0) {
            scrollOffset -= (float) scroll * 30;
            if (scrollOffset < 0) scrollOffset = 0;
        }

        // Mouse click
        if (input.isButtonPressed(0)) {
            return handleClick(input, window);
        }

        Result r = new Result();
        r.action = ActionType.NONE;
        return r;
    }

    private Result handleClick(Input input, Window window) {
        Result r = new Result();
        r.action = ActionType.NONE;

        int screenW = window.getWidth();
        int screenH = window.getHeight();
        float scale = window.getContentScaleX();
        double mx = input.getMouseX() * scale;
        double my = input.getMouseY() * scale;
        float s = Math.max(1.0f, screenH / 720.0f);

        // Logout button (top right)
        float logoutBtnW = 80 * s;
        float logoutBtnH = 30 * s;
        float logoutX = screenW - logoutBtnW - 15 * s;
        float logoutY = 15 * s;
        if (mx >= logoutX && mx <= logoutX + logoutBtnW && my >= logoutY && my <= logoutY + logoutBtnH) {
            r.action = ActionType.LOGOUT;
            return r;
        }

        float panelW = 500 * s;
        float panelX = (screenW - panelW) / 2f;
        float entryH = 50 * s;
        float pad = 8 * s;

        // Match render layout exactly
        float titleScale = 8 * s;
        float headerScale = 3 * s;
        float titleY = 80 * s - scrollOffset;
        float y = titleY + 60 * s + titleScale * 5;

        // YOUR WORLDS header
        y += headerScale * 5 + 10 * s;

        // Create World button
        float createY = y;
        y += entryH + pad;
        if (mx >= panelX && mx <= panelX + panelW && my >= createY && my <= createY + entryH) {
            if (!creatingWorld) {
                creatingWorld = true;
                worldNameInput.setLength(0);
                seedInput.setLength(0);
                createInputFocus = 0;
            }
            deleteConfirmIndex = -1;
            return r;
        }

        // Create world inputs + submit
        if (creatingWorld) {
            // Name input row
            float nameRowY = y;
            y += entryH + pad;

            // Seed input row
            float seedRowY = y;
            y += entryH + pad;

            // Check name field click
            if (mx >= panelX && mx <= panelX + panelW && my >= nameRowY && my <= nameRowY + entryH) {
                createInputFocus = 0;
                return r;
            }

            // Check seed field click (left part)
            float btnW = 100 * s;
            float btnX = panelX + panelW - btnW - 10 * s;
            if (mx >= panelX && mx < btnX && my >= seedRowY && my <= seedRowY + entryH) {
                createInputFocus = 1;
                return r;
            }

            // Check "CREATE" button click (on seed row, right side)
            if (mx >= btnX && mx <= btnX + btnW && my >= seedRowY && my <= seedRowY + entryH) {
                if (worldNameInput.length() > 0) {
                    r.action = ActionType.CREATE_WORLD;
                    r.worldName = worldNameInput.toString();
                    r.seed = parseSeed();
                    creatingWorld = false;
                    worldNameInput.setLength(0);
                    seedInput.setLength(0);
                    createInputFocus = 0;
                    return r;
                }
            }
        }

        // World entries
        float delBtnW = 40 * s;
        for (int i = 0; i < savedWorlds.size(); i++) {
            float entryY = y;
            y += entryH + pad;

            if (my >= entryY && my <= entryY + entryH) {
                // Delete button (right side, small X)
                float delX = panelX + panelW - delBtnW;
                if (mx >= delX && mx <= delX + delBtnW) {
                    if (deleteConfirmIndex == i) {
                        // Second click = confirm delete
                        r.action = ActionType.DELETE_WORLD;
                        r.worldName = savedWorlds.get(i).name;
                        deleteConfirmIndex = -1;
                        return r;
                    } else {
                        deleteConfirmIndex = i;
                        deleteConfirmTimer = 0;
                        return r;
                    }
                }

                // Click on world entry (play)
                if (mx >= panelX && mx < delX) {
                    WorldSaveManager.WorldInfo info = savedWorlds.get(i);
                    r.action = ActionType.LOAD_WORLD;
                    r.worldName = info.name;
                    r.seed = info.seed;
                    deleteConfirmIndex = -1;
                    return r;
                }
            }
        }

        if (savedWorlds.isEmpty()) {
            y += 30 * s;
        }

        // Multiplayer separator + header
        y += 20 * s + 12 * s + headerScale * 5 + 10 * s;

        // LAN server entries
        for (int i = 0; i < lanServers.size(); i++) {
            float entryY = y;
            y += entryH + pad;
            if (mx >= panelX && mx <= panelX + panelW && my >= entryY && my <= entryY + entryH) {
                LanDiscovery.LanServerInfo server = lanServers.get(i);
                r.action = ActionType.JOIN_SERVER;
                r.serverIp = server.ip;
                r.serverPort = server.port;
                r.worldName = server.worldName;
                return r;
            }
        }

        // Clicked somewhere else - cancel delete confirm
        deleteConfirmIndex = -1;
        return r;
    }

    public void render(int screenW, int screenH, UIRenderer ui, float uiScale) {
        ui.begin(screenW, screenH);
        float s = uiScale;

        // Background
        ui.drawRect(0, 0, screenW, screenH, 0.08f, 0.08f, 0.12f, 1f);

        // Animated gradient bar at top
        float barAlpha = (float)(Math.sin(animTime * 0.5) * 0.15 + 0.85);
        ui.drawRect(0, 0, screenW, 4 * s, 0.3f, 0.7f, 1f, barAlpha);

        float panelW = 500 * s;
        float panelX = (screenW - panelW) / 2f;
        float entryH = 50 * s;
        float pad = 8 * s;

        // Title
        float titleScale = 8 * s;
        String title = "CRYSTAL REALMS";
        float titleW = ui.textWidth(title, titleScale);
        float titleY = 80 * s - scrollOffset;
        ui.drawTextWithShadow(title, (screenW - titleW) / 2f, titleY, titleScale, 0.4f, 0.85f, 1f, 1f);

        // Subtitle
        float subScale = 2.5f * s;
        String sub = "SELECT OR CREATE A WORLD";
        float subW = ui.textWidth(sub, subScale);
        ui.drawText(sub, (screenW - subW) / 2f, titleY + titleScale * 5 + 10 * s, subScale, 0.5f, 0.5f, 0.6f, 0.8f);

        float y = titleY + 60 * s + titleScale * 5;

        // === YOUR WORLDS ===
        float headerScale = 3 * s;
        ui.drawTextWithShadow("YOUR WORLDS", panelX, y, headerScale, 0.7f, 0.7f, 0.8f, 0.9f);
        y += headerScale * 5 + 10 * s;

        // Create World button
        float createBg = (float)(Math.sin(animTime * 2) * 0.02 + 0.18);
        ui.drawRect(panelX, y, panelW, entryH, createBg, 0.35f, 0.15f, 0.9f);
        ui.drawRect(panelX, y, 4 * s, entryH, 0.3f, 0.9f, 0.4f, 0.9f);
        float createTextScale = 3 * s;
        ui.drawTextWithShadow("+ CREATE NEW WORLD", panelX + 14 * s, y + entryH / 2f - createTextScale * 2.5f, createTextScale, 0.4f, 1f, 0.5f, 1f);
        y += entryH + pad;

        // Create world inputs
        if (creatingWorld) {
            float inputScale = 2.5f * s;
            float blink = (float)(Math.sin(animTime * 4) > 0 ? 1 : 0);

            // Name input row
            boolean nameFocused = createInputFocus == 0;
            ui.drawRect(panelX, y, panelW, entryH, 0.15f, 0.15f, 0.2f, 0.95f);
            ui.drawRect(panelX, y, panelW, 2 * s, nameFocused ? 0.3f : 0.2f, nameFocused ? 0.9f : 0.4f, nameFocused ? 0.4f : 0.3f, 0.8f);

            // Label
            float labelScale = 2 * s;
            ui.drawText("NAME", panelX + 10 * s, y + 4 * s, labelScale, 0.5f, 0.5f, 0.6f, 0.6f);

            String nameText = worldNameInput.toString();
            String nameDisplay = nameText + (nameFocused && blink > 0 ? "|" : "");
            if (nameText.isEmpty() && nameFocused) nameDisplay = "ENTER WORLD NAME" + (blink > 0 ? "|" : "");
            else if (nameText.isEmpty()) nameDisplay = "ENTER WORLD NAME";
            ui.drawText(nameDisplay, panelX + 10 * s, y + entryH / 2f - inputScale * 1.5f + 4 * s, inputScale,
                nameText.isEmpty() ? 0.4f : 0.9f, nameText.isEmpty() ? 0.4f : 0.9f, nameText.isEmpty() ? 0.4f : 0.9f, 0.8f);
            y += entryH + pad;

            // Seed input row
            boolean seedFocused = createInputFocus == 1;
            ui.drawRect(panelX, y, panelW, entryH, 0.15f, 0.15f, 0.2f, 0.95f);
            ui.drawRect(panelX, y, panelW, 2 * s, seedFocused ? 0.3f : 0.2f, seedFocused ? 0.9f : 0.4f, seedFocused ? 0.4f : 0.3f, 0.8f);

            // Label
            ui.drawText("SEED", panelX + 10 * s, y + 4 * s, labelScale, 0.5f, 0.5f, 0.6f, 0.6f);

            String seedText = seedInput.toString();
            String seedDisplay = seedText + (seedFocused && blink > 0 ? "|" : "");
            if (seedText.isEmpty() && seedFocused) seedDisplay = "RANDOM" + (blink > 0 ? "|" : "");
            else if (seedText.isEmpty()) seedDisplay = "RANDOM";
