            // Delete button
            float delX = panelX + panelW - delBtnW;
            if (deleteConfirmIndex == i) {
                // Confirm state - red background, flashing
                float flash = (float)(Math.sin(animTime * 6) * 0.1 + 0.9);
                ui.drawRect(delX, y, delBtnW, entryH, 0.7f * flash, 0.15f, 0.15f, 0.95f);
                float delTextScale = 2 * s;
                String delText = "DEL?";
                float delTextW = ui.textWidth(delText, delTextScale);
                ui.drawTextWithShadow(delText, delX + (delBtnW - delTextW) / 2f, y + entryH / 2f - delTextScale * 2.5f, delTextScale, 1f, 0.4f, 0.4f, 1f);
            } else {
                // Normal X button
                ui.drawRect(delX, y, delBtnW, entryH, 0.2f, 0.15f, 0.15f, 0.7f);
                float delTextScale = 3 * s;
                String xText = "X";
                float xW = ui.textWidth(xText, delTextScale);
                ui.drawText(xText, delX + (delBtnW - xW) / 2f, y + entryH / 2f - delTextScale * 2.5f, delTextScale, 0.7f, 0.3f, 0.3f, 0.8f);
            }

            y += entryH + pad;
        }

        if (savedWorlds.isEmpty()) {
            float emptyScale = 2 * s;
            ui.drawText("NO SAVED WORLDS YET", panelX + 14 * s, y + 5 * s, emptyScale, 0.4f, 0.4f, 0.5f, 0.6f);
