        y += 20 * s;
        ui.drawRect(panelX, y, panelW, 2 * s, 0.3f, 0.3f, 0.4f, 0.5f);
        y += 12 * s;
        ui.drawTextWithShadow("MULTIPLAYER  LAN", panelX, y, headerScale, 0.7f, 0.7f, 0.8f, 0.9f);
        y += headerScale * 5 + 10 * s;

        if (lanServers.isEmpty()) {
            float emptyScale = 2 * s;
            String scanning = "SCANNING FOR LAN GAMES";
            float dots = (int)(animTime * 2) % 4;
            for (int d = 0; d < dots; d++) scanning += ".";
            ui.drawText(scanning, panelX + 14 * s, y + 5 * s, emptyScale, 0.4f, 0.4f, 0.5f, 0.6f);
            y += 30 * s;
        } else {
            for (int i = 0; i < lanServers.size(); i++) {
                LanDiscovery.LanServerInfo server = lanServers.get(i);
                ui.drawRect(panelX, y, panelW, entryH, 0.14f, 0.18f, 0.14f, 0.9f);
                ui.drawRect(panelX, y, 4 * s, entryH, 0.4f, 1f, 0.5f, 0.8f);

                float nameScale = 3 * s;
