                ui.drawText(detail, panelX + 14 * s, y + entryH - 14 * s, detailScale, 0.5f, 0.6f, 0.5f, 0.7f);

                // Join arrow
                float arrowX = panelX + panelW - 40 * s;
                ui.drawTextWithShadow(">", arrowX, y + entryH / 2f - nameScale * 2.5f, nameScale, 0.4f, 1f, 0.5f, 0.8f);

                y += entryH + pad;
            }
        }

        // Bottom hint
        y += 20 * s;
        float hintScale = 2 * s;
        String hint = "CLICK A WORLD TO PLAY  SCROLL TO BROWSE";
        float hintW = ui.textWidth(hint, hintScale);
        ui.drawText(hint, (screenW - hintW) / 2f, y, hintScale, 0.35f, 0.35f, 0.45f, 0.6f);

        // Logged in as + Logout button (top right)
        String username = com.danigt.ui.ProfileManager.getCurrentUsername();
        if (username != null) {
            float logoutScale = 2.2f * s;
            float logoutBtnW = 80 * s;
