            float userW = ui.textWidth(userLabel, logoutScale);
            ui.drawText(userLabel, logoutX - userW - 10 * s, logoutY + logoutBtnH / 2f - logoutScale * 2.5f, logoutScale, 0.5f, 0.5f, 0.6f, 0.7f);
