package com.danigt.ui;

import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;

/**
 * Manages user profiles stored in ~/.crystalrealms/profiles/
 * Each profile is a file: username.dat containing the hashed password.
 */
public class ProfileManager {

    private static final Path PROFILES_DIR = Paths.get(System.getProperty("user.home"), ".crystalrealms", "profiles");
    private static final Path ACTIVE_FILE = Paths.get(System.getProperty("user.home"), ".crystalrealms", "active_profile.txt");

    private static String currentUsername;

    public static void init() {
        try {
            Files.createDirectories(PROFILES_DIR);
        } catch (IOException ignored) {}
    }

    /** Check if there's a saved active profile (auto-login) */
    public static boolean hasActiveProfile() {
        if (Files.exists(ACTIVE_FILE)) {
            try {
                String name = Files.readString(ACTIVE_FILE).trim();
                if (!name.isEmpty() && Files.exists(PROFILES_DIR.resolve(name + ".dat"))) {
                    currentUsername = name;
                    return true;
                }
            } catch (IOException ignored) {}
        }
        return false;
    }

    public static String getCurrentUsername() {
        return currentUsername;
    }

    /** Register a new account. Returns true if successful, false if username taken. */
    public static boolean register(String username, String password) {
        Path file = PROFILES_DIR.resolve(username + ".dat");
        if (Files.exists(file)) return false;
        try {
            Files.writeString(file, hashPassword(password));
            currentUsername = username;
            saveActiveProfile(username);
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    /** Login with existing account. Returns true if credentials match. */
    public static boolean login(String username, String password) {
        Path file = PROFILES_DIR.resolve(username + ".dat");
        if (!Files.exists(file)) return false;
        try {
            String stored = Files.readString(file).trim();
            if (stored.equals(hashPassword(password))) {
                currentUsername = username;
                saveActiveProfile(username);
                return true;
            }
        } catch (IOException ignored) {}
        return false;
    }

    public static boolean accountExists(String username) {
        return Files.exists(PROFILES_DIR.resolve(username + ".dat"));
    }

    public static void logout() {
        currentUsername = null;
        try { Files.deleteIfExists(ACTIVE_FILE); } catch (IOException ignored) {}
    }

    private static void saveActiveProfile(String username) {
        try {
            Files.writeString(ACTIVE_FILE, username);
        } catch (IOException ignored) {}
    }

    private static String hashPassword(String password) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(password.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            return password; // fallback
        }
    }
}


