package com.danigt.ui;

import com.danigt.render.ShaderProgram;
import com.danigt.resource.ResourceLoader;
import com.danigt.world.CrystalShape;
import org.joml.Matrix4f;
import org.lwjgl.system.MemoryUtil;

import java.nio.FloatBuffer;
import java.nio.IntBuffer;
import java.util.ArrayList;
import java.util.List;

import static org.lwjgl.opengl.GL33.*;

public class UIRenderer {

    private ShaderProgram shader;
    private int vaoId, posVboId, colorVboId, eboId;

    // Pending 3D block icons to render after 2D pass
    public static class BlockIconRequest {
        public float x, y, size;
        public CrystalShape shape;
        public BlockIconRequest(float x, float y, float size, CrystalShape shape) {
            this.x = x; this.y = y; this.size = size; this.shape = shape;
        }
    }
    private final List<BlockIconRequest> pendingBlockIcons = new ArrayList<>();

    public void queueBlockIcon(float x, float y, float size, CrystalShape shape) {
        pendingBlockIcons.add(new BlockIconRequest(x, y, size, shape));
    }

    public List<BlockIconRequest> drainBlockIcons() {
        if (pendingBlockIcons.isEmpty()) return List.of();
        List<BlockIconRequest> result = new ArrayList<>(pendingBlockIcons);
        pendingBlockIcons.clear();
        return result;
    }

    // Batch buffers
    private static final int MAX_QUADS = 16000;
    private final float[] positions = new float[MAX_QUADS * 8];  // 4 verts * 2 coords
    private final float[] colors = new float[MAX_QUADS * 16];    // 4 verts * 4 rgba
    private final int[] indices = new int[MAX_QUADS * 6];
    private int quadCount = 0;

    public void init() {
        shader = new ShaderProgram();
        shader.createVertexShader(ResourceLoader.loadResource("/shaders/ui_vertex.glsl"));
        shader.createFragmentShader(ResourceLoader.loadResource("/shaders/ui_fragment.glsl"));
        shader.link();

        vaoId = glGenVertexArrays();
        glBindVertexArray(vaoId);

        posVboId = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, posVboId);
        glBufferData(GL_ARRAY_BUFFER, (long) MAX_QUADS * 8 * Float.BYTES, GL_DYNAMIC_DRAW);
        glVertexAttribPointer(0, 2, GL_FLOAT, false, 0, 0);
        glEnableVertexAttribArray(0);

        colorVboId = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, colorVboId);
        glBufferData(GL_ARRAY_BUFFER, (long) MAX_QUADS * 16 * Float.BYTES, GL_DYNAMIC_DRAW);
        glVertexAttribPointer(1, 4, GL_FLOAT, false, 0, 0);
        glEnableVertexAttribArray(1);

        eboId = glGenBuffers();
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, eboId);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, (long) MAX_QUADS * 6 * Integer.BYTES, GL_DYNAMIC_DRAW);

        glBindVertexArray(0);
    }

    public void begin(int screenWidth, int screenHeight) {
        quadCount = 0;
        shader.bind();
        Matrix4f ortho = new Matrix4f().ortho(0, screenWidth, screenHeight, 0, -1, 1);
        shader.setUniform("projection", ortho);
    }

    public void drawRect(float x, float y, float w, float h, float r, float g, float b, float a) {
        if (quadCount >= MAX_QUADS) return;

        int pi = quadCount * 8;
        positions[pi]     = x;     positions[pi + 1] = y;
        positions[pi + 2] = x + w; positions[pi + 3] = y;
        positions[pi + 4] = x + w; positions[pi + 5] = y + h;
        positions[pi + 6] = x;     positions[pi + 7] = y + h;

        int ci = quadCount * 16;
        for (int v = 0; v < 4; v++) {
            colors[ci + v * 4]     = r;
            colors[ci + v * 4 + 1] = g;
            colors[ci + v * 4 + 2] = b;
            colors[ci + v * 4 + 3] = a;
        }

        int ii = quadCount * 6;
        int vo = quadCount * 4;
        indices[ii]     = vo;     indices[ii + 1] = vo + 1; indices[ii + 2] = vo + 2;
        indices[ii + 3] = vo;     indices[ii + 4] = vo + 2; indices[ii + 5] = vo + 3;

        quadCount++;
    }

    public void end() {
        if (quadCount == 0) {
            shader.unbind();
            return;
        }

        glDisable(GL_DEPTH_TEST);
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);

        glBindVertexArray(vaoId);

        // Upload position data
        FloatBuffer posBuf = MemoryUtil.memAllocFloat(quadCount * 8);
        posBuf.put(positions, 0, quadCount * 8).flip();
        glBindBuffer(GL_ARRAY_BUFFER, posVboId);
        glBufferSubData(GL_ARRAY_BUFFER, 0, posBuf);
        MemoryUtil.memFree(posBuf);

        // Upload color data
        FloatBuffer colBuf = MemoryUtil.memAllocFloat(quadCount * 16);
        colBuf.put(colors, 0, quadCount * 16).flip();
        glBindBuffer(GL_ARRAY_BUFFER, colorVboId);
        glBufferSubData(GL_ARRAY_BUFFER, 0, colBuf);
        MemoryUtil.memFree(colBuf);

        // Upload index data
        IntBuffer idxBuf = MemoryUtil.memAllocInt(quadCount * 6);
        idxBuf.put(indices, 0, quadCount * 6).flip();
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, eboId);
        glBufferSubData(GL_ELEMENT_ARRAY_BUFFER, 0, idxBuf);
        MemoryUtil.memFree(idxBuf);

        glDrawElements(GL_TRIANGLES, quadCount * 6, GL_UNSIGNED_INT, 0);

        glBindVertexArray(0);
        glDisable(GL_BLEND);
        glEnable(GL_CULL_FACE);
        glEnable(GL_DEPTH_TEST);
        shader.unbind();
    }

    /** Queue a 3D block icon to be rendered by GameEngine after the 2D pass. */
    public void drawBlockIcon(float x, float y, float size, float r, float g, float b, float a, int texCat) {
        // r,g,b,a unused — we use the shape's actual data via the queue
        // This overload exists for backward compat; callers should switch to queueBlockIcon
    }

    public void drawBlockIcon(float x, float y, float size, CrystalShape shape) {
        queueBlockIcon(x, y, size, shape);
    }

    /**
     * Draw text using a tiny 5x7 pixel font built from rectangles.
     * Each character is drawn as filled rects for the "on" pixels.
     */
    public void drawText(String text, float x, float y, float scale, float r, float g, float b, float a) {
        float charW = 6 * scale;
        float px = x;
        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (ch == ' ') {
                px += charW;
                continue;
            }
            boolean[][] glyph = getGlyph(ch);
            if (glyph != null) {
                for (int row = 0; row < glyph.length; row++) {
                    for (int col = 0; col < glyph[row].length; col++) {
                        if (glyph[row][col]) {
                            drawRect(px + col * scale, y + row * scale, scale, scale, r, g, b, a);
                        }
                    }
                }
            }
            px += charW;
        }
    }

    /** Draw text with a dark shadow behind it for readability. */
    public void drawTextWithShadow(String text, float x, float y, float scale, float r, float g, float b, float a) {
        drawText(text, x + scale, y + scale, scale, 0, 0, 0, a * 0.6f);
        drawText(text, x, y, scale, r, g, b, a);
    }

    /** Returns width of text in pixels at the given scale. */
    public float textWidth(String text, float scale) {
        return text.length() * 6 * scale;
    }

    private static boolean[][] getGlyph(char c) {
        c = Character.toUpperCase(c);
        return switch (c) {
            case 'A' -> new boolean[][]{{false,true,true,true,false},{true,false,false,false,true},{true,true,true,true,true},{true,false,false,false,true},{true,false,false,false,true}};
            case 'B' -> new boolean[][]{{true,true,true,true,false},{true,false,false,false,true},{true,true,true,true,false},{true,false,false,false,true},{true,true,true,true,false}};
