            case 'D' -> new boolean[][]{{true,true,true,true,false},{true,false,false,false,true},{true,false,false,false,true},{true,false,false,false,true},{true,true,true,true,false}};
            case 'E' -> new boolean[][]{{true,true,true,true,true},{true,false,false,false,false},{true,true,true,false,false},{true,false,false,false,false},{true,true,true,true,true}};
            case 'F' -> new boolean[][]{{true,true,true,true,true},{true,false,false,false,false},{true,true,true,false,false},{true,false,false,false,false},{true,false,false,false,false}};
            case 'G' -> new boolean[][]{{false,true,true,true,true},{true,false,false,false,false},{true,false,true,true,true},{true,false,false,false,true},{false,true,true,true,false}};
            case 'H' -> new boolean[][]{{true,false,false,false,true},{true,false,false,false,true},{true,true,true,true,true},{true,false,false,false,true},{true,false,false,false,true}};
            case 'I' -> new boolean[][]{{true,true,true,true,true},{false,false,true,false,false},{false,false,true,false,false},{false,false,true,false,false},{true,true,true,true,true}};
            case 'J' -> new boolean[][]{{false,false,false,false,true},{false,false,false,false,true},{false,false,false,false,true},{true,false,false,false,true},{false,true,true,true,false}};
            case 'K' -> new boolean[][]{{true,false,false,true,false},{true,false,true,false,false},{true,true,false,false,false},{true,false,true,false,false},{true,false,false,true,false}};
            case 'L' -> new boolean[][]{{true,false,false,false,false},{true,false,false,false,false},{true,false,false,false,false},{true,false,false,false,false},{true,true,true,true,true}};
