            case '9' -> new boolean[][]{{false,true,true,true,false},{true,false,false,false,true},{false,true,true,true,true},{false,false,false,false,true},{false,true,true,true,false}};
            case ':' -> new boolean[][]{{false,false,false,false,false},{false,false,true,false,false},{false,false,false,false,false},{false,false,true,false,false},{false,false,false,false,false}};
            case '/' -> new boolean[][]{{false,false,false,false,true},{false,false,false,true,false},{false,false,true,false,false},{false,true,false,false,false},{true,false,false,false,false}};
            case '-' -> new boolean[][]{{false,false,false,false,false},{false,false,false,false,false},{true,true,true,true,true},{false,false,false,false,false},{false,false,false,false,false}};
            case '.' -> new boolean[][]{{false,false,false,false,false},{false,false,false,false,false},{false,false,false,false,false},{false,false,false,false,false},{false,false,true,false,false}};
            case '(' -> new boolean[][]{{false,false,true,false,false},{false,true,false,false,false},{false,true,false,false,false},{false,true,false,false,false},{false,false,true,false,false}};
            case ')' -> new boolean[][]{{false,false,true,false,false},{false,false,false,true,false},{false,false,false,true,false},{false,false,false,true,false},{false,false,true,false,false}};
            case '[' -> new boolean[][]{{false,true,true,false,false},{false,true,false,false,false},{false,true,false,false,false},{false,true,false,false,false},{false,true,true,false,false}};
            case ']' -> new boolean[][]{{false,false,true,true,false},{false,false,false,true,false},{false,false,false,true,false},{false,false,false,true,false},{false,false,true,true,false}};
            case '>' -> new boolean[][]{{true,false,false,false,false},{false,true,false,false,false},{false,false,true,false,false},{false,true,false,false,false},{true,false,false,false,false}};
            case ',' -> new boolean[][]{{false,false,false,false,false},{false,false,false,false,false},{false,false,false,false,false},{false,false,true,false,false},{false,true,false,false,false}};
            case '!' -> new boolean[][]{{false,false,true,false,false},{false,false,true,false,false},{false,false,true,false,false},{false,false,false,false,false},{false,false,true,false,false}};
            case '?' -> new boolean[][]{{false,true,true,true,false},{true,false,false,false,true},{false,false,true,true,false},{false,false,false,false,false},{false,false,true,false,false}};
            default -> null;
        };
    }

    public void cleanup() {
        glDeleteBuffers(posVboId);
        glDeleteBuffers(colorVboId);
        glDeleteBuffers(eboId);
        glDeleteVertexArrays(vaoId);
        if (shader != null) shader.cleanup();
    }
}


