package com.danigt.world;

public enum Biome {
    CRYSTAL_FIELDS("Crystal Fields"),
    MUSHROOM_GROVE("Mushroom Grove"),
    ENCHANTED_FOREST("Enchanted Forest"),
    VOLCANIC_WASTES("Volcanic Wastes"),
    FROZEN_TUNDRA("Frozen Tundra"),
    DESERT("Desert"),
    PLAINS("Plains");

    public final String displayName;

    Biome(String displayName) {
        this.displayName = displayName;
    }

    /** Fuzzy match a biome name (case-insensitive, partial match) */
    public static Biome fromName(String input) {
        String lower = input.toLowerCase().trim();
        for (Biome b : values()) {
            if (b.displayName.toLowerCase().equals(lower)) return b;
        }
        // Partial match
        for (Biome b : values()) {
            if (b.displayName.toLowerCase().contains(lower)) return b;
        }
        // Single word match
        for (Biome b : values()) {
            for (String word : b.displayName.toLowerCase().split(" ")) {
                if (word.equals(lower)) return b;
            }
        }
        return null;
    }
}


