package com.danigt.world;

import com.danigt.math.MeshBuilder;
import com.danigt.render.Mesh;

public class Chunk {

    public static final int SIZE = 16;

    private final int chunkX, chunkY, chunkZ;
    private final CrystalBlock[][][] blocks = new CrystalBlock[SIZE][SIZE][SIZE];
    private final boolean[][][] playerModified = new boolean[SIZE][SIZE][SIZE];
    private boolean generated = false;
    private Mesh mesh;
    private boolean dirty = true;
    private boolean decorated = false;

    // Neighbor chunks for cross-chunk face culling
    private Chunk[] neighbors; // +X, -X, +Y, -Y, +Z, -Z

    public Chunk(int chunkX, int chunkY, int chunkZ) {
        this.chunkX = chunkX;
        this.chunkY = chunkY;
        this.chunkZ = chunkZ;
    }

    public CrystalBlock getBlock(int x, int y, int z) {
        if (x < 0 || x >= SIZE || y < 0 || y >= SIZE || z < 0 || z >= SIZE) return null;
        return blocks[x][y][z];
    }

    public void setBlock(int x, int y, int z, CrystalBlock block) {
        if (x < 0 || x >= SIZE || y < 0 || y >= SIZE || z < 0 || z >= SIZE) return;
        blocks[x][y][z] = block;
        dirty = true;
        if (generated) {
            playerModified[x][y][z] = true;
        }
    }

    private boolean isNeighborSolid(int x, int y, int z) {
        // Inside this chunk
        if (x >= 0 && x < SIZE && y >= 0 && y < SIZE && z >= 0 && z < SIZE) {
            CrystalBlock b = blocks[x][y][z];
            if (b == null) return false;
            // Leaves are transparent — don't hide adjacent faces
            return b.shape.texCategory != 8;
        }
        // Outside - assume not solid (renders the face)
        return false;
    }

    public void buildMesh() {
        if (!dirty) return;

        if (mesh != null) {
            mesh.cleanup();
            mesh = null;
        }

        MeshBuilder builder = new MeshBuilder();
        int worldOffsetX = chunkX * SIZE;
        int worldOffsetY = chunkY * SIZE;
        int worldOffsetZ = chunkZ * SIZE;

        for (int x = 0; x < SIZE; x++) {
            for (int y = 0; y < SIZE; y++) {
                for (int z = 0; z < SIZE; z++) {
                    CrystalBlock block = blocks[x][y][z];
                    if (block == null) continue;

                    // Check which faces are visible (neighbor is air or transparent)
                    boolean[] visible = new boolean[6];
                    if (block.shape.texCategory == 8) {
                        // Leaves: show all faces (transparent block)
                        for (int f = 0; f < 6; f++) visible[f] = true;
                    } else {
                        visible[MeshBuilder.FACE_FRONT]  = !isNeighborSolid(x, y, z + 1); // +Z
                        visible[MeshBuilder.FACE_BACK]   = !isNeighborSolid(x, y, z - 1); // -Z
                        visible[MeshBuilder.FACE_TOP]    = !isNeighborSolid(x, y + 1, z); // +Y
                        visible[MeshBuilder.FACE_BOTTOM] = !isNeighborSolid(x, y - 1, z); // -Y
                        visible[MeshBuilder.FACE_RIGHT]  = !isNeighborSolid(x + 1, y, z); // +X
                        visible[MeshBuilder.FACE_LEFT]   = !isNeighborSolid(x - 1, y, z); // -X
                    }

                    // Compute vertical AO: check how many solid blocks are above
                    float aoShade = 1.0f;
                    for (int dy = 1; dy <= 4; dy++) {
                        if (isNeighborSolid(x, y + dy, z)) {
                            aoShade *= 0.85f;
                        } else {
                            break;
                        }
                    }

                    builder.addCube(block,
                        worldOffsetX + x,
                        worldOffsetY + y,
                        worldOffsetZ + z,
                        visible,
                        aoShade
                    );
                }
            }
        }

        mesh = builder.build();
        dirty = false;
    }

    public Mesh getMesh() {
        return mesh;
    }

    public boolean isDirty() { return dirty; }
    public void markDirty() { dirty = true; }
    public int getChunkX() { return chunkX; }
    public int getChunkY() { return chunkY; }
    public int getChunkZ() { return chunkZ; }

    public boolean isDecorated() { return decorated; }
    public void setDecorated(boolean d) { decorated = d; }

    public boolean isGenerated() { return generated; }
    public void setGenerated(boolean g) { generated = g; }

    public boolean hasModifications() {
        for (int x = 0; x < SIZE; x++)
            for (int y = 0; y < SIZE; y++)
                for (int z = 0; z < SIZE; z++)
                    if (playerModified[x][y][z]) return true;
        return false;
    }

    public boolean isModified(int x, int y, int z) { return playerModified[x][y][z]; }
    public CrystalBlock[][][] getBlocks() { return blocks; }

    public void cleanup() {
        if (mesh != null) {
            mesh.cleanup();
            mesh = null;
        }
    }
}


