// ===== src/main/java/com/danigt/world/TerrainGenerator.java =====
package com.danigt.world;

import com.danigt.math.Noise;
import org.joml.Vector3f;

import java.util.Random;

public class TerrainGenerator {

    private final Noise heightNoise;
    private final Noise caveNoise;
    private final Noise biomeNoise;
    private final Noise moistureNoise;
    private final long seed;

    private static final int SEA_LEVEL = 32;

    public TerrainGenerator(long seed) {
        this.seed = seed;
        this.heightNoise = new Noise(seed);
        this.caveNoise = new Noise(seed + 1);
        this.biomeNoise = new Noise(seed + 2);
        this.moistureNoise = new Noise(seed + 3);
    }

    /** Determine the biome at a given world XZ position */
    public Biome getBiome(int worldX, int worldZ) {
        double temp = biomeNoise.octaveNoise2D(worldX * 0.003 + 500, worldZ * 0.003 + 500, 2, 0.5);
        double moisture = moistureNoise.octaveNoise2D(worldX * 0.004, worldZ * 0.004, 3, 0.5);
        double biome = biomeNoise.octaveNoise2D(worldX * 0.005, worldZ * 0.005, 3, 0.5);

        // Frozen biomes first (coldest)
        if (temp < -0.4) {
            return Biome.FROZEN_TUNDRA;
        }

        // Volcanic wastes: hot + dry
        if (moisture < -0.3 && temp > 0.2) {
            return Biome.VOLCANIC_WASTES;
        }

        // Desert: dry + warm
        if (moisture < -0.1 && temp > 0.0) {
            return Biome.DESERT;
        }

        // Wet biomes
        if (moisture > 0.3 && temp > 0.0) {
            return Biome.CRYSTAL_FIELDS;
        }

        if (moisture > 0.3 && temp > -0.2) {
            return Biome.MUSHROOM_GROVE;
        }

        // Enchanted forest: moderate moisture, not too cold
        if (moisture > 0.1 && temp > -0.2 && biome > 0.1) {
            return Biome.ENCHANTED_FOREST;
        }

        return Biome.PLAINS;
    }

    public void generateChunk(Chunk chunk) {
        int cx = chunk.getChunkX() * Chunk.SIZE;
        int cy = chunk.getChunkY() * Chunk.SIZE;
        int cz = chunk.getChunkZ() * Chunk.SIZE;

        for (int x = 0; x < Chunk.SIZE; x++) {
            for (int z = 0; z < Chunk.SIZE; z++) {
                int worldX = cx + x;
                int worldZ = cz + z;

                double h = heightNoise.octaveNoise2D(worldX * 0.01, worldZ * 0.01, 5, 0.5);
                Biome biome = getBiome(worldX, worldZ);

                // Height varies by biome
                int surfaceY;
                switch (biome) {
                    case VOLCANIC_WASTES:
                        // More rugged terrain
                        surfaceY = (int) (SEA_LEVEL + h * 25);
                        break;
                    case FROZEN_TUNDRA:
                        // Flatter
                        surfaceY = (int) (SEA_LEVEL + h * 12);
                        break;
                    case ENCHANTED_FOREST:
                        // Hilly
                        surfaceY = (int) (SEA_LEVEL + h * 22);
                        break;
                    case CRYSTAL_FIELDS:
                        // Rolling hills
                        surfaceY = (int) (SEA_LEVEL + h * 18);
                        break;
                    case DESERT:
                        // Gentle dunes
                        surfaceY = (int) (SEA_LEVEL + h * 14);
                        break;
                    default:
                        surfaceY = (int) (SEA_LEVEL + h * 20);
                        break;
                }

                for (int y = 0; y < Chunk.SIZE; y++) {
                    int worldY = cy + y;

                    if (worldY > surfaceY) continue;
                    if (worldY < 0) continue;

                    // Cave carving
                    if (worldY > 2) {
                        double cave = caveNoise.noise3D(worldX * 0.05, worldY * 0.05, worldZ * 0.05);
                        if (cave > 0.35) continue;
                    }

                    int depth = surfaceY - worldY;
                    CrystalShape shape;

                    if (worldY <= 1) {
                        shape = CrystalShape.BEDROCK;
                    } else if (depth == 0) {
                        // Surface block by biome
                        shape = getSurfaceBlock(biome);
                    } else if (depth < 4) {
                        // Subsurface
                        shape = getSubsurfaceBlock(biome, depth);
                    } else {
                        // Underground: stone variants and ores
                        shape = getUndergroundBlock(biome, worldX, worldY, worldZ);
                    }

                    chunk.setBlock(x, y, z, new CrystalBlock(shape, shape.defaultColor));
                }
            }
        }
    }

    private CrystalShape getSurfaceBlock(Biome biome) {
        switch (biome) {
            case FROZEN_TUNDRA:     return CrystalShape.SNOW;
            case DESERT:            return CrystalShape.SAND;
            case VOLCANIC_WASTES:   return CrystalShape.NETHERRACK;
            case MUSHROOM_GROVE:    return CrystalShape.DIRT; // mycelium-like
            default:                return CrystalShape.GRASS;
        }
    }

    private CrystalShape getSubsurfaceBlock(Biome biome, int depth) {
        switch (biome) {
            case DESERT:
                return depth < 3 ? CrystalShape.SAND : CrystalShape.SANDSTONE;
            case VOLCANIC_WASTES:
                return depth < 2 ? CrystalShape.NETHERRACK : CrystalShape.OBSIDIAN;
            case FROZEN_TUNDRA:
                return CrystalShape.DIRT;
            default:
                return CrystalShape.DIRT;
        }
    }

    private CrystalShape getUndergroundBlock(Biome biome, int worldX, int worldY, int worldZ) {
        double stoneVar = biomeNoise.noise3D(worldX * 0.07, worldY * 0.07, worldZ * 0.07);
        CrystalShape shape;

        if (biome == Biome.VOLCANIC_WASTES && stoneVar > 0.5) {
            shape = CrystalShape.OBSIDIAN;
        } else if (stoneVar > 0.4 && stoneVar < 0.5) {
            shape = CrystalShape.GRANITE;
        } else if (stoneVar > 0.5 && stoneVar < 0.6) {
            shape = CrystalShape.DIORITE;
        } else if (stoneVar > 0.6 && stoneVar < 0.7) {
            shape = CrystalShape.ANDESITE;
        } else {
            shape = CrystalShape.STONE;
        }

        // Gravel pockets
        double gravelNoise = caveNoise.noise3D(worldX * 0.08 + 100, worldY * 0.08, worldZ * 0.08);
        if (gravelNoise > 0.55 && worldY < SEA_LEVEL - 5) {
            shape = CrystalShape.GRAVEL;
        }

        // Ore generation
        double ore = biomeNoise.noise3D(worldX * 0.1, worldY * 0.1, worldZ * 0.1);
        if (ore > 0.55 && worldY < SEA_LEVEL - 5) {
            if (worldY < 16 && ore > 0.68) {
                shape = CrystalShape.DIAMOND_ORE;
            } else if (worldY < 16 && ore > 0.66) {
                shape = CrystalShape.EMERALD_ORE;
            } else if (worldY < 32 && ore > 0.64) {
                shape = CrystalShape.GOLD_ORE;
            } else if (worldY < 32 && ore > 0.62) {
                shape = CrystalShape.REDSTONE_ORE;
            } else if (worldY < 32 && ore > 0.60) {
                shape = CrystalShape.LAPIS_ORE;
            } else if (ore > 0.58) {
                shape = CrystalShape.IRON_ORE;
            } else {
                shape = CrystalShape.COAL_ORE;
            }
        }

        // Volcanic: glowstone veins underground
        if (biome == Biome.VOLCANIC_WASTES) {
            double glow = caveNoise.noise3D(worldX * 0.12, worldY * 0.12 + 200, worldZ * 0.12);
            if (glow > 0.62) {
                shape = CrystalShape.GLOWSTONE;
            }
        }

        return shape;
    }

    /**
     * Decorate a chunk with trees and biome-specific features.
     */
    public void decorateChunk(Chunk chunk, World world) {
        int cx = chunk.getChunkX() * Chunk.SIZE;
        int cy = chunk.getChunkY() * Chunk.SIZE;
        int cz = chunk.getChunkZ() * Chunk.SIZE;

        Random rng = new Random(seed ^ ((long)cx * 341873128712L + (long)cz * 132897987541L));

        for (int x = 0; x < Chunk.SIZE; x++) {
            for (int z = 0; z < Chunk.SIZE; z++) {
                int worldX = cx + x;
                int worldZ = cz + z;

                double h = heightNoise.octaveNoise2D(worldX * 0.01, worldZ * 0.01, 5, 0.5);
                Biome biome = getBiome(worldX, worldZ);

                int surfaceY;
                switch (biome) {
                    case VOLCANIC_WASTES: surfaceY = (int)(SEA_LEVEL + h * 25); break;
                    case FROZEN_TUNDRA: surfaceY = (int)(SEA_LEVEL + h * 12); break;
                    case ENCHANTED_FOREST: surfaceY = (int)(SEA_LEVEL + h * 22); break;
                    case CRYSTAL_FIELDS: surfaceY = (int)(SEA_LEVEL + h * 18); break;
                    case DESERT: surfaceY = (int)(SEA_LEVEL + h * 14); break;
                    default: surfaceY = (int)(SEA_LEVEL + h * 20); break;
                }

                int localSurfaceY = surfaceY - cy;
                if (localSurfaceY < 0 || localSurfaceY >= Chunk.SIZE) continue;

                CrystalBlock surface = chunk.getBlock(x, localSurfaceY, z);
                if (surface == null) continue;

                // Biome-specific decorations
                switch (biome) {
                    case CRYSTAL_FIELDS:
                        if (surface.shape == CrystalShape.GRASS) {
                            // Crystal columns (rare)
                            if (rng.nextInt(200) == 0) {
                                placeCrystalColumn(world, worldX, surfaceY, worldZ, rng);
                            }
                            // Trees (normal rate)
                            if (rng.nextInt(40) == 0) {
                                placeTree(world, worldX, surfaceY, worldZ, rng,
                                    CrystalShape.BIRCH_LOG, CrystalShape.BIRCH_LEAVES, 4, 6);
                            }
                        }
                        break;

                    case MUSHROOM_GROVE:
                        if (surface.shape == CrystalShape.DIRT) {
                            // Giant mushrooms
                            if (rng.nextInt(25) == 0) {
                                placeGiantMushroom(world, worldX, surfaceY, worldZ, rng);
                            }
                        }
                        break;

                    case ENCHANTED_FOREST:
                        if (surface.shape == CrystalShape.GRASS) {
                            // Dense, tall magical trees
                            if (rng.nextInt(18) == 0) {
                                placeEnchantedTree(world, worldX, surfaceY, worldZ, rng);
                            }
                        }
                        break;

                    case VOLCANIC_WASTES:
                        if (surface.shape == CrystalShape.NETHERRACK) {
                            // Obsidian pillars
                            if (rng.nextInt(80) == 0) {
                                placeObsidianPillar(world, worldX, surfaceY, worldZ, rng);
                            }
                        }
                        break;

                    case FROZEN_TUNDRA:
                        if (surface.shape == CrystalShape.SNOW) {
                            // Ice columns
                            if (rng.nextInt(150) == 0) {
                                placeIceColumn(world, worldX, surfaceY, worldZ, rng);
                            }
                            // Sparse spruce trees
                            if (rng.nextInt(60) == 0) {
                                placeTree(world, worldX, surfaceY, worldZ, rng,
                                    CrystalShape.SPRUCE_LOG, CrystalShape.SPRUCE_LEAVES, 5, 8);
                            }
                        }
                        break;

                    case PLAINS:
                        if (surface.shape == CrystalShape.GRASS) {
                            if (rng.nextInt(40) == 0) {
                                double temp = biomeNoise.octaveNoise2D(worldX * 0.003 + 500, worldZ * 0.003 + 500, 2, 0.5);
                                CrystalShape logType, leafType;
                                if (temp < -0.2) {
                                    logType = CrystalShape.SPRUCE_LOG;
                                    leafType = CrystalShape.SPRUCE_LEAVES;
                                } else if (rng.nextFloat() > 0.7) {
                                    logType = CrystalShape.BIRCH_LOG;
                                    leafType = CrystalShape.BIRCH_LEAVES;
                                } else {
                                    logType = CrystalShape.OAK_LOG;
                                    leafType = CrystalShape.OAK_LEAVES;
                                }
                                placeTree(world, worldX, surfaceY, worldZ, rng, logType, leafType, 4, 6);
                            }
                        }
                        break;

                    case DESERT:
                        // No trees in desert
                        break;
                }
            }
        }
    }

    private void placeTree(World world, int wx, int surfaceY, int wz, Random rng,
                           CrystalShape logType, CrystalShape leafType, int minH, int maxH) {
        int trunkH = minH + rng.nextInt(maxH - minH + 1);
        for (int ty = 1; ty <= trunkH; ty++) {
            world.setBlock(wx, surfaceY + ty, wz, new CrystalBlock(logType, logType.defaultColor));
        }
        int topY = surfaceY + trunkH;
        for (int lx = -2; lx <= 2; lx++) {
            for (int lz = -2; lz <= 2; lz++) {
                for (int ly = -1; ly <= 2; ly++) {
                    if (Math.abs(lx) + Math.abs(ly) + Math.abs(lz) > 3) continue;
                    int bx = wx + lx, by = topY + ly, bz = wz + lz;
                    if (!world.isSolid(bx, by, bz)) {
                        world.setBlock(bx, by, bz, new CrystalBlock(leafType, leafType.defaultColor));
                    }
                }
            }
        }
    }

    private void placeCrystalColumn(World world, int wx, int surfaceY, int wz, Random rng) {
        // 2-5 block tall crystal pillar
        int height = 2 + rng.nextInt(4);
        CrystalShape[] crystals = {CrystalShape.DIAMOND_BLOCK, CrystalShape.EMERALD_BLOCK, CrystalShape.LAPIS_BLOCK};
        CrystalShape crystal = crystals[rng.nextInt(crystals.length)];
        for (int y = 1; y <= height; y++) {
            world.setBlock(wx, surfaceY + y, wz, new CrystalBlock(crystal, crystal.defaultColor));
        }
        // Glowstone cap
        world.setBlock(wx, surfaceY + height + 1, wz,
            new CrystalBlock(CrystalShape.GLOWSTONE, CrystalShape.GLOWSTONE.defaultColor));
    }

    private void placeGiantMushroom(World world, int wx, int surfaceY, int wz, Random rng) {
        // Short thick trunk (2-4 blocks), wide cap
        int trunkH = 2 + rng.nextInt(3);
        for (int ty = 1; ty <= trunkH; ty++) {
            world.setBlock(wx, surfaceY + ty, wz,
                new CrystalBlock(CrystalShape.SPRUCE_LOG, new Vector3f(0.75f, 0.72f, 0.65f)));
        }
        // Cap: flat disc of red or brown wool
        boolean red = rng.nextBoolean();
        CrystalShape capBlock = red ? CrystalShape.RED_WOOL : CrystalShape.ORANGE_WOOL;
        int topY = surfaceY + trunkH + 1;
        for (int lx = -2; lx <= 2; lx++) {
            for (int lz = -2; lz <= 2; lz++) {
                if (Math.abs(lx) == 2 && Math.abs(lz) == 2) continue; // round corners
                if (!world.isSolid(wx + lx, topY, wz + lz)) {
                    world.setBlock(wx + lx, topY, wz + lz,
                        new CrystalBlock(capBlock, capBlock.defaultColor));
                }
            }
        }
        // White dots on red mushroom
        if (red) {
            if (!world.isSolid(wx, topY + 1, wz)) {
                world.setBlock(wx, topY + 1, wz,
                    new CrystalBlock(CrystalShape.WHITE_WOOL, CrystalShape.WHITE_WOOL.defaultColor));
            }
        }
    }

    private void placeEnchantedTree(World world, int wx, int surfaceY, int wz, Random rng) {
        // Taller trees with purple/magical leaves mixed in
        int trunkH = 6 + rng.nextInt(4);
        for (int ty = 1; ty <= trunkH; ty++) {
            world.setBlock(wx, surfaceY + ty, wz,
                new CrystalBlock(CrystalShape.OAK_LOG, CrystalShape.OAK_LOG.defaultColor));
        }
        int topY = surfaceY + trunkH;
        // Larger canopy
        for (int lx = -3; lx <= 3; lx++) {
            for (int lz = -3; lz <= 3; lz++) {
                for (int ly = -2; ly <= 3; ly++) {
                    if (Math.abs(lx) + Math.abs(ly) + Math.abs(lz) > 4) continue;
                    int bx = wx + lx, by = topY + ly, bz = wz + lz;
                    if (!world.isSolid(bx, by, bz)) {
                        // Mix purple wool and oak leaves
                        CrystalShape leaf;
                        if (rng.nextFloat() < 0.3f) {
                            leaf = CrystalShape.PURPLE_WOOL;
                        } else {
                            leaf = CrystalShape.OAK_LEAVES;
                        }
                        world.setBlock(bx, by, bz, new CrystalBlock(leaf, leaf.defaultColor));
                    }
                }
            }
        }
        // Glowstone accent at top
        world.setBlock(wx, topY + 3, wz,
            new CrystalBlock(CrystalShape.GLOWSTONE, CrystalShape.GLOWSTONE.defaultColor));
    }

    private void placeObsidianPillar(World world, int wx, int surfaceY, int wz, Random rng) {
        int height = 4 + rng.nextInt(8);
        for (int ty = 1; ty <= height; ty++) {
            world.setBlock(wx, surfaceY + ty, wz,
                new CrystalBlock(CrystalShape.OBSIDIAN, CrystalShape.OBSIDIAN.defaultColor));
        }
        // Glowing top
        world.setBlock(wx, surfaceY + height + 1, wz,
            new CrystalBlock(CrystalShape.GLOWSTONE, CrystalShape.GLOWSTONE.defaultColor));
    }

    private void placeIceColumn(World world, int wx, int surfaceY, int wz, Random rng) {
        int height = 3 + rng.nextInt(5);
        for (int ty = 1; ty <= height; ty++) {
            world.setBlock(wx, surfaceY + ty, wz,
                new CrystalBlock(CrystalShape.GLASS, new Vector3f(0.70f, 0.85f, 0.95f)));
        }
        // Diamond block at base for crystal effect
        world.setBlock(wx, surfaceY + 1, wz,
            new CrystalBlock(CrystalShape.DIAMOND_BLOCK, CrystalShape.DIAMOND_BLOCK.defaultColor));
    }
}


