package com.danigt.world;

import java.util.*;

public class World {

    private final Map<Long, Chunk> chunks = new HashMap<>();
    private final TerrainGenerator generator;
    private final int renderDistance;

    private final long seed;
    private String worldName;

    public World(long seed, int renderDistance) {
        this.seed = seed;
        this.generator = new TerrainGenerator(seed);
        this.renderDistance = renderDistance;
    }

    public long getSeed() { return seed; }
    public String getWorldName() { return worldName; }
    public void setWorldName(String name) { this.worldName = name; }
    public TerrainGenerator getGenerator() { return generator; }

    public void update(float playerX, float playerY, float playerZ) {
        int pcx = Math.floorDiv((int) Math.floor(playerX), Chunk.SIZE);
        int pcy = Math.floorDiv((int) Math.floor(playerY), Chunk.SIZE);
        int pcz = Math.floorDiv((int) Math.floor(playerZ), Chunk.SIZE);

        // Pass 1: Generate terrain for all new chunks (no trees yet)
        for (int x = pcx - renderDistance; x <= pcx + renderDistance; x++) {
            for (int y = Math.max(pcy - 3, 0); y <= Math.max(pcy + 3, 4); y++) {
                for (int z = pcz - renderDistance; z <= pcz + renderDistance; z++) {
                    long key = chunkKey(x, y, z);
                    if (!chunks.containsKey(key)) {
                        Chunk chunk = new Chunk(x, y, z);
                        generator.generateChunk(chunk);
                        chunks.put(key, chunk);
                    }
                }
            }
        }

        // Pass 2: Decorate undecorated chunks (trees) — neighbors exist so cross-chunk works
        for (int x = pcx - renderDistance; x <= pcx + renderDistance; x++) {
            for (int y = Math.max(pcy - 3, 0); y <= Math.max(pcy + 3, 4); y++) {
                for (int z = pcz - renderDistance; z <= pcz + renderDistance; z++) {
                    Chunk chunk = chunks.get(chunkKey(x, y, z));
                    if (chunk != null && !chunk.isDecorated()) {
                        // Only decorate if the chunk above also exists (for tree tops)
                        if (chunks.containsKey(chunkKey(x, y + 1, z))) {
                            generator.decorateChunk(chunk, this);
                            chunk.setDecorated(true);
                            chunk.setGenerated(true);
                            // Load saved block modifications
                            if (worldName != null) {
                                WorldSaveManager.applyChunkModifications(chunk, worldName);
                            }
                        }
                    }
                }
            }
        }

        // Unload distant chunks
        chunks.entrySet().removeIf(entry -> {
            Chunk c = entry.getValue();
            if (Math.abs(c.getChunkX() - pcx) > renderDistance + 2 ||
                Math.abs(c.getChunkZ() - pcz) > renderDistance + 2 ||
                Math.abs(c.getChunkY() - pcy) > 6) {
                // Save modified chunks before unloading
                if (worldName != null && c.hasModifications()) {
                    WorldSaveManager.saveChunk(c, worldName);
                }
                c.cleanup();
                return true;
            }
            return false;
        });

        // Rebuild dirty meshes
        for (Chunk chunk : chunks.values()) {
            if (chunk.isDirty()) {
                chunk.buildMesh();
            }
        }
    }

    public CrystalBlock getBlock(int x, int y, int z) {
        int cx = Math.floorDiv(x, Chunk.SIZE);
        int cy = Math.floorDiv(y, Chunk.SIZE);
        int cz = Math.floorDiv(z, Chunk.SIZE);
        Chunk chunk = chunks.get(chunkKey(cx, cy, cz));
        if (chunk == null) return null;
        return chunk.getBlock(Math.floorMod(x, Chunk.SIZE), Math.floorMod(y, Chunk.SIZE), Math.floorMod(z, Chunk.SIZE));
    }

    public void setBlock(int x, int y, int z, CrystalBlock block) {
        int cx = Math.floorDiv(x, Chunk.SIZE);
        int cy = Math.floorDiv(y, Chunk.SIZE);
        int cz = Math.floorDiv(z, Chunk.SIZE);
        Chunk chunk = chunks.get(chunkKey(cx, cy, cz));
        if (chunk == null) return;
        chunk.setBlock(Math.floorMod(x, Chunk.SIZE), Math.floorMod(y, Chunk.SIZE), Math.floorMod(z, Chunk.SIZE), block);
    }

    public void removeBlock(int x, int y, int z) {
        setBlock(x, y, z, null);
    }

    public Collection<Chunk> getLoadedChunks() {
        return chunks.values();
    }

    public boolean isSolid(int x, int y, int z) {
        return getBlock(x, y, z) != null;
    }

    public void cleanup() {
        for (Chunk chunk : chunks.values()) {
            chunk.cleanup();
        }
        chunks.clear();
    }

    /**
     * Collision-free chunk key. Packs 3 ints into a long with no overlap.
     * Supports x,z in [-1048576, 1048575] and y in [-512, 511].
     */
    private static long chunkKey(int x, int y, int z) {
        long lx = x & 0x1FFFFFL;   // 21 bits
        long ly = y & 0x7FFL;       // 11 bits
        long lz = z & 0x1FFFFFL;   // 21 bits
        return lx | (ly << 21) | (lz << 32);
    }
}


