package com.danigt.world;

import org.joml.Vector3f;

public class WorldRaycaster {

    public static class HitResult {
        public final int x, y, z;         // block hit
        public final int nx, ny, nz;       // face normal (adjacent position for placement)
        public final float distance;

        public HitResult(int x, int y, int z, int nx, int ny, int nz, float distance) {
            this.x = x; this.y = y; this.z = z;
            this.nx = nx; this.ny = ny; this.nz = nz;
            this.distance = distance;
        }
    }

    public static HitResult raycast(World world, Vector3f origin, Vector3f direction, float maxDist) {
        // DDA voxel traversal
        float dx = direction.x, dy = direction.y, dz = direction.z;

        int x = (int) Math.floor(origin.x);
        int y = (int) Math.floor(origin.y);
        int z = (int) Math.floor(origin.z);

        int stepX = dx > 0 ? 1 : -1;
        int stepY = dy > 0 ? 1 : -1;
        int stepZ = dz > 0 ? 1 : -1;

        float tDeltaX = Math.abs(dx) < 1e-10 ? Float.MAX_VALUE : Math.abs(1.0f / dx);
        float tDeltaY = Math.abs(dy) < 1e-10 ? Float.MAX_VALUE : Math.abs(1.0f / dy);
        float tDeltaZ = Math.abs(dz) < 1e-10 ? Float.MAX_VALUE : Math.abs(1.0f / dz);

        float tMaxX = tDeltaX * (dx > 0 ? (1 - (origin.x - x)) : (origin.x - x));
        float tMaxY = tDeltaY * (dy > 0 ? (1 - (origin.y - y)) : (origin.y - y));
        float tMaxZ = tDeltaZ * (dz > 0 ? (1 - (origin.z - z)) : (origin.z - z));

        int lastNX = 0, lastNY = 0, lastNZ = 0;
        float t = 0;

        for (int i = 0; i < (int)(maxDist * 2); i++) {
            if (world.isSolid(x, y, z)) {
                return new HitResult(x, y, z, lastNX, lastNY, lastNZ, t);
            }

            if (tMaxX < tMaxY) {
                if (tMaxX < tMaxZ) {
                    t = tMaxX;
                    x += stepX;
                    tMaxX += tDeltaX;
                    lastNX = -stepX; lastNY = 0; lastNZ = 0;
                } else {
                    t = tMaxZ;
                    z += stepZ;
                    tMaxZ += tDeltaZ;
                    lastNX = 0; lastNY = 0; lastNZ = -stepZ;
                }
            } else {
                if (tMaxY < tMaxZ) {
                    t = tMaxY;
                    y += stepY;
                    tMaxY += tDeltaY;
                    lastNX = 0; lastNY = -stepY; lastNZ = 0;
                } else {
                    t = tMaxZ;
                    z += stepZ;
                    tMaxZ += tDeltaZ;
                    lastNX = 0; lastNY = 0; lastNZ = -stepZ;
                }
            }

            if (t > maxDist) break;
        }

        return null;
    }
}


// ===== src/main/java/com/danigt/world/WorldSaveManager.java =====
package com.danigt.world;

import com.danigt.entity.Inventory;
import com.danigt.entity.Player;
import org.joml.Vector3f;

import java.io.*;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;

public class WorldSaveManager {

    private static final String SAVE_DIR = System.getProperty("user.home")
        + File.separator + ".crystalrealms" + File.separator + "saves" + File.separator;

    public static class WorldInfo {
        public String name;
        public long seed;
        public long timestamp;
        public WorldInfo(String name, long seed, long timestamp) {
            this.name = name; this.seed = seed; this.timestamp = timestamp;
        }
    }

    // === List Worlds ===

    public static List<WorldInfo> listWorlds() {
        List<WorldInfo> worlds = new ArrayList<>();
        File dir = new File(SAVE_DIR);
        if (!dir.exists()) return worlds;
        File[] folders = dir.listFiles(File::isDirectory);
        if (folders == null) return worlds;
        for (File folder : folders) {
            File worldDat = new File(folder, "world.dat");
            if (worldDat.exists()) {
                try (DataInputStream in = new DataInputStream(new FileInputStream(worldDat))) {
                    long seed = in.readLong();
                    String name = in.readUTF();
                    long timestamp = in.readLong();
                    worlds.add(new WorldInfo(name, seed, timestamp));
                } catch (IOException e) {
                    // Skip corrupt saves
                }
            }
        }
        worlds.sort((a, b) -> Long.compare(b.timestamp, a.timestamp));
        return worlds;
    }

    // === Save World ===

    public static void save(String worldName, World world, Player player) {
        File worldDir = new File(SAVE_DIR + worldName);
        worldDir.mkdirs();
        File chunksDir = new File(worldDir, "chunks");
        chunksDir.mkdirs();

        // world.dat
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream(new File(worldDir, "world.dat")))) {
            out.writeLong(world.getSeed());
            out.writeUTF(worldName);
            out.writeLong(System.currentTimeMillis());
        } catch (IOException e) {
            e.printStackTrace();
        }

        // player.dat
        savePlayer(new File(worldDir, "player.dat"), player);

        // Save all modified chunks
        for (Chunk chunk : world.getLoadedChunks()) {
            if (chunk.hasModifications()) {
                saveChunk(chunk, worldName);
            }
        }
    }

    private static void savePlayer(File file, Player player) {
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream(file))) {
            out.writeFloat(player.position.x);
            out.writeFloat(player.position.y);
            out.writeFloat(player.position.z);
            out.writeFloat(player.yaw);
            out.writeFloat(player.pitch);
            out.writeInt(player.health);
            out.writeFloat(player.stamina);
            out.writeBoolean(player.creative);
            out.writeBoolean(player.flying);
            out.writeInt(player.selectedSlot);

            // Hotbar
            for (int i = 0; i < Player.HOTBAR_SIZE; i++) {
                if (player.hotbar[i] != null) {
                    out.writeBoolean(true);
                    out.writeInt(player.hotbar[i].ordinal());
                } else {
                    out.writeBoolean(false);
                }
            }

            // Inventory
            for (int i = 0; i < Inventory.SIZE; i++) {
                Inventory.Slot slot = player.inventory.getSlot(i);
                if (!slot.isEmpty()) {
                    out.writeBoolean(true);
                    out.writeInt(slot.shape.ordinal());
                    out.writeInt(slot.count);
                } else {
                    out.writeBoolean(false);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void saveChunk(Chunk chunk, String worldName) {
        File chunksDir = new File(SAVE_DIR + worldName + File.separator + "chunks");
        chunksDir.mkdirs();
        String fileName = "chunk_" + chunk.getChunkX() + "_" + chunk.getChunkY() + "_" + chunk.getChunkZ() + ".dat";
        File file = new File(chunksDir, fileName);

        try (DataOutputStream out = new DataOutputStream(new FileOutputStream(file))) {
            out.writeInt(chunk.getChunkX());
            out.writeInt(chunk.getChunkY());
            out.writeInt(chunk.getChunkZ());

            // Count modified blocks
            int count = 0;
            CrystalBlock[][][] blocks = chunk.getBlocks();
            for (int x = 0; x < Chunk.SIZE; x++)
                for (int y = 0; y < Chunk.SIZE; y++)
                    for (int z = 0; z < Chunk.SIZE; z++)
                        if (chunk.isModified(x, y, z)) count++;

            out.writeInt(count);

            for (int x = 0; x < Chunk.SIZE; x++) {
                for (int y = 0; y < Chunk.SIZE; y++) {
                    for (int z = 0; z < Chunk.SIZE; z++) {
                        if (!chunk.isModified(x, y, z)) continue;
                        out.writeShort(x + y * 16 + z * 256);
                        CrystalBlock block = blocks[x][y][z];
                        if (block != null) {
                            out.writeBoolean(true);
                            out.writeInt(block.shape.ordinal());
                            out.writeFloat(block.color.x);
                            out.writeFloat(block.color.y);
                            out.writeFloat(block.color.z);
                        } else {
                            out.writeBoolean(false); // air (block was removed)
                        }
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // === Load World ===

    public static class WorldLoadResult {
        public long seed;
        public String name;
        public boolean hasPlayer;
        // Player data
        public float px, py, pz, yaw, pitch;
        public int health;
        public float stamina;
        public boolean creative, flying;
        public int selectedSlot;
        public CrystalShape[] hotbar = new CrystalShape[Player.HOTBAR_SIZE];
        public CrystalShape[] invShapes = new CrystalShape[Inventory.SIZE];
        public int[] invCounts = new int[Inventory.SIZE];
    }

    public static WorldLoadResult load(String worldName) {
        File worldDir = new File(SAVE_DIR + worldName);
        WorldLoadResult result = new WorldLoadResult();

        // world.dat
        File worldDat = new File(worldDir, "world.dat");
        if (!worldDat.exists()) return null;
        try (DataInputStream in = new DataInputStream(new FileInputStream(worldDat))) {
            result.seed = in.readLong();
            result.name = in.readUTF();
            in.readLong(); // timestamp
        } catch (IOException e) {
            return null;
        }

        // player.dat
        File playerDat = new File(worldDir, "player.dat");
        if (playerDat.exists()) {
            try (DataInputStream in = new DataInputStream(new FileInputStream(playerDat))) {
                result.hasPlayer = true;
                result.px = in.readFloat();
                result.py = in.readFloat();
                result.pz = in.readFloat();
                result.yaw = in.readFloat();
                result.pitch = in.readFloat();
                result.health = in.readInt();
                result.stamina = in.readFloat();
                result.creative = in.readBoolean();
                result.flying = in.readBoolean();
                result.selectedSlot = in.readInt();

                CrystalShape[] shapes = CrystalShape.values();
                for (int i = 0; i < Player.HOTBAR_SIZE; i++) {
                    if (in.readBoolean()) {
                        int ord = in.readInt();
                        if (ord >= 0 && ord < shapes.length) result.hotbar[i] = shapes[ord];
                    }
                }
                for (int i = 0; i < Inventory.SIZE; i++) {
                    if (in.readBoolean()) {
                        int ord = in.readInt();
                        int count = in.readInt();
                        if (ord >= 0 && ord < shapes.length) {
                            result.invShapes[i] = shapes[ord];
                            result.invCounts[i] = count;
                        }
                    }
                }
            } catch (IOException e) {
                result.hasPlayer = false;
            }
        }

        return result;
    }

    public static void applyChunkModifications(Chunk chunk, String worldName) {
        if (worldName == null) return;
        String fileName = "chunk_" + chunk.getChunkX() + "_" + chunk.getChunkY() + "_" + chunk.getChunkZ() + ".dat";
        File file = new File(SAVE_DIR + worldName + File.separator + "chunks" + File.separator + fileName);
        if (!file.exists()) return;

        CrystalShape[] shapes = CrystalShape.values();
        try (DataInputStream in = new DataInputStream(new FileInputStream(file))) {
            in.readInt(); // chunkX
            in.readInt(); // chunkY
            in.readInt(); // chunkZ
            int count = in.readInt();

            for (int i = 0; i < count; i++) {
                int packed = in.readUnsignedShort();
                int x = packed % 16;
                int y = (packed / 16) % 16;
                int z = packed / 256;
                boolean hasBlock = in.readBoolean();
                if (hasBlock) {
                    int ord = in.readInt();
                    float r = in.readFloat(), g = in.readFloat(), b = in.readFloat();
                    if (ord >= 0 && ord < shapes.length) {
                        chunk.setBlock(x, y, z, new CrystalBlock(shapes[ord], new Vector3f(r, g, b)));
                    }
                } else {
                    chunk.setBlock(x, y, z, null); // removed block
                }
            }
        } catch (IOException e) {
            // Corrupt chunk file, skip
        }
    }

    // === Delete World ===

    public static void deleteWorld(String worldName) {
        File worldDir = new File(SAVE_DIR + worldName);
        if (worldDir.exists()) {
            deleteRecursive(worldDir);
        }
    }

    private static void deleteRecursive(File file) {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) deleteRecursive(child);
            }
        }
        file.delete();
    }
